export default "s, \\\"O_NOFOLLOW\\\"):\\n        flags |= os.O_NOFOLLOW\\n    elif target.is_symlink():  # pragma: no cover \u2014 Windows-only branch\\n        msg = f\\\"Refusing to read through symlink: {target}\\\"\\n        raise PermissionError(msg)\\n    fd = os.open(str(target), flags)\\n    try:\\n        return os.read(fd, n)\\n    finally:\\n        os.close(fd)\\n\\n\\ndef _check_windows_portability(path: str) -> str | None:\\n    \\\"\\\"\\\"Return a human-readable error if the path has Windows-portability issues.\\n\\n    Why we run this on every host: paths that work on macOS/Linux can silently\\n    fail on Windows (reserved names, forbidden characters, trailing dot/space\\n    silently stripped by the OS). The agent should see the same structured\\n    error regardless of where the flow runs.\\n    \\\"\\\"\\\"\\n    # Use PureWindowsPath to parse separators consistently \u2014 it splits on both\\n    # `/` and `\\\\` and exposes drive markers as components ending in '\\\\'.\\n    for component in PureWindowsPath(path).parts:\\n        # Skip root markers ('\\\\\\\\', '/', 'C:\\\\\\\\') and relative markers ('.', '..')\\n        if component.endswith((\\\"\\\\\\\\\\\", \\\"/\\\")) or component in (\\\".\\\", \\\"..\\\"):\\n            continue\\n        # Reserved name (case-insensitive, with or without extension).\\n        stem = component.split(\\\".\\\", 1)[0].upper()\\n        if stem in _WINDOWS_RESERVED_NAMES:\\n            return f\\\"Path component {component!r} is a Windows reserved name\\\"\\n        # Forbidden characters in basename.\\n        bad = sorted(set(component) & _WINDOWS_FORBIDDEN_CHARS)\\n        if bad:\\n            return f\\\"Path component {component!r} contains forbidden character(s): {bad}\\\"\\n        # Trailing dot or space \u2014 Windows silently strips them.\\n        if component != component.rstrip(\\\". \\\"):\\n            return f\\\"Path component {component!r} has trailing dot or space (silently stripped on Windows)\\\"\\n    return None\\n\\n\\nclass _ReadFileArgs(BaseModel):\\n    path: str = Field(..., description=\\\"Path to the file, relative to the sandbox root.\\\")\\n    offset: int | None = Field(default=None, description=\\\"1-based line number to start reading from.\\\")\\n    limit: int | None = Field(default=None, description=\\\"Maximum number of lines to return.\\\")\\n\\n\\nclass _WriteFileArgs(BaseModel):\\n    path: str = Field(..., description=\\\"Path to the file, relative to the sandbox root.\\\")\\n    content: str = Field(..., description=\\\"Text content to write. Overwrites existing file.\\\")\\n\\n\\nclass _EditFileArgs(BaseModel):\\n    path: str = Field(..., description=\\\"Path to the file, relative to the sandbox root.\\\")\\n    old_string: str = Field(..., description=\\\"Exact string to replace.\\\")\\n    new_string: str = Field(..., description=\\\"Replacement string.\\\")\\n    replace_all: bool = Field(default=False, description=\\\"Replace every occurrence instead of failing on ambiguity.\\\")\\n\\n\\nclass _GlobSearchArgs(BaseModel):\\n    pattern: str = Field(..., description=\\\"Glob pattern, e.g. '**/*.py'.\\\")\\n    path: str | None = Field(default=None, description=\\\"Optional sub-directory to scope the search.\\\")\\n\\n\\nclass _GrepSearchArgs(BaseModel):\\n    pattern: str = Field(..., description=\\\"Pattern to match against file contents (literal substring by default).\\\")\\n    path: str | None = Field(default=None, description=\\\"Optional file or directory to scope the search.\\\")\\n    glob: str | None = Field(default=None, description=\\\"Optional glob filter, e.g. '*.py'.\\\")\\n    case_insensitive: bool = Field(default=False, description=\\\"If true, the pattern is matched case-insensitively.\\\")\\n    output_mode: str = Field(\\n        default=\\\"files_with_matches\\\",\\n        description=\\\"One of 'files_with_matches', 'content', 'count'.\\\",\\n    )\\n    is_regex: bool = Field(\\n        default=False,\\n        description=(\\n            \\\"Treat `pattern` as a Python regex. Disabled by default \u2014 when enabled, \\\"\\n            \\\"patterns are validated against catastrophic-backtracking shapes \\\"\\n            \\\"(rejecting e.g. `(a+)+` or `(.*)*`) and oversized lines are skipped.\\\"\\n        ),\\n    )\\n\\n\\nclass FileSystemToolComponent(Component):\\n    display_name = \\\"File System\\\"\\n    description = \\\"Sandboxed filesystem access for agents.\\\"\\n    icon = \\\"folder\\\"\\n    name = \\\"FileSystemTool\\\"\\n\\n    # Enables the \\\"Tool Mode\\\" toggle on the node header. When ON the framework\\n    # calls _get_tools() and emits a Toolset output that connects to an Agent's\\n    # \\\"Tools\\\" handle. When OFF, the JSON metadata output is the only handle.\\n    add_tool_output = True\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"root_path\\\",\\n            display_name=\\\"Workspace Sub-path\\\",\\n            required=False,\\n            value=\\\"\\\",\\n            info=(\\n                \\\"Sub-folder inside your sandboxed workspace. Leave empty to use the \\\"\\n                \\\"root of the workspace.\\\\n\\\\n\\\"\\n                \\\"Resolves under <BASE_DIR>/shared/<sub_path>/ when AUTO_LOGIN=True \\\"\\n                \\\"(single-user / desktop) or under <BASE_DIR>/users/<your-namespace>/<sub_path>/ \\\"\\n                \\\"when AUTO_LOGIN=False (multi-user, per-user isolation). \\\"\\n                \\\"BASE_DIR is operator-controlled via LANGFLOW_FS_TOOL_BASE_DIR.\\\"\\n            ),\\n        ),\\n        BoolInput(\\n            name=\\\"read_only\\\",\\n            display_name=\\\"Read Only\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"If true, write and edit operations are disabled.\\\",\\n        ),\\n        # Synthetic hidden input. Exists ONLY to make the \\\"Tool Mode\\\" toggle\\n        # appear on the node header \u2014 see frontend rule in\\n        # `src/frontend/src/CustomNodes/helpers/parameter-filtering.ts :: isHidden`\\n        # and the backend gate in `src/lfx/src/lfx/template/utils.py` (toggle\\n        # visibility = `any(input.tool_mode for input in inputs)`).\\n        # `show=False` keeps it hidden from the config UI; `tool_mode=True`\\n        # would otherwise hide a real input in tool mode (see same isHidden\\n        # rule), so we keep root_path / read_only WITHOUT tool_mode=True so\\n        # they remain user-editable when the toggle is on. _get_tools() ignores\\n        # this field \u2014 each StructuredTool has its own per-operation schema.\\n        StrInput(\\n            name=\\\"tool_mode_trigger\\\",\\n            display_name=\\\"\\\",\\n            show=False,\\n            tool_mode=True,\\n            required=False,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"JSON\\\",\\n            name=\\\"metadata\\\",\\n            method=\\\"build_metadata\\\",\\n            types=[\\\"Data\\\"],\\n        ),\\n    ]\\n\\n    def build_metadata(self) -> Data:\\n        \\\"\\\"\\\"Return introspective metadata about the sandbox. No file I/O.\\n\\n        Surfaces the live AUTO_LOGIN-driven layout so flow authors can see\\n        whether per-user scoping is active and where their files actually land\\n        without needing to grep env vars.\\n        \\\"\\\"\\\"\\n        registered = [\\\"read_file\\\", \\\"glob_search\\\", \\\"grep_search\\\"]\\n        if not self.read_only:\\n            registered.extend([\\\"write_file\\\", \\\"edit_file\\\"])\\n\\n        auto_login = self._resolve_auto_login()\\n        user_id = self._resolve_user_id()\\n        if auto_login:\\n            mode = \\\"shared\\\"\\n        elif user_id:\\n            mode = \\\"isolated\\\"\\n        else:\\n            mode = \\\"refused\\\"\\n\\n        # Best-effort effective_root resolution. We never raise from metadata \u2014\\n        # if the policy refuses the call (AUTO_LOGIN=False without user_id,\\n        # unwritable BASE_DIR, etc.) we surface the reason instead of crashing\\n        # the node preview / Agent build pipeline.\\n        effective_root: str | None\\n        resolution_error: str | None = None\\n        try:\\n            effective_root = str(self._validate_root())\\n        except Exception as exc:  # noqa: BLE001 \u2014 metadata must never raise\\n            effective_root = None\\n            resolution_error = str(exc) or exc.__class__.__name__\\n\\n        return Data(\\n            data={\\n                \\\"root_path\\\": self.root_path,\\n                \\\"read_only\\\": bool(self.read_only),\\n                \\\"tools_registered\\\": registered,\\n                \\\"auto_login\\\": auto_login,\\n                \\\"mode\\\": mode,\\n                \\\"effective_root\\\": effective_root,\\n                \\\"resolution_error\\\": resolution_error,\\n            }\\n        )\\n\\n    async def _get_tools(self) -> list[Tool]:\\n        \\\"\\\"\\\"Tool Mode entrypoint. Called by Component.to_toolkit().\\\"\\\"\\\"\\n        # Capture the bound user_id ONCE per build. Each StructuredTool closure\\n        # below re-checks the live ``self._user_id`` against this value at call\\n        # time, so a tool issued for user A cannot be invoked after the\\n        # component has been reused for user B (defense for L2 in the plan).\\n        bound_user_id = self._resolve_user_id()\\n        tools: list[Tool] = [\\n            self._make_read_tool(bound_user_id=bound_user_id),\\n            self._make_glob_tool(bound_user_id=bound_user_id),\\n            self._make_grep_tool(bound_user_id=bound_user_id),\\n        ]\\n        if not self.read_only:\\n            tools.append(self._make_write_tool(bound_user_id=bound_user_id))\\n            tools.append(self._make_edit_tool(bound_user_id=bound_user_id))\\n        return tools\\n\\n    def _user_binding_error(self, bound_user_id: str | None) -> dict | None:\\n        \\\"\\\"\\\"Return a structured error dict if the live user_id has shifted.\\n\\n        In shared mode (AUTO_LOGIN=True) user_id is not part of the security\\n        boundary, so the binding check is a no-op. In isolated mode we compare\\n        the captured user_id to the live one and refuse if they diverge \u2014\\n        defends against a worker pool reusing one component instance across\\n        sessions for different users.\\n        \\\"\\\"\\\"\\n        _, err = self._user_binding_check(bound_user_id)\\n        return err\\n\\n    def _user_binding_check(self, bound_user_id: str | None) -> tuple[str | None, dict | None]:\\n        \\\"\\\"\\\"Atomic capture of the user_id for the current invocation.\\n\\n        Returns ``(captured_user_id, error_or_none)``. The captured value is\\n        the SINGLE read of ``_resolve_user_id`` for this call; downstream\\n        path-resolution code MUST reuse it (via the ContextVar pin) instead\\n        of reading again \u2014 otherwise a mid-call mutation of ``self._user_id``\\n        would let a write land in a different user's namespace while this\\n        check still passed for the original user.\\n        \\\"\\\"\\\"\\n        # When force_isolation is set, every invocation MUST carry the user_id\\n        # that was captured at binding time \u2014 AUTO_LOGIN does not relax the\\n        # check here, otherwise the per-user root in _validate_root would be\\n        # reached with the wrong identity.\\n        if getattr(self, \\\"_force_isolation\\\", False):\\n            current = self._resolve_user_id()\\n            if current and current == bound_user_id:\\n                return current, None\\n            return None, {\\n                \\\"error\\\": (\\n                    \\\"tool/user-id mismatch: this tool was bound to a different user session and cannot be reused\\\"\\n                ),\\n            }\\n        if self._resolve_auto_login():\\n            return bound_user_id, None\\n        current = self._resolve_user_id()\\n        if current == bound_user_id:\\n            return current, None\\n        return None, {\\n            \\\"error\\\": (\\\"tool/user-id mismatch: this tool was bound to a different user session and cannot be reused\\\"),\\n        }\\n\\n    def _make_read_tool(self, *, bound_user_id: str | None) -> StructuredTool:\\n        def _run(path: str, offset: int | None = None, limit: int | None = None) -> str:\\n            captured, err = self._user_binding_check(bound_user_id)\\n            if err is not None:\\n                return json.dumps(err)\\n            token = _pinned_user_id_var.set(captured)\\n            try:\\n                return json.dumps(self._read_file(path, offset=offset, limit=limit))\\n            finally:\\n                _pinned_user_id_var.reset(token)\\n\\n        return StructuredTool.from_function(\\n            name=\\\"read_file\\\",\\n            description=(\\n                \\\"Read a text file from the sandboxed workspace. \\\"\\n                \\\"Returns content prefixed with line numbers plus metadata \\\"\\n                \\\"(total_lines, start_line, num_lines).\\\"\\n            ),\\n            func=_run,\\n            args_schema=_ReadFileArgs,\\n            tags=[\\\"read_file\\\"],\\n        )\\n\\n    def _make_write_tool(self, *, bound_user_id: str | None) -> StructuredTool:\\n        def _run(path: str, content: str) -> str:\\n            captured, err = self._user_binding_check(bound_user_id)\\n            if err is not None:\\n                return json.dumps(err)\\n            token = _pinned_user_id_var.set(captured)\\n            try:\\n                return json.dumps(self._write_file(path, content))\\n            finally:\\n                _pinned_user_id_var.reset(token)\\n\\n        return StructuredTool.from_function(\\n            name=\\\"write_file\\\",\\n            description=\\\"Create or overwrite a text file inside the sandboxed workspace.\\\",\\n            func=_run,\\n            args_schema=_WriteFileArgs,\\n            tags=[\\\"write_file\\\"],\\n        )\\n\\n    def _make_edit_tool(self, *, bound_user_id: str | None) -> StructuredTool:\\n        def _run(path: str, old_string: str, new_string: str, *, replace_all: bool = False) -> str:\\n            captured, err = self._user_binding_check(bound_user_id)\\n            if err is not None:\\n                return json.dumps(err)\\n            token = _pinned_user_id_var.set(captured)\\n            try:\\n                return json.dumps(\\n                    self._edit_file(path, old_string=old_string, new_string=new_string, replace_all=replace_all)\\n                )\\n            finally:\\n                _pinned_user_id_var.reset(token)\\n\\n        return StructuredTool.from_function(\\n            name=\\\"edit_file\\\",\\n            description=(\\n                \\\"Edit a text file by replacing an exact old_string with new_string. \\\"\\n                \\\"Fails on ambiguous matches unless replace_all=True.\\\"\\n            ),\\n            func=_run,\\n            args_schema=_EditFileArgs,\\n            tags=[\\\"edit_file\\\"],\\n        )\\n\\n    def _make_glob_tool(self, *, bound_user_id: str | None) -> StructuredTool:\\n        def _run(pattern: str, path: str | None = None) -> str:\\n            captured, err = self._user_binding_check(bound_user_id)\\n            if err is not None:\\n                return json.dumps(err)\\n            token = _pinned_user_id_var.set(captured)\\n            try:\\n                return json.dumps(self._glob_search(pattern, path=path))\\n            finally:\\n                _pinned_user_id_var.reset(token)\\n\\n        return StructuredTool.from_function(\\n            name=\\\"glob_search\\\",\\n            description=(\\n                \\\"List files matching a glob pattern inside the sandboxed workspace. \\\"\\n                f\\\"Results are truncated at {GLOB_RESULT_LIMIT} entries.\\\"\\n            ),\\n            func=_run,\\n            args_schema=_GlobSearchArgs,\\n            tags=[\\\"glob_search\\\"],\\n        )\\n\\n    def _make_grep_tool(self, *, bound_user_id: str | None) -> StructuredTool:\\n        def _run(\\n            pattern: str,\\n            path: str | None = None,\\n            glob: str | None = None,\\n            *,\\n            case_insensitive: bool = False,\\n            output_mode: str = \\\"files_with_matches\\\",\\n            is_regex: bool = False,\\n        ) -> str:\\n            captured, err = self._user_binding_check(bound_user_id)\\n            if err is not None:\\n                return json.dumps(err)\\n            token = _pinned_user_id_var.set(captured)\\n            try:\\n                return json.dumps(\\n                    self._grep_search(\\n                        pattern,\\n                        path=path,\\n                        glob=glob,\\n                        case_insensitive=case_insensitive,\\n                        output_mode=output_mode,\\n                        is_regex=is_regex,\\n                    )\\n                )\\n            finally:\\n                _pinned_user_id_var.reset(token)\\n\\n        return StructuredTool.from_function(\\n            name=\\\"grep_search\\\",\\n            description=(\\n                \\\"Search file contents. Default is literal substring match (safe for any pattern); \\\"\\n                \\\"set is_regex=True to opt into Python regex. Patterns with nested unbounded \\\"\\n                \\\"quantifiers (e.g. (a+)+) are rejected to prevent catastrophic backtracking. \\\"\\n                \\\"output_mode: 'files_with_matches' (default), 'content', or 'count'. \\\"\\n                f\\\"Content mode is capped at {GREP_LINE_LIMIT} lines.\\\"\\n            ),\\n            func=_run,\\n            args_schema=_GrepSearchArgs,\\n            tags=[\\\"grep_search\\\"],\\n        )\\n\\n    def _resolve_user_id(self) -> str | None:\\n        \\\"\\\"\\\"Best-effort lookup of the calling user's id.\\n\\n        The Component base class populates ``_user_id`` during instantiation,\\n        and the property cascades to ``self.graph.user_id``. In tests there is\\n        no graph; in scheduled/anonymous runs there is no user_id at all. We\\n        treat all of those as \\\"anonymous\\\" \u2014 the isolation mode decides what to\\n        do with that information.\\n\\n        Why we filter ``\\\"none\\\"`` / ``\\\"null\\\"``: Langflow's ``PlaceholderGraph``\\n        stringifies a missing user as ``\\\"None\\\"`` rather than the Python\\n        ``None`` value, so a naive truthiness check would mistake \\\"no user\\\" for\\n        a real user named \\\"None\\\" and create a spurious shared namespace.\\n\\n        L2 binding atomicity: when a tool invocation is in progress, the\\n        pinned ContextVar value takes precedence so every read inside the\\n        same call sees the user_id captured at the binding check \u2014 even if\\n        ``self._user_id`` is mutated mid-call by a reused component instance.\\n        \\\"\\\"\\\"\\n        pinned = _pinned_user_id_var.get()\\n        if pinned is not None:\\n            return pinned\\n        graph = getattr(self, \\\"graph\\\", None)\\n        candidates: list[object | None] = []\\n        # Serving-plane: an identified end user owns the files they write during their session, so\\n        # their id wins the sandbox namespace over the executing service account. None on editor /\\n        # anonymous / feature-off runs -> falls through to the SID exactly as before (strict BC).\\n        if graph is not None:\\n            candidates.append(getattr(graph, \\\"end_user_id\\\", None))\\n        candidates.append(getattr(self, \\\"_user_id\\\", None))\\n        if graph is not None:\\n            candidates.append(getattr(graph, \\\"user_id\\\", None))\\n\\n        for value in candidates:\\n            if value is None:\\n                continue\\n            cleaned = str(value).strip()\\n            if not cleaned or cleaned.lower() in {\\\"none\\\", \\\"null\\\"}:\\n                continue\\n            return cleaned\\n        return None\\n\\n    def _isolation_config(self) -> IsolationConfig:\\n        \\\"\\\"\\\"Read the on-disk layout config from the environment on every call.\\n\\n        Re-read intentionally: tests and live operators tweak env vars between\\n        runs; caching would create stale-config bugs that are painful to\\n        diagnose. The cost is a handful of dict lookups per tool call.\\n        \\\"\\\"\\\"\\n        return load_isolation_config(env=os.environ, default_config_dir=_default_config_dir())\\n\\n    def _resolve_auto_login(self) -> bool:\\n        \\\"\\\"\\\"Return AUTO_LOGIN from the live settings service.\\n\\n        Defaults to True when the settings service is unavailable (tests, very\\n        early bootstrap) \u2014 mirrors the platform-wide default and keeps the\\n        component usable in lightweight contexts. Tests can override this\\n        method per-instance to pin the desired mode.\\n        \\\"\\\"\\\"\\n        try:\\n            settings_service = get_settings_service()\\n        except Exception:  # noqa: BLE001 \u2014 service registry may not be ready\\n            return True\\n        if settings_service is None:\\n            return True\\n        try:\\n            return bool(settings_service.auth_settings.AUTO_LOGIN)\\n        except AttributeError:\\n            return True\\n\\n    def _validate_root(self) -> Path:\\n        \\\"\\\"\\\"Resolve and authorize the effective sandbox root.\\n\\n        Dispatch:\\n          - ``_force_isolation=True``    \u2192 <BASE>/users/<hash(user_id)>/<sub_path>\\n          - AUTO_LOGIN=True              \u2192 <BASE>/shared/<sub_path>\\n          - AUTO_LOGIN=False + user_id   \u2192 <BASE>/users/<hash(user_id)>/<sub_path>\\n          - any mode with no user_id     \u2192 PermissionError (caught by callers)\\n\\n        ``_force_isolation`` exists for callers that carry an authenticated\\n        user identity and need per-user isolation regardless of the global\\n        AUTO_LOGIN flag (e.g. the agentic file router + the agent's write\\n        tools). It defaults to False so other call sites keep their current\\n        AUTO_LOGIN-driven behavior unchanged.\\n        \\\"\\\"\\\"\\n        config = self._isolation_config()\\n\\n        if getattr(self, \\\"_force_isolation\\\", False):\\n            user_id = self._resolve_user_id()\\n            if not user_id:\\n                msg = \\\"FileSystemTool requires an authenticated user when _force_isolation is set\\\"\\n                raise PermissionError(msg)\\n            return self._isolated_user_root(config=config, user_id=user_id)\\n\\n        if self._resolve_auto_login():\\n            return self._shared_root(config=config)\\n\\n        user_id = self._resolve_user_id()\\n        if not user_id:\\n            msg = \\\"FileSystemTool requires an authenticated user when AUTO_LOGIN=False\\\"\\n            raise PermissionError(msg)\\n        return self._isolated_user_root(config=config, user_id=user_id)\\n\\n    def _shared_root(self, *, config: IsolationConfig) -> Path:\\n        \\\"\\\"\\\"Materialize ``<base>/shared/<sub_path>`` and verify the boundary.\\n\\n        Why a fixed ``shared/`` prefix (and not just ``base_dir`` directly):\\n        keeps the on-disk layout symmetric with isolated mode (``users/<hash>/``)\\n        so flipping AUTO_LOGIN at deploy time never mixes the two trees.\\n        \\\"\\\"\\\"\\n        shared_root = (config.base_dir / SHARED_NAMESPACE).resolve()\\n        try:\\n            shared_root.mkdir(parents=True, exist_ok=True)\\n        except OSError as exc:\\n            msg = (\\n                f\\\"Cannot create shared workspace at {shared_root}: \\\"\\n                f\\\"{exc.strerror or exc}. \\\"\\n                f\\\"Check that LANGFLOW_FS_TOOL_BASE_DIR ({config.base_dir}) is writable \\\"\\n                f\\\"by the Langflow process user.\\\"\\n            )\\n            raise PermissionError(msg) from exc\\n\\n        sub_raw = (self.root_path or \\\"\\\").strip()\\n        sub = sub_raw.lstrip(\\\"/\\\\\\\\\\\")\\n        candidate = (shared_root / sub).resolve() if sub else shared_root\\n        if not candidate.is_relative_to(shared_root):\\n            msg = f\\\"sub_path {self.root_path!r} escapes shared workspace\\\"\\n            raise PermissionError(msg)\\n        try:\\n            candidate.mkdir(parents=True, exist_ok=True)\\n        except OSError as exc:\\n            msg = f\\\"Cannot create sub-path {candidate}: {exc.strerror or exc}\\\"\\n            raise PermissionError(msg) from exc\\n        return candidate\\n\\n    def _isolated_user_root(self, *, config: IsolationConfig, user_id: str) -> Path:\\n        \\\"\\\"\\\"Materialize ``<base>/users/<hash(user_id)>/<sub_path>`` and verify the boundary.\\\"\\\"\\\"\\n        try:\\n            pepper = load_or_create_pepper(config.pepper_path)\\n        except OSError as exc:\\n            msg = (\\n                f\\\"Cannot access pepper file at {config.pepper_path}: \\\"\\n                f\\\"{exc.strerror or exc}. \\\"\\n                f\\\"Check that LANGFLOW_FS_TOOL_PEPPER_PATH points to a writable location.\\\"\\n            )\\n            raise PermissionError(msg) from exc\\n        namespace = compute_user_namespace(user_id, pepper=pepper)\\n        user_root = (config.base_dir / namespace).resolve()\\n        try:\\n            user_root.mkdir(parents=True, exist_ok=True)\\n        except OSError as exc:\\n            msg = (\\n                f\\\"Cannot create user namespace at {user_root}: \\\"\\n                f\\\"{exc.strerror or exc}. \\\"\\n                f\\\"Check that LANGFLOW_FS_TOOL_BASE_DIR ({config.base_dir}) is writable \\\"\\n                f\\\"by the Langflow process user.\\\"\\n            )\\n            raise PermissionError(msg) from exc\\n\\n        sub_raw = (self.root_path or \\\"\\\").strip()\\n        # Strip leading separators so absolute-looking sub_paths are pinned\\n        # under the user root rather than escaping to the host filesystem.\\n        sub = sub_raw.lstrip(\\\"/\\\\\\\\\\\")\\n        candidate = (user_root / sub).resolve() if sub else user_root\\n        if not candidate.is_relative_to(user_root):\\n            msg = f\\\"sub_path {self.root_path!r} escapes user namespace\\\"\\n            raise PermissionError(msg)\\n        try:\\n            candidate.mkdir(parents=True, exist_ok=True)\\n        except OSError as exc:\\n            msg = f\\\"Cannot create sub-path {candidate}: {exc.strerror or exc}\\\"\\n            raise PermissionError(msg) from exc\\n        return candidate\\n\\n    def _validate_path(self, path: str) -> Path:\\n        \\\"\\\"\\\"Resolve `path` relative to the sandbox root and reject any escape.\\n\\n        Why raise: internal helper for control flow; each tool operation catches\\n        PermissionError and translates it into a structured error for the agent.\\n        \\\"\\\"\\\"\\n        if \\\"\\\\x00\\\" in path:\\n            msg = \\\"Path contains NUL byte\\\"\\n            raise PermissionError(msg)\\n        if portability_error := _check_windows_portability(path):\\n            raise PermissionError(portability_error)\\n        # Block the reserved segments (`.lfsig` integrity hook, `.components`\\n        # registered-user-component store). We forbid traversal even by users\\n        # with valid credentials \u2014 agents and humans both \u2014 because the\\n        # privilege model depends on these directories being unreachable from\\n        # the public tool surface.\\n        # Compare case-insensitively: APFS and NTFS resolve `.LFSIG` to the\\n        # same directory as `.lfsig`, so a case-sensitive equality check\\n        # lets uppercase variants slip past the reservation on those\\n        # filesystems. `casefold` is the locale-aware lowercase used for\\n        # caseless string comparison \u2014 broader than `.lower()`.\\n        reserved_folds = {seg.casefold() for seg in RESERVED_SEGMENTS}\\n        for part in PureWindowsPath(path).parts:\\n            folded = part.casefold()\\n            if folded in reserved_folds:\\n                # Surface the canonical segment name (with leading dot) so\\n                # error messages stay stable across modes and OSes.\\n                canonical = next(seg for seg in RESERVED_SEGMENTS if seg.casefold() == folded)\\n                msg = f\\\"Path component {canonical!r} is reserved\\\"\\n                raise PermissionError(msg)\\n        if deny_error := _check_deny_list(path):\\n            raise PermissionError(deny_error)\\n        root_resolved = self._validate_root()\\n        candidate = (root_resolved / path).resolve()\\n        if not candidate.is_relative_to(root_resolved):\\n            msg = f\\\"Path escapes workspace boundary: {path}\\\"\\n            raise PermissionError(msg)\\n        # Re-check the resolved name: a symlink with an innocuous basename can\\n        # alias a denied target that `.resolve()` has already followed.\\n        if deny_error := _check_deny_list(str(candidate.relative_to(root_resolved))):\\n            raise PermissionError(deny_error)\\n        if hardlink_error := _check_hardlink(candidate):\\n            raise PermissionError(hardlink_error)\\n        return candidate\\n\\n    def _read_file(self, path: str, offset: int | None = None, limit: int | None = None) -> dict:\\n        try:\\n            resolved = self._validate_path(path)\\n        except PermissionError as exc:\\n            return {\\\"error\\\": str(exc), \\\"path\\\": path}\\n\\n        if not resolved.exists():\\n            return {\\\"error\\\": f\\\"File not found: {path}\\\", \\\"path\\\": path}\\n        if resolved.is_dir():\\n            return {\\\"error\\\": f\\\"Path is a directory, not a file: {path}\\\", \\\"path\\\": path}\\n\\n        try:\\n            size = resolved.stat().st_size\\n        except OSError as exc:\\n            return {\\\"error\\\": f\\\"Cannot stat file: {exc.strerror or exc}\\\", \\\"path\\\": path}\\n        if size > MAX_FILE_SIZE_BYTES:\\n            return {\\n                \\\"error\\\": f\\\"File size {size} exceeds limit of {MAX_FILE_SIZE_BYTES} bytes\\\",\\n                \\\"path\\\": path,\\n            }\\n\\n        try:\\n            head = _read_head_no_follow(resolved, BINARY_SNIFF_BYTES)\\n        except OSError as exc:\\n            return {\\\"error\\\": f\\\"Cannot read file: {exc.strerror or exc}\\\", \\\"path\\\": path}\\n        if _looks_binary(head):\\n            return {\\\"error\\\": f\\\"Refusing to read binary file: {path}\\\", \\\"path\\\": path}\\n\\n        try:\\n            text = _read_bytes_no_follow(resolved).decode(\\\"utf-8\\\", errors=\\\"replace\\\")\\n        except OSError as exc:\\n            return {\\\"error\\\": f\\\"Cannot read file: {exc.strerror or exc}\\\", \\\"path\\\": path}\\n\\n        lines = text.splitlines()\\n        total = len(lines)\\n        start = offset if offset and offset > 0 else 1\\n        end = total if limit is None else min(total, start - 1 + limit)\\n        window = lines[start - 1 : end]\\n        numbered = \\\"\\\\n\\\".join(f\\\"{i:>6}\u2192{line}\\\" for i, line in enumerate(window, start=start))\\n        return {\\n            \\\"status\\\": \\\"ok\\\",\\n            \\\"path\\\": path,\\n            \\\"content\\\": numbered,\\n            \\\"total_lines\\\": total,\\n            \\\"start_line\\\": start,\\n            \\\"num_lines\\\": len(window),\\n        }\\n\\n    def _write_file(self, path: str, content: str) -> dict:\\n        try:\\n            resolved = self._validate_path(path)\\n        except PermissionError as exc:\\n            return {\\\"error\\\": str(exc), \\\"path\\\": path}\\n\\n        encoded = content.encode(\\\"utf-8\\\")\\n        if len(encoded) > MAX_FILE_SIZE_BYTES:\\n            return {\\n                \\\"error\\\": f\\\"Content size {len(encoded)} exceeds limit of {MAX_FILE_SIZE_BYTES} bytes\\\",\\n                \\\"path\\\": path,\\n            }\\n\\n        if resolved.is_dir():\\n            return {\\\"error\\\": f\\\"Path is a directory, not a file: {path}\\\", \\\"path\\\": path}\\n        # Auto-create missing parent directories. `_validate_path` has already\\n        # confirmed `resolved` lies inside the sandbox root, so every ancestor\\n        # of `resolved.parent` is also inside the root \u2014 `mkdir(parents=True)`\\n        # cannot escape the sandbox.\\n        try:\\n            resolved.parent.mkdir(parents=True, exist_ok=True)\\n        except OSError as exc:\\n            return {\\\"error\\\": f\\\"Cannot create parent directory: {exc.strerror or exc}\\\", \\\"path\\\": path}\\n\\n        existed = resolved.exists()\\n        try:\\n            _write_bytes_no_follow(resolved, encoded)\\n        except OSError as exc:\\n            return {\\\"error\\\": f\\\"Cannot write file: {exc.strerror or exc}\\\", \\\"path\\\": path}\\n\\n        return {\\n            \\\"status\\\": \\\"updated\\\" if existed else \\\"created\\\",\\n            \\\"path\\\": path,\\n            \\\"bytes_written\\\": len(encoded),\\n        }\\n\\n    def _edit_file(\\n        self,\\n        path: str,\\n        old_string: str,\\n        new_string: str,\\n        *,\\n        replace_all: bool = False,\\n    ) -> dict:\\n        try:\\n            resolved = self._validate_path(path)\\n        except PermissionError as exc:\\n            return {\\\"error\\\": str(exc), \\\"path\\\": path}\\n\\n        if not resolved.exists():\\n            return {\\\"error\\\": f\\\"File not found: {path}\\\", \\\"path\\\": path}\\n        if resolved.is_dir():\\n            return {\\\"error\\\": f\\\"Path is a directory, not a file: {path}\\\", \\\"path\\\": path}\\n\\n        # Reject empty old_string outright. With `old_string=\\\"\\\"`, str.replace\\n        # inserts new_string between every character (and at both ends),\\n        # producing roughly N*len(new_string) extra bytes \u2014 a small file plus\\n        # a large new_string can blow far past MAX_FILE_SIZE_BYTES before the\\n        # post-construction guard runs. Empty old_string also has no\\n        # well-defined semantics for \\\"edit this exact match\\\".\\n        if old_string == \\\"\\\":\\n            return {\\\"error\\\": \\\"old_string must not be empty\\\", \\\"path\\\": path}\\n\\n        try:\\n            current = _read_bytes_no_follow(resolved).decode(\\\"utf-8\\\", errors=\\\"replace\\\")\\n        except OSError as exc:\\n            return {\\\"error\\\": f\\\"Cannot read file: {exc.strerror or exc}\\\", \\\"path\\\": path}\\n\\n        occurrences = current.count(old_string)\\n        if occurrences == 0:\\n            return {\\\"error\\\": f\\\"old_string not found in file: {path}\\\", \\\"path\\\": path}\\n        if occurrences > 1 and not replace_all:\\n            return {\\n                \\\"error\\\": (\\n                    f\\\"old_string is ambiguous: {occurrences} multiple matches in {path}. \\\"\\n                    \\\"Pass replace_all=True to replace every occurrence.\\\"\\n                ),\\n                \\\"path\\\": path,\\n                \\\"matches\\\": occurrences,\\n            }\\n\\n        # Project the encoded size BEFORE building the replacement string.\\n        # str.replace allocates the full result up front, so a small file\\n        # with replace_all=True and a large new_string can balloon memory\\n        # before the post-allocation length check runs. UTF-8 byte counts are\\n        # exact (no estimation) so the projection is precise.\\n        old_bytes = len(old_string.encode(\\\"utf-8\\\"))\\n        new_bytes = len(new_string.encode(\\\"utf-8\\\"))\\n        current_bytes = len(current.encode(\\\"utf-8\\\"))\\n        replacements_planned = occurrences if replace_all else 1\\n        projected_bytes = current_bytes + replacements_planned * (new_bytes - old_bytes)\\n        if projected_bytes > MAX_FILE_SIZE_BYTES:\\n            return {\\n                \\\"error\\\": (\\n                    f\\\"Resulting content size {projected_bytes} would exceed limit of {MAX_FILE_SIZE_BYTES} bytes\\\"\\n                ),\\n                \\\"path\\\": path,\\n            }\\n\\n        updated = current.replace(old_string, new_string) if replace_all else current.replace(old_string, new_string, 1)\\n        encoded = updated.encode(\\\"utf-8\\\")\\n        # Defensive re-check (should be unreachable given the projection above,\\n        # but keeps the original invariant explicit).\\n        if len(encoded) > MAX_FILE_SIZE_BYTES:\\n            return {\\n                \\\"error\\\": f\\\"Resulting content size {len(encoded)} exceeds limit of {MAX_FILE_SIZE_BYTES} bytes\\\",\\n                \\\"path\\\": path,\\n            }\\n\\n        try:\\n            _write_bytes_no_follow(resolved, encoded)\\n        except OSError as exc:\\n            return {\\\"error\\\": f\\\"Cannot write file: {exc.strerror or exc}\\\", \\\"path\\\": path}\\n\\n        return {\\n            \\\"status\\\": \\\"ok\\\",\\n            \\\"path\\\": path,\\n            \\\"replacements\\\": occurrences if replace_all else 1,\\n            \\\"old_string\\\": old_string,\\n            \\\"new_string\\\": new_string,\\n        }\\n\\n    def _glob_search(self, pattern: str, path: str | None = None) -> dict:\\n        # Empty patterns make ``Path.glob`` raise ``ValueError`` instead of\\n        # returning an empty match list, which would propagate uncaught and\\n        # crash the agent. Surface a structured error instead.\\n        if not pattern or not pattern.strip():\\n            return {\\\"error\\\": \\\"Pattern must not be empty\\\", \\\"pattern\\\": pattern, \\\"path\\\": path}\\n        # Reject traversal segments in the pattern itself. Without this guard,\\n        # ``base.glob(\\\"../*\\\")`` walks one directory up; one of the resulting\\n        # paths (``<base>/../<base_basename>``) resolves back to ``base`` and\\n        # is surfaced to the agent as ``\\\".\\\"`` \u2014 a silent, misleading hit.\\n        # ``PureWindowsPath`` splits on both ``/`` and ``\\\\`` so the check\\n        # covers Windows-authored patterns as well.\\n        if any(part == \\\"..\\\" for part in PureWindowsPath(pattern).parts):\\n            return {\\n                \\\"error\\\": \\\"Pattern must not contain '..' (path traversal not allowed)\\\",\\n                \\\"pattern\\\": pattern,\\n                \\\"path\\\": path,\\n            }\\n        try:\\n            root_resolved = self._validate_root()\\n            base = self._validate_path(path) if path else root_resolved\\n        except PermissionError as exc:\\n            return {\\\"error\\\": str(exc), \\\"pattern\\\": pattern, \\\"path\\\": path}\\n\\n        if not base.exists() or not base.is_dir():\\n            return {\\\"error\\\": f\\\"Base path is not a directory: {path or '.'}\\\", \\\"pattern\\\": pattern}\\n\\n        # Collect up to GLOB_SCAN_CEILING (>> GLOB_RESULT_LIMIT) so we can\\n        # surface diverse branches even when one directory dominates the\\n        # iteration order. See BUG-02 / T2-001.\\n        collected: list[str] = []\\n        for match in base.glob(pattern):\\n            try:\\n                resolved_match = match.resolve()\\n            except OSError:\\n                continue\\n            if not resolved_match.is_relative_to(root_resolved):\\n                continue\\n            relative_match = str(resolved_match.relative_to(root_resolved))\\n            if _check_deny_list(relative_match):\\n                continue\\n            collected.append(relative_match)\\n            if len(collected) >= GLOB_SCAN_CEILING:\\n                break\\n\\n        # Sort for cross-filesystem determinism, then truncate to the visible\\n        # cap. Emit `truncated_branches` so the agent has a non-silent signal:\\n        # top-level branches under `base` whose files appear in the omitted\\n        # tail. The agent can narrow with `path=<branch>` to recover them.\\n        collected.sort()\\n        truncated = len(collected) > GLOB_RESULT_LIMIT\\n        if truncated:\\n            omitted = collected[GLOB_RESULT_LIMIT:]\\n            matches = collected[:GLOB_RESULT_LIMIT]\\n            truncated_branches = sorted({Path(p).parts[0] for p in omitted if Path(p).parts})\\n        else:\\n            matches = collected\\n            truncated_branches = []\\n\\n        return {\\n            \\\"status\\\": \\\"ok\\\",\\n            \\\"pattern\\\": pattern,\\n            \\\"matches\\\": matches,\\n            \\\"truncated\\\": truncated,\\n            \\\"truncated_branches\\\": truncated_branches,\\n        }\\n\\n    def _grep_search(\\n        self,\\n        pattern: str,\\n        path: str | None = None,\\n        glob: str | None = None,\\n        *,\\n        case_insensitive: bool = False,\\n        output_mode: str = \\\"files_with_matches\\\",\\n        is_regex: bool = False,\\n    ) -> dict:\\n        if output_mode not in GREP_OUTPUT_MODES:\\n            return {\\n                \\\"error\\\": f\\\"Invalid output_mode '{output_mode}'. Must be one of {GREP_OUTPUT_MODES}\\\",\\n                \\\"pattern\\\": pattern,\\n            }\\n\\n        # Build a per-line matcher. Default is a literal substring check \u2014\\n        # safe for any user-supplied pattern. Regex is opt-in and is gated by\\n        # a static heuristic plus per-line/per-file caps. Stdlib `re` cannot\\n        # be cancelled (it holds the GIL), so prevention is the only viable\\n        # mitigation: reject pathological patterns at compile time and bound\\n        # the input we hand to the engine.\\n        if is_regex:\\n            if len(pattern) > GREP_PATTERN_MAX_LEN:\\n                return {\\n                    \\\"error\\\": (\\n                        f\\\"Regex pattern exceeds {GREP_PATTERN_MAX_LEN} chars; \\\"\\n                        \\\"shorten it or use literal mode (is_regex=False).\\\"\\n                    ),\\n                    \\\"pattern\\\": pattern,\\n                }\\n            if _looks_like_redos(pattern):\\n                return {\\n                    \\\"error\\\": (\\n                        \\\"Regex pattern rejected: nested unbounded quantifier \\\"\\n                        \\\"(catastrophic-backtracking risk). Rewrite without an \\\"\\n                        \\\"outer +/* on a group that already contains +, *, {n,}, \\\"\\n                        \\\"or |, or use literal mode (is_regex=False).\\\"\\n                    ),\\n                    \\\"pattern\\\": pattern,\\n                }\\n            try:\\n                flags = re.IGNORECASE if case_insensitive else 0\\n                regex = re.compile(pattern, flags)\\n            except re.error as exc:\\n                return {\\\"error\\\": f\\\"Invalid regex pattern: {exc}\\\", \\\"pattern\\\": pattern}\\n\\n            def line_matches(line: str) -> bool:\\n                # Skip regex matching on oversized lines \u2014 they are usually\\n                # data blobs, and a long input is a prerequisite for most\\n                # practical exponential-backtracking attacks.\\n                if len(line) > GREP_REGEX_LINE_MAX_LEN:\\n                    return False\\n                return regex.search(line) is not None\\n        else:\\n            needle = pattern.lower() if case_insensitive else pattern\\n\\n            def line_matches(line: str) -> bool:\\n                hay = line.lower() if case_insensitive else line\\n                return needle in hay\\n\\n        try:\\n            root_resolved = self._validate_root()\\n            base = self._validate_path(path) if path else root_resolved\\n        except PermissionError as exc:\\n            return {\\\"error\\\": str(exc), \\\"pattern\\\": pattern, \\\"path\\\": path}\\n\\n        if not base.exists():\\n            return {\\\"error\\\": f\\\"Path does not exist: {path or '.'}\\\", \\\"pattern\\\": pattern}\\n\\n        targets = self._collect_grep_targets(base, glob)\\n        files_with_matches: list[str] = []\\n        content_matches: list[dict] = []\\n        count_matches: list[dict] = []\\n        line_budget = GREP_LINE_LIMIT\\n        truncated = False\\n\\n        for file in targets:\\n            try:\\n                resolved_file = file.resolve()\\n            except OSError:\\n                continue\\n            if not resolved_file.is_relative_to(root_resolved):\\n                continue\\n            rel_path = str(resolved_file.relative_to(root_resolved))\\n            if _check_deny_list(rel_path):\\n                continue\\n            try:\\n                size = resolved_file.stat().st_size\\n            except OSError:\\n                continue\\n            if size > MAX_FILE_SIZE_BYTES:\\n                continue\\n            try:\\n                with resolved_file.open(\\\"rb\\\") as fh:\\n                    head = fh.read(BINARY_SNIFF_BYTES)\\n            except OSError:\\n                continue\\n            if _looks_binary(head):\\n                continue\\n            try:\\n                text = resolved_file.read_text(encoding=\\\"utf-8\\\", errors=\\\"replace\\\")\\n            except OSError:\\n                continue\\n\\n            per_file_count = 0\\n            matched_any = False\\n            for idx, line in enumerate(text.splitlines(), start=1):\\n                # Per-file scan cap (regex only \u2014 literal scans are O(n)).\\n                if is_regex and idx > GREP_REGEX_LINES_PER_FILE:\\n                    break\\n                if not line_matches(line):\\n                    continue\\n                matched_any = True\\n                per_file_count += 1\\n                if output_mode == \\\"content\\\":\\n                    if line_budget <= 0:\\n                        truncated = True\\n                        break\\n                    content_matches.append({\\\"path\\\": rel_path, \\\"line_number\\\": idx, \\\"line\\\": line})\\n                    line_budget -= 1\\n\\n            if matched_any:\\n                files_with_matches.append(rel_path)\\n                if output_mode == \\\"count\\\":\\n                    count_matches.append({\\\"path\\\": rel_path, \\\"count\\\": per_file_count})\\n\\n            if output_mode == \\\"content\\\" and truncated:\\n                break\\n\\n        if output_mode == \\\"files_with_matches\\\":\\n            matches: list = files_with_matches\\n        elif output_mode == \\\"content\\\":\\n            matches = content_matches\\n        else:  # count\\n            matches = count_matches\\n\\n        return {\\n            \\\"status\\\": \\\"ok\\\",\\n            \\\"pattern\\\": pattern,\\n            \\\"output_mode\\\": output_mode,\\n            \\\"matches\\\": matches,\\n            \\\"truncated\\\": truncated,\\n        }\\n\\n    def _collect_grep_targets(self, base: Path, glob: str | None) -> list[Path]:\\n        if base.is_file():\\n            return [base]\\n        all_files = [p for p in base.rglob(\\\"*\\\") if p.is_file()]\\n        if glob:\\n            return [p for p in all_files if p.match(glob)]\\n        return all_files\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/files_and_knowledge/ingestion.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"75a6e1a457970c3324824f48765512ae2578b27709c29c8ab0ae32688ad88895\",\"content\":\"\\\"\\\"\\\"Knowledge ingestion component \u2014 backward-compat shim.\\n\\nThe full implementation now lives in\\n:mod:`lfx.components.files_and_knowledge.knowledge` as the mode-driven\\n:class:`KnowledgeComponent`. ``KnowledgeIngestionComponent`` is kept as a\\nthin subclass so saved flows referencing the legacy node id\\n(``KnowledgeIngestion``) and the legacy module path keep loading and\\nrunning unchanged. New flows should use ``KnowledgeComponent`` directly.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom lfx.components.files_and_knowledge.knowledge import (\\n    MODE_INGEST,\\n    KnowledgeComponent,\\n    _inputs_for_mode,\\n)\\nfrom lfx.io import Output\\n\\n# Preserved for callers that imported these constants from the legacy module.\\nastra_error_msg = \\\"Knowledge ingestion is not supported in Astra cloud environment.\\\"\\n\\n\\nclass KnowledgeIngestionComponent(KnowledgeComponent):\\n    \\\"\\\"\\\"Create or append to Langflow Knowledge from a DataFrame.\\n\\n    Pins the merged :class:`KnowledgeComponent` to ingest mode. All\\n    behavior is inherited unchanged.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Knowledge Ingestion\\\"\\n    description = \\\"Create or update knowledge in Langflow.\\\"\\n    icon = \\\"upload\\\"\\n    name = \\\"KnowledgeIngestion\\\"\\n    # Hidden from the default palette \u2014 surfaces only when a saved flow\\n    # already references it. New flows should pick ``Knowledge`` instead.\\n    legacy = True\\n    replacement = [\\\"files_and_knowledge.Knowledge\\\"]\\n\\n    # Pin the mode-default visibility at the class level so the canvas\\n    # renders the legacy \\\"ingest-only\\\" shape on first load.\\n    inputs = _inputs_for_mode(MODE_INGEST)\\n    outputs = [\\n        Output(\\n            display_name=\\\"Results\\\",\\n            name=\\\"dataframe_output\\\",\\n            method=\\\"build_kb_info\\\",\\n            types=[\\\"JSON\\\"],\\n            selected=\\\"JSON\\\",\\n        ),\\n    ]\\n\\n    def __init__(self, *args: Any, **kwargs: Any) -> None:\\n        super().__init__(*args, **kwargs)\\n        self.mode = MODE_INGEST\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/files_and_knowledge/knowledge.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1a8398d3e8f60e5377c12890480718c0bb2833ffb57c53da978ece1e93c89130\",\"content\":\"\\\"\\\"\\\"Unified Knowledge component \u2014 ingest into or retrieve from a knowledge base.\\n\\nThis component merges what used to live in ``ingestion.py`` and\\n``retrieval.py`` into a single, mode-driven component. A ``TabInput``\\n(\\\"\ud83d\udce5 Ingest\\\" / \\\"\ud83d\udd0d Retrieve\\\") drives which inputs and which output are\\nvisible. The merged shape gives users one node per KB instead of two\\nparallel ones that always shared the same ``knowledge_base`` picker,\\nembedding-model metadata, and backend registry.\\n\\nBoth legacy classes (``KnowledgeIngestionComponent``,\\n``KnowledgeBaseComponent``) remain importable as thin subclasses of\\n``KnowledgeComponent`` \u2014 see the sibling ``ingestion.py`` / ``retrieval.py``\\nmodules \u2014 so saved flows continue to load unchanged.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport hashlib\\nimport json\\nimport uuid\\nfrom collections.abc import Mapping\\nfrom dataclasses import asdict, dataclass, field\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport pandas as pd\\nfrom langchain_chroma import Chroma\\n\\nfrom lfx.base.knowledge_bases.backends import BackendType, BaseVectorStoreBackend, create_backend, is_local_chroma\\nfrom lfx.base.knowledge_bases.ingestion_sources.base import (\\n    IngestionItemResult,\\n    IngestionItemStatus,\\n    IngestionRunStatus,\\n    IngestionSummary,\\n)\\nfrom lfx.base.knowledge_bases.ingestion_sources.flow_component import FlowComponentSource\\nfrom lfx.base.knowledge_bases.knowledge_base_utils import get_knowledge_bases\\nfrom lfx.base.knowledge_bases.validation import (\\n    is_valid_collection_name as is_valid_kb_collection_name,\\n)\\nfrom lfx.base.knowledge_bases.validation import (\\n    validate_collection_name,\\n)\\nfrom lfx.base.models.unified_models import get_embedding_model_options, get_embeddings\\nfrom lfx.base.vectorstores.chroma_security import chroma_langchain_collection_kwargs\\nfrom lfx.components.processing.converter import convert_to_dataframe\\nfrom lfx.custom import Component\\nfrom lfx.helpers.base_model import coalesce_bool\\nfrom lfx.io import (\\n    BoolInput,\\n    DBProviderInput,\\n    DropdownInput,\\n    HandleInput,\\n    IntInput,\\n    MessageTextInput,\\n    ModelInput,\\n    Output,\\n    SecretStrInput,\\n    StrInput,\\n    TabInput,\\n    TableInput,\\n)\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.dotdict import dotdict\\nfrom lfx.schema.table import EditMode\\nfrom lfx.services.deps import (\\n    session_scope,\\n)\\nfrom lfx.utils.component_utils import set_current_fields, set_field_display\\nfrom lfx.utils.validate_cloud import raise_error_if_astra_cloud_disable_component\\n\\n\\ndef _inputs_for_mode(default_mode: str) -> list:\\n    \\\"\\\"\\\"Return a fresh copy of the canonical inputs list with show flags set for the given mode.\\n\\n    Used by the legacy subclasses so a saved flow keyed on\\n    ``KnowledgeIngestion`` / ``KnowledgeBase`` lands on a node template\\n    whose default visibility already matches the pinned mode \u2014 no\\n    \\\"wait for the user to click the mode tab\\\" UX gap on load.\\n    \\\"\\\"\\\"\\n    always_visible = set(KnowledgeComponent.default_keys) | set(KnowledgeComponent.mode_config[default_mode])\\n    inputs_copy = []\\n    for inp in KnowledgeComponent.inputs:\\n        clone = inp.model_copy(deep=True) if hasattr(inp, \\\"model_copy\\\") else inp\\n        if clone.name == \\\"mode\\\":\\n            clone.value = default_mode\\n        else:\\n            clone.show = clone.name in always_visible\\n        inputs_copy.append(clone)\\n    return inputs_copy\\n\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n# Mode constants. Plain-text labels (no emoji) for consistency with the rest of\\n# Langflow's TabInput palette \u2014 see ``MemoryComponent`` for the same convention.\\nMODE_INGEST = \\\"Ingest\\\"\\nMODE_RETRIEVE = \\\"Retrieve\\\"\\n\\n\\ndef _is_retrieve_mode(value: Any) -> bool:\\n    \\\"\\\"\\\"Lenient mode check: treats any label containing 'Retrieve' as retrieve mode.\\n\\n    Older saved flows may carry the emoji-prefixed labels (\\\"\ud83d\udce5 Ingest\\\" /\\n    \\\"\ud83d\udd0d Retrieve\\\") this component used to ship with; substring matching\\n    keeps those loading without forcing a flow rewrite.\\n    \\\"\\\"\\\"\\n    return isinstance(value, str) and \\\"Retrieve\\\" in value\\n\\n\\n# Boolean flags of a ``column_config`` row. Toggled cells hold real booleans,\\n# but a typed cell (or a flow saved while the cell rendered as plain text)\\n# keeps the raw string, e.g. ``\\\"true\\\"`` \u2014 read them with ``coalesce_bool``.\\n_COLUMN_FLAGS = (\\\"vectorize\\\", \\\"identifier\\\")\\n\\n\\ndef _normalize_column_config(config_list: list[dict[str, Any]]) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Return copies of the rows with every flag as a real boolean.\\\"\\\"\\\"\\n    return [{**row, **{key: coalesce_bool(row.get(key)) for key in _COLUMN_FLAGS}} for row in config_list]\\n\\n\\n# Error message used by both the ingest and retrieve paths when the user is\\n# running against an Astra cloud environment that disables these flows.\\nastra_error_msg = \\\"Knowledge ingestion and retrieval are not supported in Astra cloud environment.\\\"\\n\\n_DEFAULT_OPENSEARCH_CONFIG = {\\n    \\\"url_variable\\\": \\\"OPENSEARCH_URL\\\",\\n    \\\"username_variable\\\": \\\"OPENSEARCH_USERNAME\\\",\\n    \\\"password_variable\\\": \\\"OPENSEARCH_PASSWORD\\\",  # pragma: allowlist secret\\n    \\\"index_name\\\": \\\"\\\",\\n    \\\"vector_field\\\": \\\"vector_field\\\",\\n    \\\"text_field\\\": \\\"text\\\",\\n}\\n\\n_DEFAULT_CHROMA_CLOUD_CONFIG = {\\n    \\\"mode\\\": \\\"cloud\\\",\\n    \\\"tenant_variable\\\": \\\"CHROMA_TENANT\\\",\\n    \\\"database_variable\\\": \\\"CHROMA_DATABASE\\\",\\n    \\\"api_key_variable\\\": \\\"CHROMA_API_KEY\\\",  # pragma: allowlist secret\\n}\\n\\n\\nclass KnowledgeComponent(Component):\\n    \\\"\\\"\\\"One component for both writing into and reading from a Langflow knowledge base.\\n\\n    A ``TabInput`` switches between ingestion and retrieval. The\\n    ``update_build_config`` / ``update_outputs`` hooks hide the inputs\\n    and the output that don't apply to the current mode so the canvas\\n    node stays focused.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Knowledge\\\"\\n    description = \\\"Ingest into or retrieve from a Langflow knowledge base.\\\"\\n    icon = \\\"database\\\"\\n    name = \\\"Knowledge\\\"\\n\\n    # ------ Mode \u2192 visible-fields wiring ---------------------------------\\n    # ``default_keys`` are inputs always visible regardless of mode.\\n    # ``mode_config`` lists the inputs unique to each mode; everything outside\\n    # this set is hidden when its mode is not selected.\\n    default_keys: list[str] = [\\\"mode\\\", \\\"knowledge_base\\\"]\\n    mode_config: dict[str, list[str]] = {\\n        MODE_INGEST: [\\n            \\\"input_df\\\",\\n            \\\"column_config\\\",\\n            \\\"chunk_size\\\",\\n            \\\"api_key\\\",\\n            \\\"allow_duplicates\\\",\\n            \\\"metadata_json\\\",\\n        ],\\n        MODE_RETRIEVE: [\\n            \\\"search_query\\\",\\n            \\\"top_k\\\",\\n            \\\"include_metadata\\\",\\n            \\\"include_embeddings\\\",\\n            \\\"metadata_filter\\\",\\n        ],\\n    }\\n\\n    def __init__(self, *args, **kwargs) -> None:\\n        super().__init__(*args, **kwargs)\\n        self._cached_kb_path: Path | None = None\\n\\n    @staticmethod\\n    def _embedding_provider_from_selection(selection: Any) -> str | None:\\n        \\\"\\\"\\\"Read a provider name from a raw or persisted model selection.\\\"\\\"\\\"\\n        if isinstance(selection, list):\\n            selection = selection[0] if selection else None\\n        if not isinstance(selection, Mapping):\\n            return None\\n        provider = selection.get(\\\"provider\\\")\\n        if not isinstance(provider, str) or not provider.strip():\\n            return None\\n        return provider.strip()\\n\\n    async def _additional_model_provider_policy_ids(self, purpose, parameters=None) -> tuple[str, ...]:\\n        \\\"\\\"\\\"Resolve the embedding provider before dialog hooks or runtime secrets.\\n\\n        New-KB configuration carries its ModelInput inside a dropdown dialog,\\n        while existing KBs persist the provider in the KB row. Neither is a\\n        top-level ModelInput, so both must be resolved explicitly before the\\n        generic component pipeline hydrates ``api_key``.\\n        \\\"\\\"\\\"\\n        from lfx.base.models.provider_registry import resolve_provider_id\\n        from lfx.services.model_provider_policy import ModelProviderPolicyError\\n\\n        effective_parameters = parameters if isinstance(parameters, Mapping) else getattr(self, \\\"_parameters\\\", None)\\n        if not isinstance(effective_parameters, Mapping):\\n            effective_parameters = {}\\n        knowledge_value = effective_parameters.get(\\\"knowledge_base\\\", getattr(self, \\\"knowledge_base\\\", None))\\n\\n        if isinstance(knowledge_value, Mapping):\\n            if \\\"02_embedding_model\\\" not in knowledge_value:\\n                return ()\\n            provider = self._embedding_provider_from_selection(knowledge_value.get(\\\"02_embedding_model\\\"))\\n        elif isinstance(knowledge_value, str) and knowledge_value.strip():\\n            metadata = await self._get_kb_metadata(knowledge_value.strip())\\n            provider = self._embedding_provider_from_selection(metadata.get(\\\"model_selection\\\"))\\n            if provider is None:\\n                legacy_provider = metadata.get(\\\"embedding_provider\\\")\\n                provider = legacy_provider.strip() if isinstance(legacy_provider, str) else None\\n                if provider == \\\"Unknown\\\":\\n                    provider = None\\n        else:\\n            return ()\\n\\n        if provider is None:\\n            unknown_provider = \\\"unknown\\\"\\n            raise ModelProviderPolicyError(unknown_provider, purpose)\\n        return (resolve_provider_id(provider),)\\n\\n    @dataclass\\n    class NewKnowledgeBaseInput:\\n        functionality: str = \\\"create\\\"\\n        fields: dict[str, dict] = field(\\n            default_factory=lambda: {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"name\\\": \\\"create_knowledge_base\\\",\\n                        \\\"description\\\": \\\"Create new knowledge in Langflow.\\\",\\n                        \\\"display_name\\\": \\\"Create new Knowledge Base\\\",\\n                        \\\"field_order\\\": [\\n                            \\\"01_new_kb_name\\\",\\n                            \\\"02_embedding_model\\\",\\n                            \\\"03_knowledge_backend\\\",\\n                        ],\\n                        \\\"template\\\": {\\n                            \\\"01_new_kb_name\\\": StrInput(\\n                                name=\\\"new_kb_name\\\",\\n                                display_name=\\\"Knowledge Name\\\",\\n                                info=\\\"Name of the new knowledge to create.\\\",\\n                                required=True,\\n                            ),\\n                            \\\"02_embedding_model\\\": ModelInput(\\n                                name=\\\"embedding_model\\\",\\n                                display_name=\\\"Choose Embedding Model\\\",\\n                                info=(\\n                                    \\\"Select the embedding model to use for this knowledge base. \\\"\\n                                    \\\"Langflow uses the configured credentials for that model provider.\\\"\\n                                ),\\n                                required=True,\\n                                model_type=\\\"embedding\\\",\\n                            ),\\n                            \\\"03_knowledge_backend\\\": DBProviderInput(\\n                                name=\\\"knowledge_backend\\\",\\n                                display_name=\\\"DB Provider\\\",\\n                                info=(\\n                                    \\\"Select where this knowledge base stores vectors. \\\"\\n                                    \\\"OpenSearch uses the global DB Providers settings.\\\"\\n                                ),\\n                                required=True,\\n                            ),\\n                        },\\n                    },\\n                }\\n            }\\n        )\\n\\n    # ------ Inputs --------------------------------------------------------\\n    # ``knowledge_base`` is kept at position 0 so legacy tests that check\\n    # ``component.inputs[0].dialog_inputs`` continue to work.\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"knowledge_base\\\",\\n            display_name=\\\"Knowledge\\\",\\n            info=\\\"Select the knowledge to load data from.\\\",\\n            required=True,\\n            options=[],\\n            refresh_button=True,\\n            real_time_refresh=True,\\n            dialog_inputs=asdict(NewKnowledgeBaseInput()),\\n        ),\\n        TabInput(\\n            name=\\\"mode\\\",\\n            display_name=\\\"Mode\\\",\\n            options=[MODE_INGEST, MODE_RETRIEVE],\\n            value=MODE_INGEST,\\n            info=\\\"Switch between writing new data into the knowledge base and querying it.\\\",\\n            real_time_refresh=True,\\n            tool_mode=True,\\n        ),\\n        # --- Ingest-only inputs (default-shown; hidden when mode == Retrieve) -\\n        HandleInput(\\n            name=\\\"input_df\\\",\\n            display_name=\\\"Input\\\",\\n            info=(\\n                \\\"Table with all original columns (already chunked / processed). \\\"\\n                \\\"Accepts Message, Data, or DataFrame. If Message or Data is provided, \\\"\\n                \\\"it is converted to a DataFrame automatically.\\\"\\n            ),\\n            input_types=[\\\"Message\\\", \\\"Data\\\", \\\"JSON\\\", \\\"DataFrame\\\", \\\"Table\\\"],\\n            required=True,\\n            dynamic=True,\\n            show=True,\\n        ),\\n        TableInput(\\n            name=\\\"column_config\\\",\\n            display_name=\\\"Column Configuration\\\",\\n            info=\\\"Configure column behavior for the knowledge base.\\\",\\n            required=True,\\n            table_schema=[\\n                {\\n                    \\\"name\\\": \\\"column_name\\\",\\n                    \\\"display_name\\\": \\\"Column Name\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Name of the column in the source DataFrame\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n                {\\n                    \\\"name\\\": \\\"vectorize\\\",\\n                    \\\"display_name\\\": \\\"Vectorize\\\",\\n                    \\\"type\\\": \\\"boolean\\\",\\n                    \\\"description\\\": \\\"Create embeddings for this column\\\",\\n                    \\\"default\\\": False,\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n                {\\n                    \\\"name\\\": \\\"identifier\\\",\\n                    \\\"display_name\\\": \\\"Identifier\\\",\\n                    \\\"type\\\": \\\"boolean\\\",\\n                    \\\"description\\\": \\\"Use this column as unique identifier\\\",\\n                    \\\"default\\\": False,\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n            ],\\n            value=[\\n                {\\n                    \\\"column_name\\\": \\\"text\\\",\\n                    \\\"vectorize\\\": True,\\n                    \\\"identifier\\\": True,\\n                },\\n            ],\\n            dynamic=True,\\n            show=True,\\n        ),\\n        IntInput(\\n            name=\\\"chunk_size\\\",\\n            display_name=\\\"Chunk Size\\\",\\n            info=\\\"Batch size for processing embeddings\\\",\\n            advanced=True,\\n            value=1000,\\n            dynamic=True,\\n            show=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Embedding Provider API Key\\\",\\n            info=\\\"Overrides global provider settings. Leave blank to use your pre-configured API Key.\\\",\\n            advanced=True,\\n            required=False,\\n            dynamic=True,\\n            show=True,\\n        ),\\n        BoolInput(\\n            name=\\\"allow_duplicates\\\",\\n            display_name=\\\"Allow Duplicates\\\",\\n            info=\\\"Allow duplicate rows in the knowledge base\\\",\\n            advanced=True,\\n            value=False,\\n            dynamic=True,\\n            show=True,\\n        ),\\n        StrInput(\\n            name=\\\"metadata_json\\\",\\n            display_name=\\\"Metadata\\\",\\n            info=(\\n                \\\"Optional JSON object of user metadata applied to every chunk produced by this \\\"\\n                'run (e.g. {\\\"tag\\\": \\\"invoice\\\", \\\"year\\\": \\\"2026\\\"}). Same shape as the upload modal '\\n                \\\"Metadata section so chunks browser filters + Knowledge retrieval metadata_filter \\\"\\n                \\\"work uniformly across upload, folder, and flow-driven ingestion. Malformed JSON is \\\"\\n                \\\"ignored with a warning rather than failing the run.\\\"\\n            ),\\n            advanced=True,\\n            required=False,\\n            dynamic=True,\\n            show=True,\\n        ),\\n        # --- Retrieve-only inputs (default-hidden; shown when mode == Retrieve) -\\n        MessageTextInput(\\n            name=\\\"search_query\\\",\\n            display_name=\\\"Search Query\\\",\\n            info=\\\"Optional search query to filter knowledge base data.\\\",\\n            tool_mode=True,\\n            dynamic=True,\\n            show=False,\\n        ),\\n        IntInput(\\n            name=\\\"top_k\\\",\\n            display_name=\\\"Top K Results\\\",\\n            info=\\\"Number of top results to return from the knowledge base.\\\",\\n            value=5,\\n            advanced=True,\\n            required=False,\\n            dynamic=True,\\n            show=False,\\n        ),\\n        BoolInput(\\n            name=\\\"include_metadata\\\",\\n            display_name=\\\"Include Metadata\\\",\\n            info=\\\"Whether to include all metadata in the output. If false, only content is returned.\\\",\\n            value=True,\\n            advanced=False,\\n            dynamic=True,\\n            show=False,\\n        ),\\n        BoolInput(\\n            name=\\\"include_embeddings\\\",\\n            display_name=\\\"Include Embeddings\\\",\\n            info=\\\"Whether to include embeddings in the output. Only applicable if 'Include Metadata' is enabled.\\\",\\n            value=False,\\n            advanced=True,\\n            dynamic=True,\\n            show=False,\\n        ),\\n        MessageTextInput(\\n            name=\\\"metadata_filter\\\",\\n            display_name=\\\"Metadata Filter\\\",\\n            info=(\\n                \\\"Optional JSON object of user-metadata key/value pairs. Only chunks \\\"\\n                'whose source_metadata matches every key are returned (e.g. {\\\"tag\\\": \\\"invoice\\\"} '\\n                'or {\\\"tag\\\": [\\\"invoice\\\", \\\"audit\\\"]} for OR-of-values). Backends without '\\n                \\\"native filtering apply the match client-side after retrieval.\\\"\\n            ),\\n            advanced=True,\\n            dynamic=True,\\n            show=False,\\n        ),\\n    ]\\n\\n    # ------ Outputs -------------------------------------------------------\\n    # Both outputs are declared at the class level so the runtime can\\n    # dispatch to either method depending on which one the saved flow has\\n    # wired up. ``update_outputs`` filters the canvas-visible output per\\n    # selected mode; see ``TypeConverterComponent`` and ``MemoryComponent``\\n    # for the same pattern.\\n    #\\n    # Output names match the legacy ``KnowledgeIngestionComponent``\\n    # (``dataframe_output``) and ``KnowledgeBaseComponent``\\n    # (``retrieve_data``) so saved flow edges keyed on those names resolve\\n    # cleanly against the merged component.\\n    outputs = [\\n        Output(\\n            display_name=\\\"Results\\\",\\n            name=\\\"dataframe_output\\\",\\n            method=\\\"build_kb_info\\\",\\n            types=[\\\"JSON\\\"],\\n            selected=\\\"JSON\\\",\\n        ),\\n        Output(\\n            display_name=\\\"Results\\\",\\n            name=\\\"retrieve_data\\\",\\n            method=\\\"retrieve_data\\\",\\n            info=\\\"Returns the data from the selected knowledge base.\\\",\\n            types=[\\\"Table\\\"],\\n            selected=\\\"Table\\\",\\n        ),\\n    ]\\n\\n    # ------ Mode-driven UI updates ---------------------------------------\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict):\\n        \\\"\\\"\\\"Sync the visible output with the current ``mode`` value on canvas load.\\n\\n        Saved flows hit this path: ``update_outputs`` is normally only triggered\\n        by ``real_time_refresh`` field edits, so without this re-sync the\\n        canvas could land with both outputs visible.\\n        \\\"\\\"\\\"\\n        await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = new_frontend_node.get(\\\"template\\\", {})\\n        mode_value = template.get(\\\"mode\\\", {}).get(\\\"value\\\", MODE_INGEST)\\n        self.update_outputs(new_frontend_node, \\\"mode\\\", mode_value)\\n        # The rebuilt template carries class-default (Ingest) ``show`` flags,\\n        # so a saved Retrieve node returned ``search_query`` hidden and the canvas\\n        # silently dropped the edge feeding it.\\n        self._apply_mode_visibility(template)\\n        return new_frontend_node\\n\\n    def _apply_mode_visibility(self, build_config, field_name: str | None = None, field_value: Any = None):\\n        \\\"\\\"\\\"Show only the inputs that belong to the effective mode.\\\"\\\"\\\"\\n        current_mode = build_config.get(\\\"mode\\\", {}).get(\\\"value\\\") if isinstance(build_config, dict) else None\\n        if field_name == \\\"mode\\\":\\n            current_mode = field_value\\n        # Map legacy/emoji-prefixed labels onto the current canonical values so\\n        # flows saved before the label change still toggle visibility correctly.\\n        if _is_retrieve_mode(current_mode):\\n            current_mode = MODE_RETRIEVE\\n        elif current_mode not in self.mode_config:\\n            current_mode = MODE_INGEST\\n        return set_current_fields(\\n            build_config=build_config if isinstance(build_config, dotdict) else dotdict(build_config),\\n            action_fields=self.mode_config,\\n            selected_action=current_mode,\\n            default_fields=self.default_keys,\\n            func=set_field_display,\\n        )\\n\\n    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:\\n        \\\"\\\"\\\"Filter visible outputs to match the selected mode.\\n\\n        Triggered by the ``mode`` ``TabInput`` ``real_time_refresh`` flag.\\n        The class-level ``outputs`` list always carries both entries so the\\n        runtime can resolve either ``build_kb_info`` or ``retrieve_data``\\n        regardless of canvas visibility \u2014 we just hide the unused one here.\\n        \\\"\\\"\\\"\\n        if field_name != \\\"mode\\\":\\n            return frontend_node\\n        if _is_retrieve_mode(field_value):\\n            frontend_node[\\\"outputs\\\"] = [\\n                Output(\\n                    display_name=\\\"Results\\\",\\n                    name=\\\"retrieve_data\\\",\\n                    method=\\\"retrieve_data\\\",\\n                    info=\\\"Returns the data from the selected knowledge base.\\\",\\n                    types=[\\\"Table\\\"],\\n                    selected=\\\"Table\\\",\\n                )\\n            ]\\n        else:\\n            frontend_node[\\\"outputs\\\"] = [\\n                Output(\\n                    display_name=\\\"Results\\\",\\n                    name=\\\"dataframe_output\\\",\\n                    method=\\\"build_kb_info\\\",\\n                    types=[\\\"JSON\\\"],\\n                    selected=\\\"JSON\\\",\\n                )\\n            ]\\n        return frontend_node\\n\\n    async def update_build_config(\\n        self,\\n        build_config,\\n        field_value: Any,\\n        field_name: str | None = None,\\n    ):\\n        \\\"\\\"\\\"Refresh KB options, drive the create-KB dialog, and hide off-mode fields.\\\"\\\"\\\"\\n        # Astra-cloud gate covers both ingest and retrieve paths.\\n        raise_error_if_astra_cloud_disable_component(astra_error_msg)\\n\\n        # Always populate the create-KB dialog's embedding-model options so the\\n        # ModelInput renders correctly regardless of which input triggered the\\n        # refresh.\\n        try:\\n            dialog_template = (\\n                build_config[\\\"knowledge_base\\\"]\\n                .get(\\\"dialog_inputs\\\", {})\\n                .get(\\\"fields\\\", {})\\n                .get(\\\"data\\\", {})\\n                .get(\\\"node\\\", {})\\n                .get(\\\"template\\\", {})\\n            )\\n            if \\\"02_embedding_model\\\" in dialog_template:\\n                embedding_options = get_embedding_model_options(user_id=self.user_id)\\n                dialog_template[\\\"02_embedding_model\\\"][\\\"options\\\"] = embedding_options\\n        except Exception:  # noqa: BLE001\\n            self.log(\\\"Failed to populate embedding model options in dialog\\\")\\n\\n        # KB-picker refresh + create-new-KB flow (lifted from the legacy ingestion\\n        # component verbatim; relied on by both the canvas refresh button and the\\n        # dialog-submit path).\\n        if field_name == \\\"knowledge_base\\\":\\n            # Lazy import keeps lfx importable without langflow installed.\\n            from langflow.services.database.models.user.crud import get_user_by_id\\n\\n            async with session_scope() as db:\\n                if not self.user_id:\\n                    msg = \\\"User ID is required for fetching knowledge base list.\\\"\\n                    raise ValueError(msg)\\n                current_user = await get_user_by_id(db, self.user_id)\\n                if not current_user:\\n                    msg = f\\\"User with ID {self.user_id} not found.\\\"\\n                    raise ValueError(msg)\\n                kb_user = current_user.username\\n            if isinstance(field_value, dict) and \\\"01_new_kb_name\\\" in field_value:\\n                model_selection = field_value[\\\"02_embedding_model\\\"]\\n                if isinstance(model_selection, dict):\\n                    model_selection = [model_selection]\\n\\n                backend_type, backend_config = self._normalize_backend_selection(\\n                    field_value.get(\\\"03_knowledge_backend\\\")\\n                )\\n                new_kb_name = field_value[\\\"01_new_kb_name\\\"]\\n                if backend_type == BackendType.CHROMA.value:\\n                    validate_collection_name(\\n                        new_kb_name,\\n                        resource=\\\"Knowledge base\\\",\\n                        local=is_local_chroma(backend_type, backend_config),\\n                    )\\n\\n                embed_model = get_embeddings(\\n                    model=model_selection,\\n                    user_id=self.user_id,\\n                )\\n\\n                try:\\n                    await asyncio.wait_for(\\n                        asyncio.to_thread(embed_model.embed_query, \\\"test\\\"),\\n                        timeout=10,\\n                    )\\n                except TimeoutError as e:\\n                    msg = \\\"Embedding validation timed out. Please verify network connectivity and key.\\\"\\n                    raise ValueError(msg) from e\\n                except Exception as e:\\n                    msg = f\\\"Embedding validation failed: {e!s}\\\"\\n                    raise ValueError(msg) from e\\n\\n                # Only local Chroma gets a directory; every remote backend\\n                # returns None here and creates its collection on first write.\\n                from langflow.api.utils.kb_helpers import resolve_local_store_path\\n\\n                resolve_local_store_path(\\n                    new_kb_name,\\n                    kb_user,\\n                    backend_type=backend_type,\\n                    backend_config=backend_config,\\n                    create=True,\\n                )\\n\\n                build_config[\\\"knowledge_base\\\"][\\\"value\\\"] = new_kb_name\\n                await self._create_knowledge_base_record(\\n                    user_id=self.user_id,\\n                    name=field_value[\\\"01_new_kb_name\\\"],\\n                    model_selection=model_selection,\\n                    backend_type=backend_type,\\n                    backend_config=backend_config,\\n                )\\n\\n            build_config[\\\"knowledge_base\\\"][\\\"options\\\"] = await get_knowledge_bases(user_id=self.user_id)\\n            if build_config[\\\"knowledge_base\\\"][\\\"value\\\"] not in build_config[\\\"knowledge_base\\\"][\\\"options\\\"]:\\n                build_config[\\\"knowledge_base\\\"][\\\"value\\\"] = None\\n\\n        # Honor the current mode regardless of which field triggered the refresh.\\n        return self._apply_mode_visibility(build_config, field_name, field_value)\\n\\n    # =====================================================================\\n    #                       INGESTION CODE PATH\\n    # =====================================================================\\n    @staticmethod\\n    def _scalar_notna(value) -> bool:\\n        \\\"\\\"\\\"Check if a value is not NA, safely handling arrays and sequences.\\n\\n        ``pd.notna`` returns an array when given an array-like input, which\\n        cannot be used directly in a boolean context.  This helper collapses\\n        the result to a single scalar ``bool``.\\n        \\\"\\\"\\\"\\n        result = pd.notna(value)\\n        if hasattr(result, \\\"__iter__\\\") and not isinstance(result, str):\\n            import numpy as np\\n\\n            arr = np.asarray(result)\\n            return arr.size > 0 and arr.all()\\n        return bool(result)\\n\\n    def _validate_column_config(self, df_source: pd.DataFrame) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Validate column configuration using Structured Output patterns.\\\"\\\"\\\"\\n        if not self.column_config:\\n            msg = \\\"Column configuration cannot be empty\\\"\\n            raise ValueError(msg)\\n\\n        config_list = self.column_config if isinstance(self.column_config, list) else []\\n\\n        df_columns = set(df_source.columns)\\n        for config in config_list:\\n            col_name = config.get(\\\"column_name\\\")\\n            if col_name not in df_columns:\\n                msg = f\\\"Column '{col_name}' not found in DataFrame. Available columns: {sorted(df_columns)}\\\"\\n                raise ValueError(msg)\\n\\n        return config_list\\n\\n    @staticmethod\\n    def _extract_source_types_from_df(df_source: pd.DataFrame) -> set[str]:\\n        \\\"\\\"\\\"Pull file extensions out of common path/name columns on the source DataFrame.\\n\\n        The direct-upload ingestion path stores extensions in\\n        the KB row's ``source_types`` so the KB list can render the\\n        correct file-type icon. When ingestion happens via a connected\\n        ``input_df`` (e.g. File \u2192 Knowledge) the same field stayed empty and\\n        the icon defaulted to a blank tile. We look at the well-known columns\\n        the File / S3 / cloud-storage components produce and collect any\\n        plausible extension so the icon is consistent across both flows.\\n        \\\"\\\"\\\"\\n        candidate_columns = (\\\"file_path\\\", \\\"file_name\\\", \\\"filename\\\", \\\"source\\\", \\\"path\\\", \\\"mimetype\\\")\\n        extensions: set[str] = set()\\n        for col in candidate_columns:\\n            if col not in df_source.columns:\\n                continue\\n            for value in df_source[col].dropna():\\n                ext = KnowledgeComponent._extension_from_value(value)\\n                # Drop anything that doesn't look like an extension (URL\\n                # query strings, version segments, etc.) \u2014 the icon palette\\n                # keys off short alphanumeric tokens like \\\"pdf\\\"/\\\"docx\\\".\\n                if ext:\\n                    extensions.add(ext)\\n        return extensions\\n\\n    @staticmethod\\n    def _extension_from_value(value: Any) -> str | None:\\n        \\\"\\\"\\\"Return a normalized file-extension token from a path / filename / MIME string.\\n\\n        Accepts values like ``\\\"report.PDF\\\"``, ``\\\"/docs/notes.txt\\\"``, or\\n        ``\\\"application/pdf\\\"`` and returns ``\\\"pdf\\\"`` / ``\\\"txt\\\"``. Returns\\n        ``None`` if no plausible extension can be derived.\\n        \\\"\\\"\\\"\\n        extension_length_limit = 10\\n        if value is None:\\n            return None\\n        text = str(value).strip()\\n        if not text:\\n            return None\\n        # MIME types like ``application/pdf`` carry the canonical extension\\n        # in the subtype slot \u2014 preserve them so File / S3 messages keyed\\n        # only on ``mimetype`` still resolve to an icon.\\n        if \\\"/\\\" in text and \\\".\\\" not in text.rsplit(\\\"/\\\", 1)[-1]:\\n            subtype = text.rsplit(\\\"/\\\", 1)[-1].strip().lower()\\n            return subtype if subtype and len(subtype) <= extension_length_limit and subtype.isalnum() else None\\n        if \\\".\\\" not in text:\\n            return None\\n        ext = text.rsplit(\\\".\\\", 1)[-1].strip().lower()\\n        if ext and len(ext) <= extension_length_limit and ext.isalnum():\\n            return ext\\n        return None\\n\\n    @classmethod\\n    def _extract_source_types_from_mapping(cls, mapping: Any) -> set[str]:\\n        \\\"\\\"\\\"Pull extensions from a Message/Data-style ``data`` dict or a plain dict.\\\"\\\"\\\"\\n        if not isinstance(mapping, dict):\\n            return set()\\n        candidate_keys = (\\\"file_path\\\", \\\"file_name\\\", \\\"filename\\\", \\\"source\\\", \\\"path\\\", \\\"mimetype\\\")\\n        extensions: set[str] = set()\\n        for key in candidate_keys:\\n            ext = cls._extension_from_value(mapping.get(key))\\n            if ext:\\n                extensions.add(ext)\\n        return extensions\\n\\n    @classmethod\\n    def _extract_source_types_from_input(cls, input_value: Any) -> set[str]:\\n        \\\"\\\"\\\"Pull file extensions out of the raw component input.\\n\\n        ``convert_to_dataframe`` strips Message/Data fields down to ``text``\\n        when projecting onto a DataFrame, so file metadata attached to a\\n        File-component \\\"Raw Content\\\" output never reaches\\n        ``_extract_source_types_from_df``. Looking at the raw input first\\n        keeps the KB icon consistent with direct upload.\\n        \\\"\\\"\\\"\\n        if input_value is None:\\n            return set()\\n        if isinstance(input_value, list):\\n            extensions: set[str] = set()\\n            for item in input_value:\\n                extensions |= cls._extract_source_types_from_input(item)\\n            return extensions\\n        if isinstance(input_value, pd.DataFrame):\\n            return cls._extract_source_types_from_df(input_value)\\n        # Message / Data / JSON all expose a ``data`` dict via the lfx schema.\\n        mapping = getattr(input_value, \\\"data\\\", None)\\n        if mapping is None and isinstance(input_value, dict):\\n            mapping = input_value\\n        return cls._extract_source_types_from_mapping(mapping)\\n\\n    async def _refresh_kb_stats(\\n        self,\\n        *,\\n        kb_record_id: Any,\\n        backend: BaseVectorStoreBackend,\\n        extensions: set[str],\\n    ) -> None:\\n        \\\"\\\"\\\"Recount the KB from its vector store and write the totals onto the row.\\n\\n        Backend-agnostic: counts come from ``count`` / ``iter_documents`` /\\n        ``storage_size_bytes``, so a Chroma, OpenSearch, or pgVector KB all report\\n        real numbers. ``extensions`` are merged into ``source_types`` so the KB\\n        list renders the right file-type icon regardless of which ingestion route\\n        produced the chunks.\\n\\n        Best-effort: the chunks are already written and committed by the time this\\n        runs, so a stats refresh failure must not fail the ingestion.\\n        \\\"\\\"\\\"\\n        if kb_record_id is None:\\n            return\\n        try:\\n            from langflow.api.utils import knowledge_base_service\\n        except ImportError:\\n            return\\n\\n        try:\\n            chunks = await backend.count()\\n            characters = 0\\n            words = 0\\n            async for batch in backend.iter_documents():\\n                for document in batch:\\n                    characters += len(document.content)\\n                    words += len(document.content.split())\\n\\n            record = await knowledge_base_service.get_by_id(kb_record_id)\\n            existing = set(record.source_types or []) if record is not None else set()\\n\\n            await knowledge_base_service.update_stats(\\n                kb_record_id,\\n                chunks=chunks,\\n                words=words,\\n                characters=characters,\\n                size_bytes=await backend.storage_size_bytes(),\\n                source_types=sorted(existing | extensions),\\n            )\\n        except Exception as e:  # noqa: BLE001 \u2014 stats are cosmetic; chunks are already written\\n            self.log(f\\\"Warning: Could not refresh knowledge base stats: {e}\\\")\\n\\n    @staticmethod\\n    def _default_backend_selection() -> tuple[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Deployment default for a new KB with no explicit backend chosen.\\n\\n        pgVector is environment-driven: when ``PGVECTOR_CONNECTION_STRING`` is set\\n        the deployment snap-configures to Postgres, so an unspecified selection\\n        (headless flows, multi-replica) becomes ``postgres``. Otherwise Chroma.\\n        \\\"\\\"\\\"\\n        from lfx.base.knowledge_bases.backends.postgres import postgres_env_configured\\n\\n        if postgres_env_configured():\\n            return BackendType.POSTGRES.value, {}\\n        return BackendType.CHROMA.value, {}\\n\\n    @classmethod\\n    def _normalize_backend_selection(cls, value: Any) -> tuple[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Normalize a DBProviderInput value into backend type/config.\\\"\\\"\\\"\\n        if not value:\\n            return cls._default_backend_selection()\\n\\n        if isinstance(value, str):\\n            if value == BackendType.OPENSEARCH.value:\\n                return BackendType.OPENSEARCH.value, _DEFAULT_OPENSEARCH_CONFIG.copy()\\n            if value == BackendType.POSTGRES.value:\\n                return BackendType.POSTGRES.value, {}\\n            return BackendType.CHROMA.value, {}\\n\\n        if not isinstance(value, dict):\\n            return BackendType.CHROMA.value, {}\\n\\n        backend_type = str(value.get(\\\"backend_type\\\") or value.get(\\\"id\\\") or BackendType.CHROMA.value)\\n\\n        if backend_type == BackendType.OPENSEARCH.value:\\n            backend_config = value.get(\\\"backend_config\\\") or value.get(\\\"config\\\") or {}\\n            if not isinstance(backend_config, dict):\\n                backend_config = {}\\n            return BackendType.OPENSEARCH.value, {**_DEFAULT_OPENSEARCH_CONFIG, **backend_config}\\n\\n        if backend_type == BackendType.POSTGRES.value:\\n            return BackendType.POSTGRES.value, {}\\n\\n        if backend_type == \\\"chroma_cloud\\\":\\n            backend_config = value.get(\\\"backend_config\\\") or value.get(\\\"config\\\") or {}\\n            if not isinstance(backend_config, dict):\\n                backend_config = {}\\n            return BackendType.CHROMA.value, {**_DEFAULT_CHROMA_CLOUD_CONFIG, **backend_config}\\n\\n        return BackendType.CHROMA.value, {}\\n\\n    async def _create_knowledge_base_record(\\n        self,\\n        *,\\n        user_id: Any,\\n        name: str,\\n        model_selection: list[dict[str, Any]],\\n        backend_type: str,\\n        backend_config: dict[str, Any],\\n    ) -> None:\\n        \\\"\\\"\\\"Persist the component-created KB in the DB when Langflow is available.\\\"\\\"\\\"\\n        try:\\n            from langflow.api.utils import knowledge_base_service\\n        except ImportError:\\n            return\\n\\n        try:\\n            await knowledge_base_service.create_record(\\n                user_id=user_id,\\n                name=name,\\n                model_selection=model_selection,\\n                column_config=_normalize_column_config(self.column_config)\\n                if isinstance(self.column_config, list)\\n                else [],\\n                backend_type=backend_type,\\n                backend_config=backend_config,\\n            )\\n        except Exception as exc:  # noqa: BLE001\\n            self.log(f\\\"Warning: could not persist knowledge base record: {exc}\\\")\\n\\n    def _build_column_metadata(self, config_list: list[dict[str, Any]], df_source: pd.DataFrame) -> dict[str, Any]:\\n        \\\"\\\"\\\"Build detailed column metadata.\\\"\\\"\\\"\\n        metadata: dict[str, Any] = {\\n            \\\"total_columns\\\": len(df_source.columns),\\n            \\\"mapped_columns\\\": len(config_list),\\n            \\\"unmapped_columns\\\": len(df_source.columns) - len(config_list),\\n            \\\"columns\\\": [],\\n            \\\"summary\\\": {\\\"vectorized_columns\\\": [], \\\"identifier_columns\\\": []},\\n        }\\n\\n        for config in config_list:\\n            col_name = config.get(\\\"column_name\\\")\\n            vectorize = coalesce_bool(config.get(\\\"vectorize\\\"))\\n            identifier = coalesce_bool(config.get(\\\"identifier\\\"))\\n\\n            metadata[\\\"columns\\\"].append(\\n                {\\n                    \\\"name\\\": col_name,\\n                    \\\"vectorize\\\": vectorize,\\n                    \\\"identifier\\\": identifier,\\n                }\\n            )\\n\\n            if vectorize:\\n                metadata[\\\"summary\\\"][\\\"vectorized_columns\\\"].append(col_name)\\n            if identifier:\\n                metadata[\\\"summary\\\"][\\\"identifier_columns\\\"].append(col_name)\\n\\n        return metadata\\n\\n    async def _create_vector_store(\\n        self,\\n        df_source: pd.DataFrame,\\n        config_list: list[dict[str, Any]],\\n        embedding_function,\\n    ) -> BaseVectorStoreBackend:\\n        \\\"\\\"\\\"Create vector store using the configured DB provider.\\\"\\\"\\\"\\n        backend_type, backend_config = await self._resolve_backend_config()\\n        # ``None`` for every remote backend \u2014 nothing to create on this box.\\n        vector_store_dir = self._resolve_store_path(await self._kb_username(), backend_type, backend_config)\\n        if vector_store_dir is not None:\\n            vector_store_dir.mkdir(parents=True, exist_ok=True)\\n\\n        backend = create_backend(\\n            backend_type,\\n            kb_name=self.knowledge_base,\\n            kb_path=vector_store_dir,\\n            backend_config=backend_config,\\n            embedding_function=embedding_function,\\n            user_id=self.user_id,\\n        )\\n        await backend.ensure_ready()\\n\\n        existing_ids = None\\n        if backend_type != BackendType.CHROMA.value and not self.allow_duplicates:\\n            existing_ids = set()\\n            async for batch in backend.iter_documents():\\n                for document in batch:\\n                    doc_id = document.metadata.get(\\\"_id\\\")\\n                    if doc_id:\\n                        existing_ids.add(doc_id)\\n\\n        data_objects = await self._convert_df_to_data_objects(df_source, config_list, existing_ids=existing_ids)\\n\\n        user_metadata_tag = self._resolve_user_metadata_tag()\\n\\n        documents = []\\n        for data_obj in data_objects:\\n            doc = data_obj.to_lc_document()\\n            if user_metadata_tag:\\n                doc.metadata[\\\"source_metadata\\\"] = user_metadata_tag\\n            documents.append(doc)\\n\\n        if documents:\\n            await backend.add_documents(documents)\\n            self.log(f\\\"Added {len(documents)} documents to vector store '{self.knowledge_base}'\\\")\\n\\n        return backend\\n\\n    async def _convert_df_to_data_objects(\\n        self,\\n        df_source: pd.DataFrame,\\n        config_list: list[dict[str, Any]],\\n        existing_ids: set[str] | None = None,\\n    ) -> list[Data]:\\n        \\\"\\\"\\\"Convert DataFrame to Data objects for vector store.\\\"\\\"\\\"\\n        data_objects: list[Data] = []\\n\\n        if existing_ids is None:\\n            # Local-Chroma-only branch: every other backend collects its existing\\n            # ids through ``iter_documents`` in ``_create_vector_store`` and\\n            # passes them in, so ``kb_path`` is guaranteed non-None here.\\n            kb_path = await self._kb_path()\\n            if kb_path is None:\\n                existing_ids = set()\\n            else:\\n                chroma = Chroma(\\n                    persist_directory=str(kb_path),\\n                    collection_name=self.knowledge_base,\\n                    **chroma_langchain_collection_kwargs(),\\n                )\\n\\n                all_docs = chroma.get()\\n\\n                existing_ids = {metadata.get(\\\"_id\\\") for metadata in all_docs[\\\"metadatas\\\"] if metadata.get(\\\"_id\\\")}\\n\\n        content_cols = []\\n        identifier_cols = []\\n\\n        for config in config_list:\\n            col_name = config.get(\\\"column_name\\\")\\n\\n            if coalesce_bool(config.get(\\\"vectorize\\\")):\\n                content_cols.append(col_name)\\n            if coalesce_bool(config.get(\\\"identifier\\\")):\\n                identifier_cols.append(col_name)\\n\\n        for _, row in df_source.iterrows():\\n            identifier_parts = [str(row[col]) for col in content_cols if col in row and self._scalar_notna(row[col])]\\n\\n            page_content = \\\" \\\".join(identifier_parts)\\n\\n            data_dict = {\\n                \\\"text\\\": page_content,\\n            }\\n\\n            if identifier_cols:\\n                identifier_parts = [\\n                    str(row[col]) for col in identifier_cols if col in row and self._scalar_notna(row[col])\\n                ]\\n                page_content = \\\" \\\".join(identifier_parts)\\n\\n            for col in df_source.columns:\\n                if col not in content_cols and col in row and self._scalar_notna(row[col]):\\n                    value = row[col]\\n                    data_dict[col] = str(value)\\n\\n            page_content_hash = hashlib.sha256(page_content.encode()).hexdigest()\\n            data_dict[\\\"_id\\\"] = page_content_hash\\n\\n            if not self.allow_duplicates and page_content_hash in existing_ids:\\n                self.log(f\\\"Skipping duplicate row with hash {page_content_hash}\\\")\\n                continue\\n\\n            data_obj = Data(data=data_dict)\\n            data_objects.append(data_obj)\\n\\n        return data_objects\\n\\n    def is_valid_collection_name(self, name: str) -> bool:\\n        \\\"\\\"\\\"Return whether ``name`` satisfies the shared collection-name contract.\\\"\\\"\\\"\\n        return is_valid_kb_collection_name(name)\\n\\n    def _resolve_store_path(\\n        self,\\n        kb_user: str,\\n        backend_type: str,\\n        backend_config: dict[str, Any] | None,\\n    ) -> Path | None:\\n        \\\"\\\"\\\"Return this KB's on-disk directory, or ``None`` when it needs no disk.\\n\\n        Only local Chroma stores anything on this box; every other backend\\n        resolves to ``None`` and never touches the filesystem.\\n        \\\"\\\"\\\"\\n        # Lazy import keeps lfx importable without langflow's DB services.\\n        from langflow.api.utils.kb_helpers import resolve_local_store_path\\n\\n        return resolve_local_store_path(\\n            self.knowledge_base,\\n            kb_user,\\n            backend_type=backend_type,\\n            backend_config=backend_config,\\n        )\\n\\n    async def _kb_username(self) -> str:\\n        \\\"\\\"\\\"Resolve the owning user's username (used to root a local-Chroma path).\\\"\\\"\\\"\\n        cached = getattr(self, \\\"_cached_kb_username\\\", None)\\n        if cached is not None:\\n            return cached\\n\\n        # Lazy import to keep ``lfx`` importable standalone \u2014 langflow's\\n        # user/DB models are not always available at module load time.\\n        from langflow.services.database.models.user.crud import get_user_by_id\\n\\n        async with session_scope() as db:\\n            if not self.user_id:\\n                msg = \\\"User ID is required for fetching knowledge base path.\\\"\\n                raise ValueError(msg)\\n            current_user = await get_user_by_id(db, self.user_id)\\n            if not current_user:\\n                msg = f\\\"User with ID {self.user_id} not found.\\\"\\n                raise ValueError(msg)\\n            self._cached_kb_username = current_user.username\\n\\n        return self._cached_kb_username\\n\\n    async def _kb_path(self) -> Path | None:\\n        \\\"\\\"\\\"Resolve the KB's local directory from its configured backend.\\\"\\\"\\\"\\n        cached_path = getattr(self, \\\"_cached_kb_path\\\", None)\\n        if cached_path is not None:\\n            return cached_path\\n\\n        backend_type, backend_config = await self._resolve_backend_config()\\n        kb_user = await self._kb_username()\\n        self._cached_kb_path = self._resolve_store_path(kb_user, backend_type, backend_config)\\n        return self._cached_kb_path\\n\\n    def _resolve_user_metadata_tag(self) -> str:\\n        \\\"\\\"\\\"Return the JSON-encoded user metadata tag for chunk writes.\\\"\\\"\\\"\\n        raw = getattr(self, \\\"metadata_json\\\", None)\\n        if not raw:\\n            return \\\"\\\"\\n        text = raw.strip() if isinstance(raw, str) else raw\\n        if not text:\\n            return \\\"\\\"\\n        try:\\n            decoded = json.loads(text)\\n        except (TypeError, json.JSONDecodeError) as exc:\\n            self.log(f\\\"KnowledgeComponent: metadata_json is not valid JSON ({exc}); skipping metadata stamp.\\\")\\n            return \\\"\\\"\\n        if not isinstance(decoded, dict):\\n            self.log(\\\"KnowledgeComponent: metadata_json must decode to a JSON object; skipping metadata stamp.\\\")\\n            return \\\"\\\"\\n        return json.dumps(decoded, sort_keys=True)\\n\\n    async def build_kb_info(self) -> Data:\\n        \\\"\\\"\\\"Main ingestion routine \u2192 returns a dict with KB metadata.\\n\\n        The annotation is intentionally narrowed to ``Data`` even though the\\n        cross-mode fallback below may return a ``DataFrame`` from\\n        ``retrieve_data``. The frontend builds React-Flow handle IDs from\\n        this output's type list; widening it to ``Data | DataFrame`` makes\\n        the API advertise ``[\\\"JSON\\\", \\\"Table\\\"]`` for the ingest output and\\n        breaks every saved-edge sourceHandle that was generated against\\n        a single-type handle (BUG-02). Python doesn't enforce return\\n        annotations at runtime, so the rare fallback path keeps working.\\n        \\\"\\\"\\\"\\n        if _is_retrieve_mode(getattr(self, \\\"mode\\\", MODE_INGEST)):\\n            return await self.retrieve_data()\\n        raise_error_if_astra_cloud_disable_component(astra_error_msg)\\n\\n        run_id: uuid.UUID | None = None\\n        run_job_id: uuid.UUID | None = None\\n        run_summary: IngestionSummary | None = None\\n        run_status: IngestionRunStatus = IngestionRunStatus.SUCCEEDED\\n        run_error: str | None = None\\n        kb_record_id: uuid.UUID | None = None\\n        try:\\n            input_value = self.input_df[0] if isinstance(self.input_df, list) else self.input_df\\n            df_source: DataFrame = convert_to_dataframe(input_value, auto_parse=False)\\n\\n            config_list = self._validate_column_config(df_source)\\n            column_metadata = self._build_column_metadata(config_list, df_source)\\n\\n            # Embedding config comes from the ``knowledge_base`` row \u2014 the sole\\n            # authority. No sidecar is read, so ingestion resolves the same model\\n            # on any replica.\\n            stored_metadata = await self._get_kb_metadata()\\n            model_selection = stored_metadata.get(\\\"model_selection\\\")\\n            if model_selection:\\n                model_selection = [model_selection] if isinstance(model_selection, dict) else list(model_selection)\\n            else:\\n                embedding_model_name = stored_metadata.get(\\\"embedding_model\\\")\\n                embedding_provider = stored_metadata.get(\\\"embedding_provider\\\", \\\"Unknown\\\")\\n                if embedding_model_name:\\n                    try:\\n                        all_options = get_embedding_model_options(user_id=self.user_id)\\n                        match = next(\\n                            (o for o in all_options if o.get(\\\"name\\\") == embedding_model_name),\\n                            None,\\n                        )\\n                        if match:\\n                            model_selection = [match]\\n                        else:\\n                            self.log(\\n                                f\\\"Embedding model '{embedding_model_name}' (provider: {embedding_provider}) \\\"\\n                                \\\"from the knowledge base record is no longer available in the model registry. \\\"\\n                                \\\"Please re-create this knowledge base with a supported embedding model.\\\"\\n                            )\\n                            msg = (\\n                                f\\\"Embedding model '{embedding_model_name}' is no longer recognized. \\\"\\n                                \\\"The knowledge base was created with an older format and the model \\\"\\n                                \\\"is not available in the current registry. \\\"\\n                                \\\"Please re-create the knowledge base with a supported embedding model.\\\"\\n                            )\\n                            raise ValueError(msg)\\n                    except ValueError:\\n                        raise\\n                    except Exception:  # noqa: BLE001\\n                        self.log(\\n                            f\\\"Failed to look up embedding model '{embedding_model_name}' in registry. \\\"\\n                            \\\"Please re-create this knowledge base with a supported embedding model.\\\"\\n                        )\\n                        msg = (\\n                            f\\\"Could not look up embedding model '{embedding_model_name}' \\\"\\n                            f\\\"(provider: {embedding_provider}). \\\"\\n                            \\\"Please re-create the knowledge base with a supported embedding model.\\\"\\n                        )\\n                        raise ValueError(msg)  # noqa: B904\\n\\n            if not model_selection:\\n                msg = \\\"No embedding model configuration found. Please create the knowledge base first.\\\"\\n                raise ValueError(msg)\\n\\n            # ``api_key=None`` falls through to the user's variables table and\\n            # then the environment inside ``get_embeddings`` \u2014 the same\\n            # resolution the server-side ingestion path uses. The component input\\n            # only overrides it.\\n            embedding_function = get_embeddings(\\n                model=model_selection,\\n                user_id=self.user_id,\\n                api_key=self.api_key if getattr(self, \\\"api_key\\\", None) else None,\\n                chunk_size=self.chunk_size,\\n            )\\n\\n            kb_path = await self._kb_path()\\n\\n            run_id, run_job_id, run_summary, kb_record_id = await self._begin_ingestion_run(kb_path)\\n            if kb_record_id is not None:\\n                await self._record_kb_status(kb_record_id, \\\"ingesting\\\")\\n\\n            backend = await self._create_vector_store(df_source, config_list, embedding_function=embedding_function)\\n\\n            try:\\n                # Stamp the KB with the file extensions we just ingested so\\n                # the Knowledge Bases list renders the correct icon for\\n                # flow-driven ingestion (input_df), matching direct upload.\\n                # We look at the raw input first because ``convert_to_dataframe``\\n                # drops Message/Data metadata fields (file_path, mimetype, \u2026)\\n                # when projecting onto the DataFrame.\\n                source_types = self._extract_source_types_from_input(input_value)\\n                source_types |= self._extract_source_types_from_df(df_source)\\n                if isinstance(backend, BaseVectorStoreBackend):\\n                    await self._refresh_kb_stats(\\n                        kb_record_id=kb_record_id,\\n                        backend=backend,\\n                        extensions=source_types,\\n                    )\\n            finally:\\n                if isinstance(backend, BaseVectorStoreBackend):\\n                    await backend.teardown()\\n\\n            meta: dict[str, Any] = {\\n                \\\"kb_id\\\": str(uuid.uuid4()),\\n                \\\"kb_name\\\": self.knowledge_base,\\n                \\\"rows\\\": len(df_source),\\n                \\\"column_metadata\\\": column_metadata,\\n                \\\"path\\\": str(kb_path),\\n                \\\"config_columns\\\": len(config_list),\\n                \\\"timestamp\\\": datetime.now(tz=timezone.utc).isoformat(),\\n            }\\n\\n            if run_summary is not None:\\n                run_summary.record_item(\\n                    IngestionItemResult(\\n                        item_id=self.knowledge_base,\\n                        display_name=f\\\"{self.knowledge_base} ({len(df_source)} rows)\\\",\\n                        status=IngestionItemStatus.SUCCEEDED,\\n                        chunks_created=len(df_source),\\n                    ),\\n                )\\n\\n            if kb_record_id is not None:\\n                # Stats were already refreshed straight from the backend above.\\n                await self._record_kb_status(kb_record_id, \\\"ready\\\")\\n\\n            self.status = f\\\"\u2705 KB **{self.knowledge_base}** saved \u00b7 {len(df_source)} chunks.\\\"\\n\\n            return Data(data=meta)\\n\\n        except (OSError, ValueError, RuntimeError, KeyError) as e:\\n            run_status = IngestionRunStatus.FAILED\\n            run_error = str(e) or e.__class__.__name__\\n            msg = f\\\"Error during KB ingestion: {e}\\\"\\n            raise RuntimeError(msg) from e\\n        except Exception as e:\\n            run_status = IngestionRunStatus.FAILED\\n            run_error = str(e) or e.__class__.__name__\\n            raise\\n        finally:\\n            if run_id is not None and run_summary is not None:\\n                await self._finalize_ingestion_run(\\n                    run_id=run_id,\\n                    job_id=run_job_id,\\n                    summary=run_summary,\\n                    status=run_status,\\n                    error_message=run_error,\\n                )\\n            if kb_record_id is not None and run_status is IngestionRunStatus.FAILED:\\n                await self._record_kb_status(kb_record_id, \\\"failed\\\", failure_reason=run_error)\\n\\n    async def _begin_ingestion_run(\\n        self,\\n        kb_path: Path,\\n    ) -> tuple[uuid.UUID | None, uuid.UUID | None, IngestionSummary | None, uuid.UUID | None]:\\n        \\\"\\\"\\\"Create a parent ``Job`` and seed an ingestion-run row.\\\"\\\"\\\"\\n        if not self.user_id:\\n            self.log(\\\"No user_id on component; skipping ingestion-run tracking.\\\")\\n            return None, None, None, None\\n\\n        try:\\n            user_uuid = uuid.UUID(str(self.user_id))\\n        except (ValueError, TypeError) as exc:\\n            self.log(f\\\"Could not coerce user_id={self.user_id!r} to UUID; skipping run tracking ({exc}).\\\")\\n            return None, None, None, None\\n\\n        try:\\n            from langflow.api.utils import ingestion_run_service, knowledge_base_service\\n            from langflow.services.database.models.jobs.model import JobStatus, JobType\\n            from langflow.services.deps import get_job_service\\n        except ImportError as exc:\\n            self.log(f\\\"Run-history wiring unavailable; ingestion will not be recorded ({exc}).\\\")\\n            return None, None, None, None\\n\\n        try:\\n            kb_record = await knowledge_base_service.get_by_user_and_name(user_uuid, self.knowledge_base)\\n            kb_record_id = kb_record.id if kb_record is not None else None\\n\\n            user_metadata = self._parse_user_metadata_dict()\\n\\n            job_id = uuid.uuid4()\\n            job_service = get_job_service()\\n            raw_flow_id = getattr(self, \\\"flow_id\\\", None)\\n            flow_id_uuid = uuid.UUID(str(raw_flow_id)) if raw_flow_id else job_id\\n            await job_service.create_job(\\n                job_id=job_id,\\n                flow_id=flow_id_uuid,\\n                job_type=JobType.INGESTION,\\n                asset_id=kb_record_id,\\n                asset_type=\\\"knowledge_base\\\",\\n                user_id=user_uuid,\\n            )\\n            await job_service.update_job_status(job_id, JobStatus.IN_PROGRESS)\\n\\n            source = FlowComponentSource(\\n                user_id=user_uuid,\\n                source_config={\\n                    \\\"knowledge_base\\\": self.knowledge_base,\\n                    \\\"kb_path\\\": str(kb_path),\\n                    \\\"flow_id\\\": str(flow_id_uuid),\\n                },\\n            )\\n\\n            run_id = await ingestion_run_service.create_run(\\n                kb_name=self.knowledge_base,\\n                source=source,\\n                job_id=job_id,\\n                user_id=user_uuid,\\n                kb_id=kb_record_id,\\n                user_metadata=user_metadata,\\n            )\\n            if run_id is None:\\n                return None, job_id, None, kb_record_id\\n            await ingestion_run_service.mark_running(run_id)\\n\\n            summary = IngestionSummary(\\n                kb_name=self.knowledge_base,\\n                source_type=source.source_type.value,\\n                user_id=user_uuid,\\n                job_id=job_id,\\n                source_config=source.describe().get(\\\"config\\\") or {},\\n                user_metadata=user_metadata,\\n            )\\n            self.log(f\\\"Started ingestion run job_id={job_id} kb_name={self.knowledge_base} kb_id={kb_record_id}\\\")\\n        except Exception as exc:  # noqa: BLE001 \u2014 telemetry must never abort ingestion\\n            self.log(f\\\"Could not begin ingestion-run tracking: {exc}\\\")\\n            return None, None, None, None\\n        else:\\n            return run_id, job_id, summary, kb_record_id\\n\\n    async def _finalize_ingestion_run(\\n        self,\\n        *,\\n        run_id: uuid.UUID,\\n        job_id: uuid.UUID | None,\\n        summary: IngestionSummary,\\n        status: IngestionRunStatus,\\n        error_message: str | None,\\n    ) -> None:\\n        \\\"\\\"\\\"Persist the final summary and transition the parent Job.\\\"\\\"\\\"\\n        try:\\n            from langflow.api.utils import ingestion_run_service\\n            from langflow.services.database.models.jobs.model import JobStatus\\n            from langflow.services.deps import get_job_service\\n        except ImportError as exc:\\n            self.log(f\\\"Run-history wiring unavailable; ingestion-run finalize skipped ({exc}).\\\")\\n            return\\n\\n        try:\\n            await ingestion_run_service.finalize_run(\\n                run_id,\\n                summary=summary,\\n                status=status,\\n                error_message=error_message,\\n            )\\n            if job_id is not None:\\n                terminal_status = JobStatus.COMPLETED if status is not IngestionRunStatus.FAILED else JobStatus.FAILED\\n                await get_job_service().update_job_status(job_id, terminal_status, finished_timestamp=True)\\n        except Exception as exc:  # noqa: BLE001 \u2014 telemetry must never re-raise\\n            self.log(f\\\"Could not finalize ingestion-run tracking: {exc}\\\")\\n\\n    async def _record_kb_status(\\n        self,\\n        kb_record_id: uuid.UUID,\\n        status_value: str,\\n        *,\\n        failure_reason: str | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Mirror Path A's KB-row status transitions.\\\"\\\"\\\"\\n        try:\\n            from langflow.api.utils import knowledge_base_service\\n            from langflow.services.database.models.knowledge_base.model import KnowledgeBaseStatus\\n        except ImportError:\\n            return\\n        try:\\n            await knowledge_base_service.update_status(\\n                kb_record_id,\\n                status=KnowledgeBaseStatus(status_value),\\n                failure_reason=failure_reason,\\n            )\\n        except Exception as exc:  # noqa: BLE001\\n            self.log(f\\\"Could not update KB status to {status_value}: {exc}\\\")\\n\\n    def _parse_user_metadata_dict(self) -> dict[str, Any]:\\n        \\\"\\\"\\\"Decode ``metadata_json`` to a dict, or ``{}`` on any error.\\\"\\\"\\\"\\n        raw = getattr(self, \\\"metadata_json\\\", None)\\n        if not raw:\\n            return {}\\n        text = raw.strip() if isinstance(raw, str) else raw\\n        if not text:\\n            return {}\\n        try:\\n            decoded = json.loads(text)\\n        except (TypeError, json.JSONDecodeError):\\n            return {}\\n        return decoded if isinstance(decoded, dict) else {}\\n\\n    # =====================================================================\\n    #                       RETRIEVAL CODE PATH\\n    # =====================================================================\\n    @property\\n    def _user_uuid(self) -> uuid.UUID | None:\\n        \\\"\\\"\\\"Return self.user_id as a UUID, converting from str if necessary.\\\"\\\"\\\"\\n        if not self.user_id:\\n            return None\\n        return self.user_id if isinstance(self.user_id, uuid.UUID) else uuid.UUID(self.user_id)\\n\\n    async def _get_kb_metadata(self, knowledge_base: str | None = None) -> dict:\\n        \\\"\\\"\\\"Load this knowledge base's embedding config from its database row.\\n\\n        The row is the sole authority. There is no on-disk sidecar to fall back\\n        to, which is what lets retrieval work identically on a replica whose\\n        filesystem never held the KB directory.\\n        \\\"\\\"\\\"\\n        raise_error_if_astra_cloud_disable_component(astra_error_msg)\\n        try:\\n            from langflow.api.utils import knowledge_base_service\\n        except ImportError:\\n            return {}\\n\\n        user_uuid = self._user_uuid\\n        if user_uuid is None:\\n            return {}\\n        record = await knowledge_base_service.get_by_user_and_name(\\n            user_uuid,\\n            knowledge_base or self.knowledge_base,\\n        )\\n        if record is None:\\n            return {}\\n        return knowledge_base_service.record_to_metadata_dict(record)\\n\\n    async def _backend_from_record(self) -> tuple[str, dict[str, Any]] | None:\\n        \\\"\\\"\\\"Read ``(backend_type, backend_config)`` off the KB's database row.\\n\\n        Returns ``None`` when there is no row to read \u2014 a legacy KB predating the\\n        record, or bare lfx with no langflow installed. A lookup that *fails* is a\\n        different situation and is allowed to propagate: guessing a backend after a\\n        database error is how vectors end up in a store nothing queries.\\n        \\\"\\\"\\\"\\n        try:\\n            from langflow.api.utils import knowledge_base_service\\n        except ImportError:\\n            return None\\n\\n        user_uuid = self._user_uuid\\n        if user_uuid is None:\\n            return None\\n        record = await knowledge_base_service.get_by_user_and_name(user_uuid, self.knowledge_base)\\n        if record is None:\\n            return None\\n        return record.backend_type or BackendType.CHROMA.value, record.backend_config or {}\\n\\n    async def _resolve_backend_config(self) -> tuple[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Resolve this KB's backend from its database row.\\n\\n        Ingestion and retrieval both land here, so they cannot disagree about\\n        where this KB's vectors live. A backend that cannot be resolved raises\\n        rather than defaulting to local storage: guessing is how a pod ends up\\n        writing vectors to a local directory while queries follow the real config\\n        to a remote store and silently find nothing.\\n        \\\"\\\"\\\"\\n        resolved = await self._backend_from_record()\\n        if resolved is None:\\n            msg = (\\n                f\\\"Cannot determine the vector-store backend for knowledge base \\\"\\n                f\\\"'{self.knowledge_base}': it has no database record. Refusing to fall \\\"\\n                f\\\"back to local storage, which would write to a different store than \\\"\\n                f\\\"queries read from. If this knowledge base predates database-backed \\\"\\n                f\\\"metadata, adopt it with 'langflow reconcile-kb-from-disk'.\\\"\\n            )\\n            raise ValueError(msg)\\n        return resolved\\n\\n    def _resolve_model_selection(self, metadata: dict[str, Any]) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Resolve the ``get_embeddings``-compatible model selection from metadata.\\\"\\\"\\\"\\n        model_selection = metadata.get(\\\"model_selection\\\")\\n        if model_selection:\\n            selection_list = [model_selection] if isinstance(model_selection, dict) else list(model_selection)\\n            return [self._hydrate_model_metadata(entry) for entry in selection_list]\\n\\n        embedding_model_name = metadata.get(\\\"embedding_model\\\")\\n        embedding_provider = metadata.get(\\\"embedding_provider\\\", \\\"Unknown\\\")\\n        if not embedding_model_name:\\n            msg = (\\n                f\\\"Knowledge base '{self.knowledge_base}' has no embedding model recorded; \\\"\\n                \\\"re-create it with a supported embedding model.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        match = self._find_catalog_entry(embedding_model_name)\\n        if match is None:\\n            msg = (\\n                f\\\"Embedding model '{embedding_model_name}' (provider '{embedding_provider}') \\\"\\n                \\\"recorded for this knowledge base is no longer available in the model registry. \\\"\\n                \\\"Please re-create the knowledge base with a supported embedding model.\\\"\\n            )\\n            raise ValueError(msg)\\n        return [match]\\n\\n    def _hydrate_model_metadata(self, entry: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Fill in ``metadata.embedding_class`` / ``param_mapping`` if missing.\\\"\\\"\\\"\\n        entry_metadata = entry.get(\\\"metadata\\\") or {}\\n        has_class = bool(entry_metadata.get(\\\"embedding_class\\\"))\\n        has_mapping = bool(entry_metadata.get(\\\"param_mapping\\\"))\\n        if has_class and has_mapping:\\n            return entry\\n\\n        model_name = entry.get(\\\"name\\\")\\n        if not model_name:\\n            return entry\\n\\n        catalog_entry = self._find_catalog_entry(model_name)\\n        if catalog_entry is None:\\n            return entry\\n\\n        catalog_metadata = catalog_entry.get(\\\"metadata\\\") or {}\\n        merged_metadata = {**catalog_metadata, **entry_metadata}\\n        return {**entry, \\\"metadata\\\": merged_metadata}\\n\\n    def _find_catalog_entry(self, model_name: str) -> dict[str, Any] | None:\\n        \\\"\\\"\\\"Look up an embedding model by name in the unified-models catalog.\\\"\\\"\\\"\\n        options = get_embedding_model_options(user_id=self.user_id)\\n        return next((o for o in options if o.get(\\\"name\\\") == model_name), None)\\n\\n    async def retrieve_data(self) -> DataFrame:\\n        \\\"\\\"\\\"Retrieve data from the selected knowledge base.\\n\\n        Annotation narrowed to ``DataFrame`` to keep this output's handle\\n        type list at ``[\\\"Table\\\"]`` only; widening to a union surfaces\\n        ``[\\\"Table\\\", \\\"JSON\\\"]`` on the API and breaks every starter-project\\n        edge whose sourceHandle was stored against a single-type handle\\n        (BUG-02). The cross-mode defensive fallback may still return a\\n        ``Data`` at runtime \u2014 Python ignores return annotations, so\\n        nothing breaks.\\n        \\\"\\\"\\\"\\n        if not _is_retrieve_mode(getattr(self, \\\"mode\\\", MODE_INGEST)):\\n            return await self.build_kb_info()\\n        raise_error_if_astra_cloud_disable_component(astra_error_msg)\\n\\n        # Lazy import: langflow's user/DB models aren't part of lfx's\\n        # standalone install, so ``lfx run <starter>.json`` can't resolve\\n        # this symbol at module import time. Deferring to use keeps the\\n        # component importable in both environments.\\n        from langflow.services.database.models.user.crud import get_user_by_id\\n\\n        async with session_scope() as db:\\n            if not self.user_id:\\n                msg = \\\"User ID is required for fetching Knowledge Base data.\\\"\\n                raise ValueError(msg)\\n            current_user = await get_user_by_id(db, self.user_id)\\n            if not current_user:\\n                msg = f\\\"User with ID {self.user_id} not found.\\\"\\n                raise ValueError(msg)\\n            kb_user = current_user.username\\n\\n        metadata = await self._get_kb_metadata()\\n        if not metadata:\\n            msg = f\\\"Metadata not found for knowledge base: {self.knowledge_base}. Ensure it has been indexed.\\\"\\n            raise ValueError(msg)\\n\\n        model_selection = self._resolve_model_selection(metadata)\\n        chunk_size = metadata.get(\\\"chunk_size\\\")\\n\\n        # Resolve where this KB lives before instantiating embeddings: path\\n        # containment is a cheap local check, and a request that will be refused\\n        # shouldn't first pay for a credential lookup and a provider client.\\n        backend_type, backend_config = await self._resolve_backend_config()\\n        kb_path = self._resolve_store_path(kb_user, backend_type, backend_config)\\n\\n        # ``api_key=None`` is not \\\"no credential\\\": ``get_embeddings`` resolves the\\n        # provider's key from the user's variables table and then the environment,\\n        # exactly as the server-side ingestion path does. The component input just\\n        # takes precedence when supplied.\\n        embedding_function = get_embeddings(\\n            model=model_selection,\\n            user_id=self.user_id,\\n            api_key=self.api_key if getattr(self, \\\"api_key\\\", None) else None,\\n            chunk_size=chunk_size,\\n        )\\n\\n        backend = create_backend(\\n            backend_type,\\n            kb_name=self.knowledge_base,\\n            kb_path=kb_path,\\n            backend_config=backend_config,\\n            embedding_function=embedding_function,\\n            user_id=self.user_id,\\n        )\\n        try:\\n            user_metadata_filter = _parse_metadata_filter(getattr(self, \\\"metadata_filter\\\", None))\\n            use_scores = bool(self.search_query)\\n            search_k = self.top_k * 4 if user_metadata_filter else self.top_k\\n            results = await backend.similarity_search(\\n                query=self.search_query or \\\"\\\",\\n                k=search_k,\\n                with_scores=use_scores,\\n            )\\n            if user_metadata_filter:\\n                results = [\\n                    (doc, score) for doc, score in results if _chunk_matches_filter(doc.metadata, user_metadata_filter)\\n                ]\\n                results = results[: self.top_k]\\n\\n            embeddings_by_key: dict[tuple[str, str], list[float]] = {}\\n            if self.include_embeddings and results:\\n                # Join each retrieved chunk to its stored embedding. We key on\\n                # ``_id`` when present and fall back to page content otherwise,\\n                # so KBs populated by direct file upload \u2014 whose chunks carry no\\n                # ``_id`` \u2014 still resolve. See ``_embedding_match_key``.\\n                wanted_keys = {_embedding_match_key(doc.page_content, doc.metadata) for doc, _score in results}\\n                async for batch in backend.iter_documents(include_embeddings=True):\\n                    for entry in batch:\\n                        if entry.embedding is None:\\n                            continue\\n                        key = _embedding_match_key(entry.content, entry.metadata)\\n                        if key in wanted_keys:\\n                            embeddings_by_key[key] = entry.embedding\\n                    if len(embeddings_by_key) == len(wanted_keys):\\n                        break\\n\\n            data_list: list[Data] = []\\n            for doc, score in results:\\n                kwargs: dict[str, Any] = {\\\"content\\\": doc.page_content}\\n                if use_scores:\\n                    kwargs[\\\"_score\\\"] = -1 * score\\n                if self.include_metadata:\\n                    kwargs.update(doc.metadata)\\n                if self.include_embeddings:\\n                    kwargs[\\\"_embeddings\\\"] = embeddings_by_key.get(_embedding_match_key(doc.page_content, doc.metadata))\\n                data_list.append(Data(**kwargs))\\n\\n            return DataFrame(data=data_list)\\n        finally:\\n            await backend.teardown()\\n\\n\\ndef _embedding_match_key(content: str, metadata: dict[str, Any] | None) -> tuple[str, str]:\\n    \\\"\\\"\\\"Build a stable key for aligning a retrieved chunk with its stored embedding.\\n\\n    Embeddings are gathered separately (via ``iter_documents``) and then joined\\n    back onto the search results. Component-driven ingestion stamps a\\n    content-hash ``_id`` on every chunk, but direct file-upload ingestion\\n    (``KBIngestionHelper.perform_ingestion``) does not. Keying the join purely on\\n    ``_id`` therefore left every upload-populated KB with ``_embeddings: None``.\\n\\n    We prefer ``_id`` when present (so legitimately distinct chunks that happen to\\n    share text aren't collapsed) and fall back to the chunk's page content\\n    otherwise. The content fallback is exact for the embedding use case: two\\n    chunks with identical text necessarily share the same embedding vector. The\\n    leading ``\\\"id\\\"`` / ``\\\"content\\\"`` tag namespaces the two key spaces so a mixed\\n    KB (some chunks with ``_id``, some without) never cross-matches.\\n    \\\"\\\"\\\"\\n    doc_id = metadata.get(\\\"_id\\\") if metadata else None\\n    if doc_id:\\n        return (\\\"id\\\", str(doc_id))\\n    return (\\\"content\\\", content or \\\"\\\")\\n\\n\\ndef _parse_metadata_filter(raw: str | None) -> dict[str, list[str]]:\\n    \\\"\\\"\\\"Decode the ``metadata_filter`` input into a {key: [values]} map.\\n\\n    Empty or malformed input maps to an empty filter so retrieval falls back\\n    to the unfiltered path. JSON errors are swallowed here rather than raised:\\n    surfacing component-config errors at the canvas node would break a flow\\n    run for what is meant to be an optional refinement.\\n    \\\"\\\"\\\"\\n    if not raw:\\n        return {}\\n    text = raw.strip() if isinstance(raw, str) else raw\\n    if not text:\\n        return {}\\n    try:\\n        decoded = json.loads(text)\\n    except (TypeError, json.JSONDecodeError):\\n        logger.warning(\\\"KnowledgeComponent: metadata_filter is not valid JSON; ignoring filter.\\\")\\n        return {}\\n    if not isinstance(decoded, dict):\\n        logger.warning(\\\"KnowledgeComponent: metadata_filter must be a JSON object; ignoring filter.\\\")\\n        return {}\\n    result: dict[str, list[str]] = {}\\n    for key, value in decoded.items():\\n        if not isinstance(key, str):\\n            continue\\n        if isinstance(value, list):\\n            result[key] = [str(entry) for entry in value]\\n        else:\\n            result[key] = [str(value)]\\n    return result\\n\\n\\ndef _chunk_matches_filter(metadata: dict[str, Any] | None, filt: dict[str, list[str]]) -> bool:\\n    \\\"\\\"\\\"AND across keys, OR within key values, mirroring the chunks endpoint.\\\"\\\"\\\"\\n    if not filt:\\n        return True\\n    if not metadata:\\n        return False\\n    raw = metadata.get(\\\"source_metadata\\\")\\n    if not raw:\\n        return False\\n    try:\\n        stored = json.loads(raw) if isinstance(raw, str) else raw\\n    except json.JSONDecodeError:\\n        return False\\n    if not isinstance(stored, dict):\\n        return False\\n    for key, expected_values in filt.items():\\n        actual = stored.get(key)\\n        if actual is None:\\n            return False\\n        actual_set = {str(entry) for entry in actual} if isinstance(actual, list) else {str(actual)}\\n        if not actual_set & set(expected_values):\\n            return False\\n    return True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/files_and_knowledge/memory_retrieval.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c9fde7472919f48499eb84df72c77a1f7f9f0675b232418b3b367c0607b8366c\",\"content\":\"\\\"\\\"\\\"Memory Base retrieval component.\\n\\nQueries the vector store backing a Memory Base, scoped to the current flow's\\nrequest session. Additional option to filter by session_id if the developer wants\\nto turn that on. The component will auto filter based on session_id then.\\n\\nWhere that store lives comes from the Memory Base's ``knowledge_base`` row, not\\nfrom disk: only a local-Chroma Memory Base resolves a filesystem path at all.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport uuid\\nfrom collections.abc import Mapping\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport numpy as np\\nfrom langflow.api.utils.kb_helpers import (\\n    resolve_backend_selection,\\n    resolve_embedding_selection,\\n    resolve_local_store_path,\\n)\\nfrom langflow.services.database.models.memory_base.model import MemoryBase\\nfrom langflow.services.database.models.user.crud import get_user_by_id\\nfrom langflow.services.memory_base.kb_path_helpers import hash_session_id\\nfrom sqlmodel import select\\n\\nfrom lfx.base.knowledge_bases.backends import create_backend\\nfrom lfx.custom import Component\\nfrom lfx.io import BoolInput, DropdownInput, IntInput, MessageTextInput, Output\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.services.deps import session_scope\\nfrom lfx.workflow.end_user_identity import end_user_id_from_scoped_session, serving_end_user_enabled\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.user.model import User\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from lfx.base.knowledge_bases.backends.base import BaseVectorStoreBackend\\n\\n\\ndef _coerce_uuid(value: Any) -> uuid.UUID | None:\\n    if value is None:\\n        return None\\n    if isinstance(value, uuid.UUID):\\n        return value\\n    try:\\n        return uuid.UUID(str(value))\\n    except (ValueError, TypeError):\\n        return None\\n\\n\\ndef _to_python_scalar(value: Any) -> Any:\\n    \\\"\\\"\\\"Convert numpy scalars (int64, float64, bool_, \u2026) to Python primitives.\\n\\n    Chroma persists integer/float metadata as numpy scalars, which break JSON\\n    serialization when this component is consumed as an Agent tool \u2014 LangChain's\\n    tool-output path calls ``vars()`` / iterates the value, both of which fail\\n    on numpy C-extension scalars. Coerce at the boundary so downstream stays\\n    primitive-only.\\n    \\\"\\\"\\\"\\n    if isinstance(value, np.generic):\\n        return value.item()\\n    return value\\n\\n\\ndef _session_filter_enabled(value: Any) -> bool:\\n    \\\"\\\"\\\"Parse serialized false values while keeping unknown values fail-closed.\\\"\\\"\\\"\\n    if isinstance(value, str):\\n        return value.strip().lower() not in {\\\"\\\", \\\"0\\\", \\\"false\\\", \\\"no\\\", \\\"off\\\"}\\n    return bool(value)\\n\\n\\nclass MemoryBaseComponent(Component):\\n    display_name = \\\"Memory Base\\\"\\n    description = (\\n        \\\"Retrieve long-term memory from a Memory Base attached to this workflow. \\\"\\n        \\\"When 'Filter by Session' is off, queries run across all sessions.\\\"\\n    )\\n    icon = \\\"brain\\\"\\n    name = \\\"MemoryBase\\\"\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"memory_base\\\",\\n            display_name=\\\"Memory Base\\\",\\n            info=\\\"Memory Base whose captured conversation history will be searched.\\\",\\n            required=True,\\n            options=[],\\n            refresh_button=True,\\n            real_time_refresh=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"search_query\\\",\\n            display_name=\\\"Search Query\\\",\\n            info=\\\"Query used for semantic retrieval against the memory base.\\\",\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"top_k\\\",\\n            display_name=\\\"Top K Results\\\",\\n            info=\\\"Number of top results to return.\\\",\\n            value=5,\\n            advanced=True,\\n            required=False,\\n        ),\\n        BoolInput(\\n            name=\\\"include_metadata\\\",\\n            display_name=\\\"Include Metadata\\\",\\n            info=\\\"Include chunk metadata (session_id, sender, timestamp, \u2026) on each row.\\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"filter_by_session\\\",\\n            display_name=\\\"Filter by Session\\\",\\n            info=(\\n                \\\"If enabled, only memories from the current session will be retrieved. \\\"\\n                \\\"Disable to allow retrieval across every session ingested into this \\\"\\n                \\\"Memory Base (useful for cross-conversation recall).\\\"\\n            ),\\n            value=True,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            name=\\\"retrieve_data\\\",\\n            display_name=\\\"Results\\\",\\n            method=\\\"retrieve_memory\\\",\\n            info=(\\n                \\\"Returns matching memory chunks. Scoped to the current session by \\\"\\n                \\\"default; turn 'Filter by Session' off to retrieve across sessions.\\\"\\n            ),\\n        ),\\n    ]\\n\\n    async def _policy_embedding_selection(self, selected: str) -> tuple[str, str]:\\n        \\\"\\\"\\\"Resolve an attached Memory Base's non-secret embedding metadata.\\\"\\\"\\\"\\n        flow_id = _coerce_uuid(self._get_runtime_or_frontend_node_attr(\\\"flow_id\\\"))\\n        if flow_id is None:\\n            msg = \\\"flow_id is not available on the graph context; Memory Base retrieval is unavailable.\\\"\\n            raise ValueError(msg)\\n\\n        owner_user_id = _coerce_uuid(self.user_id)\\n        if owner_user_id is None:\\n            msg = \\\"user_id is not available on the graph context; Memory Base retrieval is unavailable.\\\"\\n            raise ValueError(msg)\\n\\n        async with session_scope() as db:\\n            memory_base = (\\n                await db.exec(\\n                    select(MemoryBase).where(\\n                        MemoryBase.name == selected,\\n                        MemoryBase.flow_id == flow_id,\\n                        MemoryBase.user_id == owner_user_id,\\n                    )\\n                )\\n            ).first()\\n        if memory_base is None:\\n            msg = f\\\"Memory Base '{selected}' is not attached to this flow.\\\"\\n            raise ValueError(msg)\\n        return await resolve_embedding_selection(user_id=memory_base.user_id, kb_name=memory_base.kb_name)\\n\\n    async def _additional_model_provider_policy_ids(self, purpose, parameters=None) -> tuple[str, ...]:\\n        \\\"\\\"\\\"Discover the persisted embedding provider before runtime input hydration.\\\"\\\"\\\"\\n        from lfx.base.models.provider_registry import resolve_provider_id\\n        from lfx.services.model_provider_policy import ModelProviderPolicyError\\n\\n        effective_parameters = parameters if isinstance(parameters, Mapping) else getattr(self, \\\"_parameters\\\", None)\\n        if not isinstance(effective_parameters, Mapping):\\n            effective_parameters = {}\\n        selected = effective_parameters.get(\\\"memory_base\\\", getattr(self, \\\"memory_base\\\", None))\\n        if not isinstance(selected, str) or not selected.strip():\\n            return ()\\n\\n        provider, _model = await self._policy_embedding_selection(selected.strip())\\n        if not isinstance(provider, str) or not provider.strip():\\n            unknown_provider = \\\"unknown\\\"\\n            raise ModelProviderPolicyError(unknown_provider, purpose)\\n        return (resolve_provider_id(provider),)\\n\\n    async def arequire_model_provider_policy(self, purpose, *, user_id=None, parameters=None) -> None:\\n        \\\"\\\"\\\"Capture the trusted actor context after the shared pre-hydration gate.\\\"\\\"\\\"\\n        await super().arequire_model_provider_policy(\\n            purpose,\\n            user_id=user_id,\\n            parameters=parameters,\\n        )\\n\\n        from lfx.services.model_provider_policy import current_model_provider_policy_context\\n\\n        actor_user_id = self.user_id if user_id is None else user_id\\n        policy_context = current_model_provider_policy_context()\\n        self._runtime_provider_policy_actor_id = actor_user_id\\n        self._runtime_provider_policy_attributes = (\\n            dict(policy_context.attributes)\\n            if policy_context is not None and str(policy_context.user_id) == str(actor_user_id)\\n            else {}\\n        )\\n\\n    def _build_where_clause(self, *, session_id: str | None = None, end_user_id: str | None = None) -> dict | None:\\n        \\\"\\\"\\\"Compose the metadata filter based on opt-in filters and manual params.\\n\\n        Emits a flat ``{key: value}`` dict, which is the contract every\\n        ``BaseVectorStoreBackend`` accepts: Chroma reads it as ``$eq`` shorthand\\n        and OpenSearch translates it into a bool query. Chroma's explicit\\n        ``{\\\"$eq\\\": ...}`` operator form is NOT portable \u2014 a remote backend would\\n        treat the operator dict as a literal value and silently match nothing.\\n\\n        When ``filter_by_session`` is on, the session-id predicate already scopes to one\\n        end user (its ``<end_user>::<base>`` prefix). When it is off (cross-session recall)\\n        on the serving plane, ``end_user_id`` keeps the query within that one end user so it\\n        does not span every end user's chunks in the shared service-account store. Off /\\n        editor (``end_user_id`` None) adds neither predicate \u2014 all sessions, unchanged.\\n        \\\"\\\"\\\"\\n        predicates: dict = {}\\n        if _session_filter_enabled(self.filter_by_session) and session_id:\\n            predicates[\\\"session_id\\\"] = str(session_id)\\n        elif end_user_id:\\n            predicates[\\\"end_user_id\\\"] = str(end_user_id)\\n\\n        return predicates or None\\n\\n    async def update_build_config(self, build_config, field_value, field_name=None):  # noqa: ARG002\\n        if field_name != \\\"memory_base\\\":\\n            return build_config\\n\\n        flow_id = _coerce_uuid(self._get_runtime_or_frontend_node_attr(\\\"flow_id\\\"))\\n        user_uuid = _coerce_uuid(self.user_id)\\n        if flow_id is None or user_uuid is None:\\n            build_config[\\\"memory_base\\\"][\\\"options\\\"] = []\\n            build_config[\\\"memory_base\\\"][\\\"value\\\"] = None\\n            return build_config\\n\\n        # At design time self.user_id == the flow developer == MB owner, so this\\n        # filters to the same set a Flow-lookup would return but without relying\\n        # on the Flow row being persisted yet.\\n        async with session_scope() as db:\\n            stmt = select(MemoryBase).where(\\n                MemoryBase.flow_id == flow_id,\\n                MemoryBase.user_id == user_uuid,\\n            )\\n            mbs = list((await db.exec(stmt)).all())\\n\\n        options = sorted(mb.name for mb in mbs)\\n        build_config[\\\"memory_base\\\"][\\\"options\\\"] = options\\n        if build_config[\\\"memory_base\\\"].get(\\\"value\\\") not in options:\\n            build_config[\\\"memory_base\\\"][\\\"value\\\"] = None\\n        return build_config\\n\\n    async def _resolve_attached_mb(\\n        self,\\n        db: AsyncSession,\\n        selected: str,\\n        flow_id: uuid.UUID,\\n        execution_user_id: uuid.UUID,\\n    ) -> tuple[MemoryBase, User]:\\n        \\\"\\\"\\\"Look up the MB row scoped to the exact flow execution principal.\\\"\\\"\\\"\\n        mb = (\\n            await db.exec(\\n                select(MemoryBase).where(\\n                    MemoryBase.name == selected,\\n                    MemoryBase.flow_id == flow_id,\\n                    MemoryBase.user_id == execution_user_id,\\n                )\\n            )\\n        ).first()\\n        if mb is None:\\n            msg = f\\\"Memory Base '{selected}' is not attached to this flow.\\\"\\n            raise ValueError(msg)\\n\\n        owner = await get_user_by_id(db, mb.user_id)\\n        if owner is None:\\n            msg = \\\"Memory Base owner account could not be resolved.\\\"\\n            raise ValueError(msg)\\n        return mb, owner\\n\\n    async def _build_backend(\\n        self,\\n        owner: User,\\n        owner_username: str,\\n        kb_name: str,\\n    ) -> BaseVectorStoreBackend:\\n        \\\"\\\"\\\"Construct the KB's configured backend, wired to its embedding function.\\n\\n        The embedding config and the backend both resolve from the\\n        ``knowledge_base`` row, so nothing on disk is consulted to decide *where*\\n        this Memory Base lives. A local path is then derived only when that row\\n        says local Chroma; for OpenSearch, pgVector, or Chroma Cloud it stays\\n        ``None`` and the filesystem is never touched. That is what lets a\\n        Memory Base be queried \u2014 with the right embedding model \u2014 from a replica\\n        whose local disk never held the KB directory.\\n        \\\"\\\"\\\"\\n        # Re-resolve the persisted selection and actor policy immediately before\\n        # owner credential access. The graph-level preflight runs before input\\n        # hydration; this repeat also closes a metadata-change race between that\\n        # boundary and backend construction.\\n        provider, model = await resolve_embedding_selection(user_id=owner.id, kb_name=kb_name)\\n        provider_policy = await self._resolve_runtime_embedding_policy(provider, owner.id)\\n\\n        # Resolve where this Memory Base lives before constructing a provider\\n        # client. Path containment and backend metadata do not read embedding\\n        # credentials.\\n        backend_type, backend_config = await resolve_backend_selection(user_id=owner.id, kb_name=kb_name)\\n        try:\\n            kb_path = resolve_local_store_path(\\n                kb_name,\\n                owner_username,\\n                backend_type=backend_type,\\n                backend_config=backend_config,\\n            )\\n        except ValueError as exc:\\n            msg = \\\"Memory Base path is not accessible.\\\"\\n            raise ValueError(msg) from exc\\n\\n        embedding_function = self._build_embeddings_with_policy(\\n            provider,\\n            model,\\n            owner_user_id=owner.id,\\n            provider_policy=provider_policy,\\n        )\\n\\n        backend = create_backend(\\n            backend_type,\\n            kb_name=kb_name,\\n            kb_path=kb_path,\\n            backend_config=backend_config,\\n            embedding_function=embedding_function,\\n            user_id=owner.id,\\n        )\\n        await backend.ensure_ready()\\n        return backend\\n\\n    async def _resolve_runtime_embedding_policy(self, provider: str, owner_user_id: uuid.UUID):\\n        \\\"\\\"\\\"Refresh actor-scoped provider policy before owner credential lookup.\\\"\\\"\\\"\\n        from lfx.services.model_provider_policy import (\\n            ModelProviderPolicyPurpose,\\n            aresolve_model_provider_policy,\\n            current_model_provider_policy_context,\\n        )\\n\\n        actor_user_id = getattr(self, \\\"_runtime_provider_policy_actor_id\\\", None)\\n        attributes = getattr(self, \\\"_runtime_provider_policy_attributes\\\", None)\\n        if actor_user_id is None:\\n            policy_context = current_model_provider_policy_context()\\n            if policy_context is not None:\\n                actor_user_id = policy_context.user_id\\n                attributes = dict(policy_context.attributes)\\n            else:\\n                actor_user_id = owner_user_id\\n                attributes = {}\\n\\n        snapshot = await aresolve_model_provider_policy(\\n            user_id=actor_user_id,\\n            providers=[provider],\\n            purpose=ModelProviderPolicyPurpose.USE,\\n            attributes=attributes,\\n        )\\n        snapshot.require(provider)\\n        return snapshot\\n\\n    @staticmethod\\n    def _build_embeddings_with_policy(provider: str, model: str, *, owner_user_id, provider_policy):\\n        \\\"\\\"\\\"Build with owner credentials while reusing the actor's trusted decision.\\\"\\\"\\\"\\n        from lfx.base.models.unified_models import get_embeddings\\n        from lfx.base.models.unified_models.class_registry import (\\n            EMBEDDING_PARAM_MAPPINGS,\\n            EMBEDDING_PROVIDER_CLASS_MAPPING,\\n        )\\n\\n        embedding_class = EMBEDDING_PROVIDER_CLASS_MAPPING.get(provider)\\n        param_mapping = EMBEDDING_PARAM_MAPPINGS.get(provider)\\n        if not embedding_class or not param_mapping:\\n            msg = f\\\"Embedding provider '{provider}' is not registered\\\"\\n            raise ValueError(msg)\\n        selected_option = {\\n            \\\"name\\\": model,\\n            \\\"provider\\\": provider,\\n            \\\"category\\\": provider,\\n            \\\"icon\\\": provider,\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": embedding_class,\\n                \\\"param_mapping\\\": param_mapping,\\n                \\\"model_type\\\": \\\"embeddings\\\",\\n            },\\n        }\\n        return get_embeddings(\\n            model=[selected_option],\\n            user_id=owner_user_id,\\n            provider_policy=provider_policy,\\n        )\\n\\n    def _format_results(self, results: list[tuple], backend: BaseVectorStoreBackend) -> DataFrame:\\n        \\\"\\\"\\\"Convert backend ``(doc, score)`` tuples into the component's DataFrame output.\\n\\n        Metadata values are coerced from numpy scalars to Python primitives so the\\n        resulting DataFrame is JSON-serializable when the component is invoked as\\n        an Agent tool.\\n        \\\"\\\"\\\"\\n        data_list: list[Data] = []\\n        for doc, score in results:\\n            kwargs: dict = {\\\"content\\\": doc.page_content}\\n            if self.search_query:\\n                kwargs[\\\"_score\\\"] = _to_python_scalar(backend.normalize_score(score))\\n            if self.include_metadata:\\n                for key, value in (doc.metadata or {}).items():\\n                    kwargs[key] = _to_python_scalar(value)\\n            data_list.append(Data(**kwargs))\\n        return DataFrame(data=data_list)\\n\\n    async def retrieve_memory(self) -> DataFrame:\\n        \\\"\\\"\\\"Retrieve chunks from the selected Memory Base.\\n\\n        Scoped to the current ``session_id`` when ``filter_by_session`` is true; when\\n        false, every chunk in the Memory Base is queryable so the agent can recall\\n        context from prior conversations across all sessions.\\n        \\\"\\\"\\\"\\n        session_id = getattr(self.graph, \\\"session_id\\\", None)\\n        filter_on = _session_filter_enabled(self.filter_by_session)\\n        if filter_on and not session_id:\\n            # Only required when filtering is on, since the value gates the where clause.\\n            msg = (\\n                \\\"A session_id is required on the flow request when 'Filter by Session' \\\"\\n                \\\"is enabled \u2014 disable the toggle to allow cross-session retrieval.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        # Serving plane: the end-user id lives in the scoped session prefix. When filtering\\n        # by session it is already scoped; when doing cross-session recall it becomes the\\n        # sole end-user predicate (see _build_where_clause).\\n        end_user_id = end_user_id_from_scoped_session(session_id)\\n        if serving_end_user_enabled() and not filter_on and end_user_id is None:\\n            # Fail-closed: an anonymous serving caller has no end-user scope, so\\n            # cross-session recall over the shared service-account store would return every\\n            # end user's memory. Anonymous runs persist nothing and have no cross-session\\n            # memory to recall, so return empty rather than leak.\\n            logger.debug(\\\"MemoryBase cross-session recall blocked for anonymous serving caller\\\")\\n            return DataFrame(data=[])\\n\\n        flow_id = _coerce_uuid(getattr(self.graph, \\\"flow_id\\\", None))\\n        if flow_id is None:\\n            msg = \\\"flow_id is not available on the graph context; Memory Base retrieval is unavailable.\\\"\\n            raise ValueError(msg)\\n\\n        execution_user_id = _coerce_uuid(getattr(self.graph, \\\"user_id\\\", None))\\n        if execution_user_id is None:\\n            msg = \\\"user_id is not available on the graph context; Memory Base retrieval is unavailable.\\\"\\n            raise ValueError(msg)\\n\\n        selected = self.memory_base\\n        if not selected:\\n            msg = \\\"No Memory Base is selected.\\\"\\n            raise ValueError(msg)\\n\\n        async with session_scope() as db:\\n            mb, owner = await self._resolve_attached_mb(db, selected, flow_id, execution_user_id)\\n            owner_username = owner.username\\n            kb_name = mb.kb_name\\n\\n        where = self._build_where_clause(session_id=session_id, end_user_id=end_user_id)\\n\\n        logger.debug(\\n            \\\"MemoryBase retrieval mb=%s session_hash=%s session_filter=%s top_k=%s\\\",\\n            selected,\\n            hash_session_id(session_id) if session_id else \\\"<none>\\\",\\n            where is not None,\\n            self.top_k,\\n        )\\n\\n        if not self.search_query:\\n            # Embedding providers may reject empty input; skip the round-trip entirely.\\n            return DataFrame(data=[])\\n\\n        backend = await self._build_backend(owner, owner_username, kb_name)\\n        try:\\n            results = await backend.similarity_search(\\n                query=self.search_query,\\n                k=self.top_k,\\n                filter=where,\\n                with_scores=True,\\n            )\\n        finally:\\n            await backend.teardown()\\n        return self._format_results(results, backend)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/files_and_knowledge/retrieval.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ffe12d6bb75f743fec08e25b9bca2a48857c9301437cbcded0fe4fed4839386f\",\"content\":\"\\\"\\\"\\\"Knowledge Base retrieval component \u2014 backward-compat shim.\\n\\nThe full implementation now lives in\\n:mod:`lfx.components.files_and_knowledge.knowledge` as the mode-driven\\n:class:`KnowledgeComponent`. ``KnowledgeBaseComponent`` remains as a thin\\nsubclass so saved flows referencing the legacy node id (``KnowledgeBase``)\\nand the legacy module path keep loading and running unchanged.\\n\\nThe module-level ``_parse_metadata_filter`` / ``_chunk_matches_filter``\\nhelpers are re-exported here because existing unit tests import them\\nfrom this module path \u2014 see\\n``src/backend/tests/unit/components/files_and_knowledge/test_retrieval.py``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom lfx.components.files_and_knowledge.knowledge import (\\n    MODE_RETRIEVE,\\n    KnowledgeComponent,\\n    _chunk_matches_filter,\\n    _inputs_for_mode,\\n    _parse_metadata_filter,\\n)\\nfrom lfx.io import Output\\n\\n__all__ = [\\n    \\\"KnowledgeBaseComponent\\\",\\n    \\\"_chunk_matches_filter\\\",\\n    \\\"_parse_metadata_filter\\\",\\n]\\n\\nastra_error_msg = \\\"Knowledge retrieval is not supported in Astra cloud environment.\\\"\\n\\n\\nclass KnowledgeBaseComponent(KnowledgeComponent):\\n    \\\"\\\"\\\"Search and retrieve data from knowledge.\\n\\n    Pins the merged :class:`KnowledgeComponent` to retrieve mode. All\\n    behavior is inherited unchanged.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Knowledge Base\\\"\\n    description = \\\"Search and retrieve data from knowledge.\\\"\\n    icon = \\\"download\\\"\\n    name = \\\"KnowledgeBase\\\"\\n    # Hidden from the default palette \u2014 surfaces only when a saved flow\\n    # already references it. New flows should pick ``Knowledge`` instead.\\n    legacy = True\\n    replacement = [\\\"files_and_knowledge.Knowledge\\\"]\\n\\n    # Pin the mode-default visibility at the class level so the canvas\\n    # renders the legacy \\\"retrieve-only\\\" shape on first load.\\n    inputs = _inputs_for_mode(MODE_RETRIEVE)\\n    outputs = [\\n        Output(\\n            display_name=\\\"Results\\\",\\n            name=\\\"retrieve_data\\\",\\n            method=\\\"retrieve_data\\\",\\n            info=\\\"Returns the data from the selected knowledge base.\\\",\\n            types=[\\\"Table\\\"],\\n            selected=\\\"Table\\\",\\n        ),\\n    ]\\n\\n    def __init__(self, *args: Any, **kwargs: Any) -> None:\\n        super().__init__(*args, **kwargs)\\n        self.mode = MODE_RETRIEVE\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/files_and_knowledge/save_file.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"06768dd5465c8c0fdda9792cdd991cb73a80cbf4299d473d3ba4a28d8309679b\",\"content\":\"import contextlib\\nimport json\\nimport re\\nfrom collections.abc import AsyncIterator, Iterator\\nfrom pathlib import Path, PurePath, PureWindowsPath\\nfrom typing import Any\\n\\nimport orjson\\nimport pandas as pd\\nfrom fastapi import UploadFile\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom lfx.custom import Component\\nfrom lfx.inputs import SortableListInput\\nfrom lfx.inputs.inputs import DataFrameInput\\nfrom lfx.io import BoolInput, DropdownInput, SecretStrInput, StrInput\\nfrom lfx.schema import Data, DataFrame, Message\\nfrom lfx.services.deps import get_settings_service, get_storage_service, session_scope\\nfrom lfx.template.field.base import Output\\nfrom lfx.utils.file_path_security import component_file_access_scopes, enforce_local_file_access\\nfrom lfx.utils.validate_cloud import is_astra_cloud_environment\\n\\n\\ndef _get_storage_location_options():\\n    \\\"\\\"\\\"Get storage location options, filtering out Local if in Astra cloud environment.\\\"\\\"\\\"\\n    all_options = [{\\\"name\\\": \\\"AWS\\\", \\\"icon\\\": \\\"Amazon\\\"}, {\\\"name\\\": \\\"Google Drive\\\", \\\"icon\\\": \\\"google\\\"}]\\n    if is_astra_cloud_environment():\\n        return all_options\\n    return [{\\\"name\\\": \\\"Local\\\", \\\"icon\\\": \\\"hard-drive\\\"}, *all_options]\\n\\n\\ndef _get_default_storage_location() -> list[dict[str, str]]:\\n    \\\"\\\"\\\"Return the default storage selection for the component template.\\\"\\\"\\\"\\n    return [_get_storage_location_options()[0]]\\n\\n\\ndef _is_default_storage(storage_name: str) -> bool:\\n    \\\"\\\"\\\"Check whether a storage type is the default selection.\\\"\\\"\\\"\\n    return _get_default_storage_location()[0][\\\"name\\\"] == storage_name\\n\\n\\nclass SaveToFileComponent(Component):\\n    display_name = \\\"Write File\\\"\\n    description = \\\"Save content to a file in the specified format and return its path.\\\"\\n    documentation: str = \\\"https://docs.langflow.org/write-file\\\"\\n    icon = \\\"file-text\\\"\\n    name = \\\"SaveToFile\\\"\\n\\n    # File format options for different storage types\\n    LOCAL_DATA_FORMAT_CHOICES = [\\\"csv\\\", \\\"excel\\\", \\\"json\\\", \\\"markdown\\\"]\\n    LOCAL_MESSAGE_FORMAT_CHOICES = [\\\"txt\\\", \\\"html\\\", \\\"json\\\", \\\"markdown\\\"]\\n    AWS_FORMAT_CHOICES = [\\n        \\\"txt\\\",\\n        \\\"json\\\",\\n        \\\"csv\\\",\\n        \\\"xml\\\",\\n        \\\"html\\\",\\n        \\\"md\\\",\\n        \\\"yaml\\\",\\n        \\\"log\\\",\\n        \\\"tsv\\\",\\n        \\\"jsonl\\\",\\n        \\\"parquet\\\",\\n        \\\"xlsx\\\",\\n        \\\"zip\\\",\\n    ]\\n    GDRIVE_FORMAT_CHOICES = [\\\"txt\\\", \\\"html\\\", \\\"json\\\", \\\"csv\\\", \\\"xlsx\\\", \\\"slides\\\", \\\"docs\\\", \\\"jpg\\\", \\\"mp3\\\"]\\n\\n    inputs = [\\n        SortableListInput(\\n            name=\\\"storage_location\\\",\\n            display_name=\\\"Storage Location\\\",\\n            placeholder=\\\"Select Location\\\",\\n            info=\\\"Choose where to save the file.\\\",\\n            options=_get_storage_location_options(),\\n            real_time_refresh=True,\\n            limit=1,\\n            value=_get_default_storage_location(),\\n            advanced=True,\\n        ),\\n        # Common inputs\\n        DataFrameInput(\\n            name=\\\"input\\\",\\n            display_name=\\\"File Content\\\",\\n            info=(\\n                \\\"The content to save. Accepts a DataFrame, Data, or Message object directly. \\\"\\n                'Can also accept a JSON string (e.g. \\\\'[{\\\"col1\\\": \\\"val1\\\"}]\\\\') which will be '\\n                \\\"parsed into a DataFrame, or plain text which will be saved as a Message.\\\"\\n            ),\\n            input_types=[\\\"Data\\\", \\\"JSON\\\", \\\"DataFrame\\\", \\\"Table\\\", \\\"Message\\\"],\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        StrInput(\\n            name=\\\"file_name\\\",\\n            display_name=\\\"File Name\\\",\\n            info=\\\"File name without extension (e.g. 'report'). Extension is added automatically.\\\",\\n            required=True,\\n            show=True,\\n            tool_mode=True,\\n        ),\\n        StrInput(\\n            name=\\\"file_format\\\",\\n            display_name=\\\"File Format (Tool)\\\",\\n            info=\\\"Output format: 'csv', 'json', 'txt', 'html', 'excel', 'markdown'. Overrides pre-configured format.\\\",\\n            required=False,\\n            show=False,\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"append_mode\\\",\\n            display_name=\\\"Append\\\",\\n            info=(\\n                \\\"Append to file if it exists (only for Local storage with plain text formats). \\\"\\n                \\\"Not supported for cloud storage (AWS/Google Drive).\\\"\\n            ),\\n            value=False,\\n            show=_is_default_storage(\\\"Local\\\"),\\n        ),\\n        # Format inputs (dynamic based on storage location)\\n        DropdownInput(\\n            name=\\\"local_format\\\",\\n            display_name=\\\"File Format\\\",\\n            options=list(dict.fromkeys(LOCAL_DATA_FORMAT_CHOICES + LOCAL_MESSAGE_FORMAT_CHOICES)),\\n            info=\\\"Select the file format for local storage.\\\",\\n            value=\\\"json\\\",\\n            show=_is_default_storage(\\\"Local\\\"),\\n        ),\\n        DropdownInput(\\n            name=\\\"aws_format\\\",\\n            display_name=\\\"File Format\\\",\\n            options=AWS_FORMAT_CHOICES,\\n            info=\\\"Select the file format for AWS S3 storage.\\\",\\n            value=\\\"txt\\\",\\n            show=_is_default_storage(\\\"AWS\\\"),\\n        ),\\n        DropdownInput(\\n            name=\\\"gdrive_format\\\",\\n            display_name=\\\"File Format\\\",\\n            options=GDRIVE_FORMAT_CHOICES,\\n            info=\\\"Select the file format for Google Drive storage.\\\",\\n            value=\\\"txt\\\",\\n            show=_is_default_storage(\\\"Google Drive\\\"),\\n        ),\\n        # AWS S3 specific inputs\\n        SecretStrInput(\\n            name=\\\"aws_access_key_id\\\",\\n            display_name=\\\"AWS Access Key ID\\\",\\n            info=\\\"Optional. Falls back to the AWS_ACCESS_KEY_ID environment variable.\\\",\\n            show=_is_default_storage(\\\"AWS\\\"),\\n            advanced=not _is_default_storage(\\\"AWS\\\"),\\n            required=False,\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_secret_access_key\\\",\\n            display_name=\\\"AWS Secret Key\\\",\\n            info=\\\"Optional. Falls back to the AWS_SECRET_ACCESS_KEY environment variable.\\\",\\n            show=_is_default_storage(\\\"AWS\\\"),\\n            advanced=not _is_default_storage(\\\"AWS\\\"),\\n            required=False,\\n        ),\\n        StrInput(\\n            name=\\\"bucket_name\\\",\\n            display_name=\\\"S3 Bucket Name\\\",\\n            info=\\\"Optional. Falls back to the configured object storage bucket.\\\",\\n            show=_is_default_storage(\\\"AWS\\\"),\\n            advanced=not _is_default_storage(\\\"AWS\\\"),\\n            required=False,\\n        ),\\n        StrInput(\\n            name=\\\"aws_region\\\",\\n            display_name=\\\"AWS Region\\\",\\n            info=\\\"AWS region (e.g., us-east-1, eu-west-1).\\\",\\n            show=_is_default_storage(\\\"AWS\\\"),\\n            advanced=not _is_default_storage(\\\"AWS\\\"),\\n        ),\\n        StrInput(\\n            name=\\\"s3_prefix\\\",\\n            display_name=\\\"S3 Prefix\\\",\\n            info=\\\"Prefix for all files in S3.\\\",\\n            show=_is_default_storage(\\\"AWS\\\"),\\n            advanced=not _is_default_storage(\\\"AWS\\\"),\\n        ),\\n        # Google Drive specific inputs\\n        SecretStrInput(\\n            name=\\\"service_account_key\\\",\\n            display_name=\\\"GCP Credentials Secret Key\\\",\\n            info=\\\"Your Google Cloud Platform service account JSON key as a secret string (complete JSON content).\\\",\\n            show=_is_default_storage(\\\"Google Drive\\\"),\\n            advanced=not _is_default_storage(\\\"Google Drive\\\"),\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"folder_id\\\",\\n            display_name=\\\"Google Drive Folder ID\\\",\\n            info=(\\n                \\\"The Google Drive folder ID where the file will be uploaded. \\\"\\n                \\\"The folder must be shared with the service account email.\\\"\\n            ),\\n            required=True,\\n            show=_is_default_storage(\\\"Google Drive\\\"),\\n            advanced=not _is_default_storage(\\\"Google Drive\\\"),\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"File Path\\\",\\n            name=\\\"message\\\",\\n            method=\\\"save_to_file\\\",\\n            # Tool-facing documentation: ``build_description`` prefers output\\n            # ``info`` over the component description when this component is\\n            # exposed as an agent tool, so the argument reference lives here\\n            # instead of bloating the UI card description.\\n            info=(\\n                \\\"Save data to a file. \\\"\\n                \\\"Arguments: 'input' \u2014 the content to save (pass a DataFrame directly, or a JSON string \\\"\\n                \\\"for tabular data, or plain text for messages); \\\"\\n                \\\"'file_name' \u2014 the name to save as, without extension (e.g. 'report'); \\\"\\n                \\\"'file_format' \u2014 output format: 'csv', 'json', 'txt', 'html', 'excel', 'markdown' (optional). \\\"\\n                \\\"Returns a confirmation with the file path or URL.\\\"\\n            ),\\n        )\\n    ]\\n\\n    def update_build_config(self, build_config, field_value, field_name=None):\\n        \\\"\\\"\\\"Update build configuration to show/hide fields based on storage location selection.\\\"\\\"\\\"\\n        # Update options dynamically based on cloud environment\\n        # This ensures options are refreshed when build_config is updated\\n        if \\\"storage_location\\\" in build_config:\\n            updated_options = _get_storage_location_options()\\n            build_config[\\\"storage_location\\\"][\\\"options\\\"] = updated_options\\n\\n        # When tool_mode is toggled, hide storage-specific format dropdowns\\n        # (the agent uses the unified file_format input instead)\\n        if field_name == \\\"tool_mode\\\":\\n            format_fields = [\\\"local_format\\\", \\\"aws_format\\\", \\\"gdrive_format\\\"]\\n            for f_name in format_fields:\\n                if f_name in build_config:\\n                    build_config[f_name][\\\"show\\\"] = not bool(field_value)\\n            return build_config\\n\\n        if field_name != \\\"storage_location\\\":\\n            return build_config\\n\\n        # Extract selected storage location\\n        selected = [location[\\\"name\\\"] for location in field_value] if isinstance(field_value, list) else []\\n\\n        # Hide all dynamic fields first\\n        dynamic_fields = [\\n            \\\"file_name\\\",  # Common fields (input is always visible)\\n            \\\"append_mode\\\",\\n            \\\"local_format\\\",\\n            \\\"aws_format\\\",\\n            \\\"gdrive_format\\\",\\n            \\\"aws_access_key_id\\\",\\n            \\\"aws_secret_access_key\\\",\\n            \\\"bucket_name\\\",\\n            \\\"aws_region\\\",\\n            \\\"s3_prefix\\\",\\n            \\\"service_account_key\\\",\\n            \\\"folder_id\\\",\\n        ]\\n\\n        for f_name in dynamic_fields:\\n            if f_name in build_config:\\n                build_config[f_name][\\\"show\\\"] = False\\n\\n        # Show fields based on selected storage location\\n        is_tool_mode = build_config.get(\\\"tools_metadata\\\", {}).get(\\\"show\\\", False)\\n\\n        if len(selected) == 1:\\n            location = selected[0]\\n\\n            # Show file_name when any storage location is selected\\n            if \\\"file_name\\\" in build_config:\\n                build_config[\\\"file_name\\\"][\\\"show\\\"] = True\\n\\n            # Show append_mode only for Local storage (not supported for cloud storage)\\n            if \\\"append_mode\\\" in build_config:\\n                build_config[\\\"append_mode\\\"][\\\"show\\\"] = location == \\\"Local\\\"\\n\\n            if location == \\\"Local\\\":\\n                if \\\"local_format\\\" in build_config:\\n                    build_config[\\\"local_format\\\"][\\\"show\\\"] = not is_tool_mode\\n\\n            elif location == \\\"AWS\\\":\\n                aws_fields = [\\n                    \\\"aws_format\\\",\\n                    \\\"aws_access_key_id\\\",\\n                    \\\"aws_secret_access_key\\\",\\n                    \\\"bucket_name\\\",\\n                    \\\"aws_region\\\",\\n                    \\\"s3_prefix\\\",\\n                ]\\n                for f_name in aws_fields:\\n                    if f_name in build_config:\\n                        show = f_name != \\\"aws_format\\\" or not is_tool_mode\\n                        build_config[f_name][\\\"show\\\"] = show\\n                        build_config[f_name][\\\"advanced\\\"] = False\\n\\n            elif location == \\\"Google Drive\\\":\\n                gdrive_fields = [\\\"gdrive_format\\\", \\\"service_account_key\\\", \\\"folder_id\\\"]\\n                for f_name in gdrive_fields:\\n                    if f_name in build_config:\\n                        show = f_name != \\\"gdrive_format\\\" or not is_tool_mode\\n                        build_config[f_name][\\\"show\\\"] = show\\n                        build_config[f_name][\\\"advanced\\\"] = False\\n\\n        return build_config\\n\\n    async def save_to_file(self) -> Message:\\n        \\\"\\\"\\\"Save the input to a file and upload it, returning a confirmation message.\\\"\\\"\\\"\\n        # Validate inputs\\n        if not self.file_name:\\n            msg = \\\"File name must be provided.\\\"\\n            raise ValueError(msg)\\n        if not self._get_input_type():\\n            msg = \\\"Input type is not set.\\\"\\n            raise ValueError(msg)\\n\\n        # Get selected storage location\\n        storage_location = self._get_selected_storage_location()\\n        if not storage_location:\\n            msg = \\\"Storage location must be selected.\\\"\\n            raise ValueError(msg)\\n\\n        # Check if Local storage is disabled in cloud environment\\n        if storage_location == \\\"Local\\\" and is_astra_cloud_environment():\\n            msg = \\\"Local storage is not available in cloud environment. Please use AWS or Google Drive.\\\"\\n            raise ValueError(msg)\\n\\n        # Route to appropriate save method based on storage location\\n        if storage_location == \\\"Local\\\":\\n            return await self._save_to_local()\\n        if storage_location == \\\"AWS\\\":\\n            return await self._save_to_aws()\\n        if storage_location == \\\"Google Drive\\\":\\n            return await self._save_to_google_drive()\\n        msg = f\\\"Unsupported storage location: {storage_location}\\\"\\n        raise ValueError(msg)\\n\\n    def _get_input_type(self) -> str:\\n        \\\"\\\"\\\"Determine the input type based on the provided input.\\\"\\\"\\\"\\n        # Use exact type checking (type() is) instead of isinstance() to avoid inheritance issues.\\n        # Since Message inherits from Data, isinstance(message, Data) would return True for Message objects,\\n        # causing Message inputs to be incorrectly identified as Data type.\\n        if type(self.input) is DataFrame:\\n            return \\\"DataFrame\\\"\\n        if type(self.input) is Message:\\n            return \\\"Message\\\"\\n        if type(self.input) is Data:\\n            return \\\"Data\\\"\\n        # When invoked by a code agent (e.g. OpenDsStar), the input may be a raw\\n        # pandas DataFrame rather than Langflow's DataFrame wrapper.\\n        if isinstance(self.input, pd.DataFrame):\\n            self.input = DataFrame(self.input)\\n            return \\\"DataFrame\\\"\\n        # When invoked as a tool, the agent passes a string. Try to parse it as\\n        # tabular JSON (list of objects) \u2192 DataFrame, otherwise wrap as Message.\\n        if isinstance(self.input, str):\\n            self.input = self._coerce_string_input(self.input)\\n            return self._get_input_type()\\n        msg = f\\\"Unsupported input type: {type(self.input)}\\\"\\n        raise ValueError(msg)\\n\\n    def _coerce_string_input(self, value: str) -> DataFrame | Message:\\n        \\\"\\\"\\\"Convert a raw string (from agent tool call) into a DataFrame or Message.\\n\\n        Tries to parse as JSON first \u2014 a list of objects or a single object becomes\\n        a DataFrame. Anything else is wrapped in a Message.\\n        \\\"\\\"\\\"\\n        try:\\n            parsed = json.loads(value)\\n            if isinstance(parsed, list) and parsed and isinstance(parsed[0], dict):\\n                return DataFrame(pd.DataFrame(parsed))\\n            if isinstance(parsed, dict):\\n                return DataFrame(pd.DataFrame([parsed]))\\n        except (json.JSONDecodeError, ValueError):\\n            pass\\n        return Message(text=value)\\n\\n    def _get_default_format(self) -> str:\\n        \\\"\\\"\\\"Return the default file format based on input type.\\\"\\\"\\\"\\n        if self._get_input_type() == \\\"DataFrame\\\":\\n            return \\\"csv\\\"\\n        if self._get_input_type() == \\\"Data\\\":\\n            return \\\"json\\\"\\n        if self._get_input_type() == \\\"Message\\\":\\n            return \\\"json\\\"\\n        return \\\"json\\\"  # Fallback\\n\\n    def _adjust_file_path_with_format(self, path: Path, fmt: str) -> Path:\\n        \\\"\\\"\\\"Adjust the file path to include the correct extension.\\\"\\\"\\\"\\n        file_extension = path.suffix.lower().lstrip(\\\".\\\")\\n        if fmt == \\\"excel\\\":\\n            return Path(f\\\"{path}.xlsx\\\").expanduser() if file_extension not in [\\\"xlsx\\\", \\\"xls\\\"] else path\\n        return Path(f\\\"{path}.{fmt}\\\").expanduser() if file_extension != fmt else path\\n\\n    def _get_safe_local_file_name(self) -> str:\\n        \\\"\\\"\\\"Return a local file basename, rejecting paths before any file access.\\\"\\\"\\\"\\n        file_name = str(self.file_name).strip()\\n        if not file_name:\\n            msg = \\\"File name must be provided.\\\"\\n            raise ValueError(msg)\\n\\n        local_path = PurePath(file_name)\\n        windows_path = PureWindowsPath(file_name)\\n        path_parts = (*local_path.parts, *windows_path.parts)\\n\\n        if (\\n            \\\"\\\\x00\\\" in file_name\\n            or local_path.is_absolute()\\n            or windows_path.is_absolute()\\n            or windows_path.drive\\n            or len(local_path.parts) != 1\\n            or len(windows_path.parts) != 1\\n            or any(part in {\\\"\\\", \\\".\\\", \\\"..\\\"} for part in path_parts)\\n        ):\\n            msg = \\\"Local file name must be a file name only, without paths or parent directory references.\\\"\\n            raise ValueError(msg)\\n\\n        return file_name\\n\\n    def _is_plain_text_format(self, fmt: str) -> bool:\\n        \\\"\\\"\\\"Check if a file format is plain text (supports appending).\\\"\\\"\\\"\\n        plain_text_formats = [\\\"txt\\\", \\\"json\\\", \\\"markdown\\\", \\\"md\\\", \\\"csv\\\", \\\"xml\\\", \\\"html\\\", \\\"yaml\\\", \\\"log\\\", \\\"tsv\\\", \\\"jsonl\\\"]\\n        return fmt.lower() in plain_text_formats\\n\\n    async def _upload_file(self, file_path: Path) -> Any:\\n        \\\"\\\"\\\"Upload the saved file using the upload_user_file service.\\n\\n        Returns the ``UploadFileResponse`` (with the durable storage ``path`` and\\n        ``provider``) so the caller can report the real destination and, for\\n        remote backends, discard the local staging copy.\\n        \\\"\\\"\\\"\\n        from langflow.api.v2.files import upload_user_file\\n        from langflow.services.database.models.user.crud import get_user_by_id\\n\\n        # Ensure the file exists\\n        if not file_path.exists():\\n            msg = f\\\"File not found: {file_path}\\\"\\n            raise FileNotFoundError(msg)\\n\\n        # Upload the file - always use append=False because the local file already contains\\n        # the correct content (either new or appended locally)\\n        with file_path.open(\\\"rb\\\") as f:\\n            async with session_scope() as db:\\n                if not self.user_id:\\n                    msg = \\\"User ID is required for file saving.\\\"\\n                    raise ValueError(msg)\\n                current_user = await get_user_by_id(db, self.user_id)\\n\\n                return await upload_user_file(\\n                    file=UploadFile(filename=file_path.name, file=f, size=file_path.stat().st_size),\\n                    session=db,\\n                    current_user=current_user,\\n                    storage_service=get_storage_service(),\\n                    settings_service=get_settings_service(),\\n                    append=False,\\n                )\\n\\n    def _save_dataframe(self, dataframe: DataFrame, path: Path, fmt: str) -> str:\\n        \\\"\\\"\\\"Save a DataFrame to the specified file format.\\\"\\\"\\\"\\n        append_mode = getattr(self, \\\"append_mode\\\", False)\\n        should_append = append_mode and path.exists() and self._is_plain_text_format(fmt)\\n\\n        if fmt == \\\"csv\\\":\\n            dataframe.to_csv(path, index=False, mode=\\\"a\\\" if should_append else \\\"w\\\", header=not should_append)\\n        elif fmt == \\\"excel\\\":\\n            dataframe.to_excel(path, index=False, engine=\\\"openpyxl\\\")\\n        elif fmt == \\\"json\\\":\\n            if should_append:\\n                # Read and parse existing JSON\\n                existing_data = []\\n                try:\\n                    existing_content = path.read_text(encoding=\\\"utf-8\\\").strip()\\n                    if existing_content:\\n                        parsed = json.loads(existing_content)\\n                        # Handle case where existing content is a single object\\n                        if isinstance(parsed, dict):\\n                            existing_data = [parsed]\\n                        elif isinstance(parsed, list):\\n                            existing_data = parsed\\n                except (json.JSONDecodeError, FileNotFoundError):\\n                    # Treat parse errors or missing file as empty array\\n                    existing_data = []\\n\\n                # Append new data\\n                new_records = json.loads(dataframe.to_json(orient=\\\"records\\\"))\\n                existing_data.extend(new_records)\\n\\n                # Write back as a single JSON array\\n                path.write_text(json.dumps(existing_data, indent=2), encoding=\\\"utf-8\\\")\\n            else:\\n                dataframe.to_json(path, orient=\\\"records\\\", indent=2)\\n        elif fmt == \\\"markdown\\\":\\n            content = dataframe.to_markdown(index=False)\\n            if should_append:\\n                path.write_text(path.read_text(encoding=\\\"utf-8\\\") + \\\"\\\\n\\\\n\\\" + content, encoding=\\\"utf-8\\\")\\n            else:\\n                path.write_text(content, encoding=\\\"utf-8\\\")\\n        else:\\n            msg = f\\\"Unsupported DataFrame format: {fmt}\\\"\\n            raise ValueError(msg)\\n        action = \\\"appended to\\\" if should_append else \\\"saved successfully as\\\"\\n        return f\\\"DataFrame {action} '{path}'\\\"\\n\\n    def _save_data(self, data: Data, path: Path, fmt: str) -> str:\\n        \\\"\\\"\\\"Save a Data object to the specified file format.\\\"\\\"\\\"\\n        append_mode = getattr(self, \\\"append_mode\\\", False)\\n        should_append = append_mode and path.exists() and self._is_plain_text_format(fmt)\\n\\n        if fmt == \\\"csv\\\":\\n            pd.DataFrame(data.data).to_csv(\\n                path,\\n                index=False,\\n                mode=\\\"a\\\" if should_append else \\\"w\\\",\\n                header=not should_append,\\n            )\\n        elif fmt == \\\"excel\\\":\\n            pd.DataFrame(data.data).to_excel(path, index=False, engine=\\\"openpyxl\\\")\\n        elif fmt == \\\"json\\\":\\n            new_data = jsonable_encoder(data.data)\\n            if should_append:\\n                # Read and parse existing JSON\\n                existing_data = []\\n                try:\\n                    existing_content = path.read_text(encoding=\\\"utf-8\\\").strip()\\n                    if existing_content:\\n                        parsed = json.loads(existing_content)\\n                        # Handle case where existing content is a single object\\n                        if isinstance(parsed, dict):\\n                            existing_data = [parsed]\\n                        elif isinstance(parsed, list):\\n                            existing_data = parsed\\n                except (json.JSONDecodeError, FileNotFoundError):\\n                    # Treat parse errors or missing file as empty array\\n                    existing_data = []\\n\\n                # Append new data\\n                if isinstance(new_data, list):\\n                    existing_data.extend(new_data)\\n                else:\\n                    existing_data.append(new_data)\\n\\n                # Write back as a single JSON array\\n                path.write_text(json.dumps(existing_data, indent=2), encoding=\\\"utf-8\\\")\\n            else:\\n                content = orjson.dumps(new_data, option=orjson.OPT_INDENT_2).decode(\\\"utf-8\\\")\\n                path.write_text(content, encoding=\\\"utf-8\\\")\\n        elif fmt == \\\"markdown\\\":\\n            content = pd.DataFrame(data.data).to_markdown(index=False)\\n            if should_append:\\n                path.write_text(path.read_text(encoding=\\\"utf-8\\\") + \\\"\\\\n\\\\n\\\" + content, encoding=\\\"utf-8\\\")\\n            else:\\n                path.write_text(content, encoding=\\\"utf-8\\\")\\n        else:\\n            msg = f\\\"Unsupported Data format: {fmt}\\\"\\n            raise ValueError(msg)\\n        action = \\\"appended to\\\" if should_append else \\\"saved successfully as\\\"\\n        return f\\\"Data {action} '{path}'\\\"\\n\\n    async def _save_message(self, message: Message, path: Path, fmt: str) -> str:\\n        \\\"\\\"\\\"Save a Message to the specified file format, handling async iterators.\\\"\\\"\\\"\\n        content = \\\"\\\"\\n        stream = message.text_stream if hasattr(message, \\\"text_stream\\\") else None\\n        if stream is not None and isinstance(stream, AsyncIterator):\\n            async for item in stream:\\n                content += str(item) + \\\" \\\"\\n            content = content.strip()\\n        elif stream is not None and isinstance(stream, Iterator):\\n            content = \\\" \\\".join(str(item) for item in stream)\\n        else:\\n            content = str(message.text)\\n\\n        append_mode = getattr(self, \\\"append_mode\\\", False)\\n        should_append = append_mode and path.exists() and self._is_plain_text_format(fmt)\\n\\n        if fmt in (\\\"txt\\\", \\\"html\\\"):\\n            if should_append:\\n                path.write_text(path.read_text(encoding=\\\"utf-8\\\") + \\\"\\\\n\\\" + content, encoding=\\\"utf-8\\\")\\n            else:\\n                path.write_text(content, encoding=\\\"utf-8\\\")\\n        elif fmt == \\\"json\\\":\\n            new_message = {\\\"message\\\": content}\\n            if should_append:\\n                # Read and parse existing JSON\\n                existing_data = []\\n                try:\\n                    existing_content = path.read_text(encoding=\\\"utf-8\\\").strip()\\n                    if existing_content:\\n                        parsed = json.loads(existing_content)\\n                        # Handle case where existing content is a single object\\n                        if isinstance(parsed, dict):\\n                            existing_data = [parsed]\\n                        elif isinstance(parsed, list):\\n                            existing_data = parsed\\n                except (json.JSONDecodeError, FileNotFoundError):\\n                    # Treat parse errors or missing file as empty array\\n                    existing_data = []\\n\\n                # Append new message\\n                existing_data.append(new_message)\\n\\n                # Write back as a single JSON array\\n                path.write_text(json.dumps(existing_data, indent=2), encoding=\\\"utf-8\\\")\\n            else:\\n                path.write_text(json.dumps(new_message, indent=2), encoding=\\\"utf-8\\\")\\n        elif fmt == \\\"markdown\\\":\\n            md_content = f\\\"**Message:**\\\\n\\\\n{content}\\\"\\n            if should_append:\\n                path.write_text(path.read_text(encoding=\\\"utf-8\\\") + \\\"\\\\n\\\\n\\\" + md_content, encoding=\\\"utf-8\\\")\\n            else:\\n                path.write_text(md_content, encoding=\\\"utf-8\\\")\\n        else:\\n            msg = f\\\"Unsupported Message format: {fmt}\\\"\\n            raise ValueError(msg)\\n        action = \\\"appended to\\\" if should_append else \\\"saved successfully as\\\"\\n        return f\\\"Message {action} '{path}'\\\"\\n\\n    def _get_selected_storage_location(self) -> str:\\n        \\\"\\\"\\\"Get the selected storage location from the SortableListInput.\\\"\\\"\\\"\\n        if hasattr(self, \\\"storage_location\\\") and self.storage_location:\\n            if isinstance(self.storage_location, list) and len(self.storage_location) > 0:\\n                return self.storage_location[0].get(\\\"name\\\", \\\"\\\")\\n            if isinstance(self.storage_location, dict):\\n                return self.storage_location.get(\\\"name\\\", \\\"\\\")\\n        return \\\"\\\"\\n\\n    def _get_file_format_for_location(self, location: str) -> str:\\n        \\\"\\\"\\\"Get the appropriate file format based on storage location.\\n\\n        If the agent set file_format via tool mode, that takes priority.\\n        \\\"\\\"\\\"\\n        agent_format = getattr(self, \\\"file_format\\\", None)\\n        if agent_format:\\n            return agent_format\\n        if location == \\\"Local\\\":\\n            return getattr(self, \\\"local_format\\\", None) or self._get_default_format()\\n        if location == \\\"AWS\\\":\\n            return getattr(self, \\\"aws_format\\\", \\\"txt\\\")\\n        if location == \\\"Google Drive\\\":\\n            return getattr(self, \\\"gdrive_format\\\", \\\"txt\\\")\\n        return self._get_default_format()\\n\\n    def _serving_end_user_segment(self) -> str | None:\\n        \\\"\\\"\\\"Filesystem-safe end-user id to namespace saved files under, or ``None``.\\n\\n        On the serving plane an identified end user owns the files they write during their\\n        session, so their id (``graph.end_user_id``) namespaces the save destination instead\\n        of the shared service account. Sanitized to ``[A-Za-z0-9_.-]`` so a gateway-supplied\\n        id can never traverse out of the storage root. ``None`` off / editor / anonymous, so\\n        the destination falls back to the SID scope exactly as before (strict BC).\\n        \\\"\\\"\\\"\\n        graph = getattr(getattr(self, \\\"_vertex\\\", None), \\\"graph\\\", None)\\n        end_user = getattr(graph, \\\"end_user_id\\\", None)\\n        if not end_user:\\n            return None\\n        safe = re.sub(r\\\"[^A-Za-z0-9_.-]\\\", \\\"_\\\", str(end_user)).strip(\\\"._\\\")\\n        return safe or None\\n\\n    async def _save_to_local(self) -> Message:\\n        \\\"\\\"\\\"Save file to local storage (original functionality).\\\"\\\"\\\"\\n        file_format = self._get_file_format_for_location(\\\"Local\\\")\\n\\n        # Validate file format based on input type\\n        allowed_formats = (\\n            self.LOCAL_MESSAGE_FORMAT_CHOICES if self._get_input_type() == \\\"Message\\\" else self.LOCAL_DATA_FORMAT_CHOICES\\n        )\\n        if file_format not in allowed_formats:\\n            msg = f\\\"Invalid file format '{file_format}' for {self._get_input_type()}. Allowed: {allowed_formats}\\\"\\n            raise ValueError(msg)\\n\\n        # Prepare file path. file_name is tenant-controlled and this writes to local disk.\\n        settings = get_settings_service().settings\\n        scope_ids = component_file_access_scopes(self)\\n        # Serving plane: an identified end user owns their files, so their (sanitized) id\\n        # becomes the namespace folder AND an allowed access scope for enforce_local_file_access.\\n        # None off / editor / anonymous -> scope_ids unchanged -> SID namespace as before (BC).\\n        end_user_segment = self._serving_end_user_segment()\\n        if end_user_segment:\\n            scope_ids = (end_user_segment, *scope_ids)\\n        file_path = Path(self._get_safe_local_file_name()).expanduser()\\n        if settings.restrict_local_file_access and not file_path.is_absolute():\\n            # New files belong to the authenticated user's storage namespace. If no\\n            # user/flow scope exists, ``enforce_local_file_access`` below fails closed.\\n            scope_root = Path(scope_ids[0]) if scope_ids else Path()\\n            file_path = Path(settings.config_dir) / scope_root / file_path\\n        file_path = self._adjust_file_path_with_format(file_path, file_format)\\n        file_path = enforce_local_file_access(file_path, scope_ids=scope_ids)\\n        if not file_path.parent.exists():\\n            file_path.parent.mkdir(parents=True, exist_ok=True)\\n\\n        # Save the input to file based on type\\n        if self._get_input_type() == \\\"DataFrame\\\":\\n            confirmation = self._save_dataframe(self.input, file_path, file_format)\\n        elif self._get_input_type() == \\\"Data\\\":\\n            confirmation = self._save_data(self.input, file_path, file_format)\\n        elif self._get_input_type() == \\\"Message\\\":\\n            confirmation = await self._save_message(self.input, file_path, file_format)\\n        else:\\n            msg = f\\\"Unsupported input type: {self._get_input_type()}\\\"\\n            raise ValueError(msg)\\n\\n        # Upload the saved file into the configured storage backend.\\n        upload_result = await self._upload_file(file_path)\\n\\n        # When the backend is remote (e.g. S3) the local file was only a\\n        # serialization staging area \u2014 the durable copy now lives in the storage\\n        # service. Delete the staging file (matching AWS-mode cleanup) and report\\n        # the storage destination instead of the misleading local path.\\n        # Why: on disposable executor pods the local copy is both redundant and\\n        # unreachable by other pods, so leaving it behind leaks a file and makes\\n        # the returned path point somewhere that does not durably exist. For local\\n        # storage the staged file IS the durable artifact, so it is kept as-is.\\n        #\\n        # Exception: append_mode accumulates content by reading the persisted local\\n        # file across calls (should_append hinges on path.exists()). Deleting it\\n        # would make the next append silently fall back to overwrite and lose the\\n        # accumulated content \u2014 so the staging file is preserved when appending.\\n        settings = get_settings_service().settings\\n        if settings.storage_type != \\\"local\\\":\\n            if not getattr(self, \\\"append_mode\\\", False):\\n                with contextlib.suppress(OSError):\\n                    file_path.unlink()\\n            destination = upload_result.path if upload_result is not None else file_path.name\\n            provider = (\\n                upload_result.provider\\n                if upload_result is not None and upload_result.provider\\n                else settings.storage_type\\n            ).upper()\\n            action = (\\n                \\\"appended to\\\"\\n                if getattr(self, \\\"append_mode\\\", False) and self._is_plain_text_format(file_format)\\n                else \\\"saved successfully as\\\"\\n            )\\n            return Message(text=f\\\"{self._get_input_type()} {action} '{destination}' in {provider} storage\\\")\\n\\n        # Local storage: the staged file is the durable artifact \u2014 keep it and\\n        # report its on-disk path.\\n        final_path = Path.cwd() / file_path if not file_path.is_absolute() else file_path\\n        return Message(text=f\\\"{confirmation} at {final_path}\\\")\\n\\n    async def _save_to_aws(self) -> Message:\\n        \\\"\\\"\\\"Save file to AWS S3 using S3 functionality.\\\"\\\"\\\"\\n        import os\\n\\n        import boto3\\n\\n        # Get AWS credentials from component inputs or fall back to environment variables\\n        aws_access_key_id = getattr(self, \\\"aws_access_key_id\\\", None)\\n        if aws_access_key_id and hasattr(aws_access_key_id, \\\"get_secret_value\\\"):\\n            aws_access_key_id = aws_access_key_id.get_secret_value()\\n        access_key_from_environment = not aws_access_key_id\\n        if access_key_from_environment:\\n            aws_access_key_id = os.getenv(\\\"AWS_ACCESS_KEY_ID\\\")\\n\\n        aws_secret_access_key = getattr(self, \\\"aws_secret_access_key\\\", None)\\n        if aws_secret_access_key and hasattr(aws_secret_access_key, \\\"get_secret_value\\\"):\\n            aws_secret_access_key = aws_secret_access_key.get_secret_value()\\n        secret_key_from_environment = not aws_secret_access_key\\n        if secret_key_from_environment:\\n            aws_secret_access_key = os.getenv(\\\"AWS_SECRET_ACCESS_KEY\\\")\\n\\n        bucket_name = getattr(self, \\\"bucket_name\\\", None)\\n        if not bucket_name:\\n            # Try to get from storage service settings\\n            settings = get_settings_service().settings\\n            bucket_name = settings.object_storage_bucket_name\\n\\n        # Validate AWS credentials\\n        if not aws_access_key_id:\\n            msg = (\\n                \\\"AWS Access Key ID is required for S3 storage. Provide it as a component input \\\"\\n                \\\"or set AWS_ACCESS_KEY_ID environment variable.\\\"\\n            )\\n            raise ValueError(msg)\\n        if not aws_secret_access_key:\\n            msg = (\\n                \\\"AWS Secret Key is required for S3 storage. Provide it as a component input \\\"\\n                \\\"or set AWS_SECRET_ACCESS_KEY environment variable.\\\"\\n            )\\n            raise ValueError(msg)\\n        if not bucket_name:\\n            msg = (\\n                \\\"S3 Bucket Name is required for S3 storage. Provide it as a component input \\\"\\n                \\\"or set LANGFLOW_OBJECT_STORAGE_BUCKET_NAME environment variable.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        # Create S3 client from the resolved component or fallback values\\n        client_config: dict[str, Any] = {\\n            \\\"aws_access_key_id\\\": str(aws_access_key_id),\\n            \\\"aws_secret_access_key\\\": str(aws_secret_access_key),\\n        }\\n        if access_key_from_environment and secret_key_from_environment:\\n            aws_session_token = os.getenv(\\\"AWS_SESSION_TOKEN\\\")\\n            if aws_session_token:\\n                client_config[\\\"aws_session_token\\\"] = aws_session_token\\n\\n        # Get region from component input, environment variable, or settings\\n        aws_region = getattr(self, \\\"aws_region\\\", None)\\n        if not aws_region:\\n            aws_region = os.getenv(\\\"AWS_DEFAULT_REGION\\\") or os.getenv(\\\"AWS_REGION\\\")\\n        if aws_region:\\n            client_config[\\\"region_name\\\"] = str(aws_region)\\n\\n        s3_client = boto3.client(\\\"s3\\\", **client_config)\\n\\n        # Extract content\\n        content = self._extract_content_for_upload()\\n        file_format = self._get_file_format_for_location(\\\"AWS\\\")\\n\\n        # Generate file path. Namespace by user_id so concurrent multi-user runs\\n        # writing the same file_name don't overwrite each other \u2014 mirrors how the\\n        # platform storage service isolates files under \\\"{user_id}/\\\". Layout:\\n        #   {s3_prefix}/{user_id}/{file_name}.{ext}\\n        file_name = f\\\"{self.file_name}.{file_format}\\\"\\n        path_segments = []\\n        if hasattr(self, \\\"s3_prefix\\\") and self.s3_prefix:\\n            path_segments.append(self.s3_prefix.rstrip(\\\"/\\\"))\\n        # Serving plane: an identified end user owns their files (sanitized id); else the SID.\\n        user_id = self._serving_end_user_segment() or self.user_id\\n        if user_id and str(user_id) != \\\"None\\\":\\n            path_segments.append(str(user_id))\\n        path_segments.append(file_name)\\n        file_path = \\\"/\\\".join(path_segments)\\n\\n        # Create temporary file\\n        import tempfile\\n\\n        with tempfile.NamedTemporaryFile(\\n            mode=\\\"w\\\", encoding=\\\"utf-8\\\", suffix=f\\\".{file_format}\\\", delete=False\\n        ) as temp_file:\\n            temp_file.write(content)\\n            temp_file_path = temp_file.name\\n\\n        try:\\n            # Upload to S3\\n            s3_client.upload_file(temp_file_path, bucket_name, file_path)\\n            s3_url = f\\\"s3://{bucket_name}/{file_path}\\\"\\n            return Message(text=f\\\"File successfully uploaded to {s3_url}\\\")\\n        finally:\\n            # Clean up temp file\\n            if Path(temp_file_path).exists():\\n                Path(temp_file_path).unlink()\\n\\n    async def _save_to_google_drive(self) -> Message:\\n        \\\"\\\"\\\"Save file to Google Drive using Google Drive functionality.\\\"\\\"\\\"\\n        import tempfile\\n\\n        from googleapiclient.http import MediaFileUpload\\n\\n        from lfx.base.data.cloud_storage_utils import create_google_drive_service\\n\\n        # Validate Google Drive credentials\\n        if not getattr(self, \\\"service_account_key\\\", None):\\n            msg = \\\"GCP Credentials Secret Key is required for Google Drive storage\\\"\\n            raise ValueError(msg)\\n        if not getattr(self, \\\"folder_id\\\", None):\\n            msg = \\\"Google Drive Folder ID is required for Google Drive storage\\\"\\n            raise ValueError(msg)\\n\\n        # Create Google Drive service with full drive scope (needed for folder operations)\\n        drive_service, credentials = create_google_drive_service(\\n            self.service_account_key, scopes=[\\\"https://www.googleapis.com/auth/drive\\\"], return_credentials=True\\n        )\\n\\n        # Extract content and format\\n        content = self._extract_content_for_upload()\\n        file_format = self._get_file_format_for_location(\\\"Google Drive\\\")\\n\\n        # Handle special Google Drive formats\\n        if file_format in [\\\"slides\\\", \\\"docs\\\"]:\\n            return await self._save_to_google_apps(drive_service, credentials, content, file_format)\\n\\n        # Create temporary file\\n        file_path = f\\\"{self.file_name}.{file_format}\\\"\\n        with tempfile.NamedTemporaryFile(\\n            mode=\\\"w\\\",\\n            encoding=\\\"utf-8\\\",\\n            suffix=f\\\".{file_format}\\\",\\n            delete=False,\\n        ) as temp_file:\\n            temp_file.write(content)\\n            temp_file_path = temp_file.name\\n\\n        try:\\n            # Upload to Google Drive\\n            # Note: We skip explicit folder verification since it requires broader permissions.\\n            # If the folder doesn't exist or isn't accessible, the create() call will fail with a clear error.\\n            file_metadata = {\\\"name\\\": file_path, \\\"parents\\\": [self.folder_id]}\\n            media = MediaFileUpload(temp_file_path, resumable=True)\\n\\n            try:\\n                uploaded_file = (\\n                    drive_service.files().create(body=file_metadata, media_body=media, fields=\\\"id\\\").execute()\\n                )\\n            except Exception as e:\\n                msg = (\\n                    f\\\"Unable to upload file to Google Drive folder '{self.folder_id}'. \\\"\\n                    f\\\"Error: {e!s}. \\\"\\n                    \\\"Please ensure: 1) The folder ID is correct, 2) The folder exists, \\\"\\n                    \\\"3) The service account has been granted access to this folder.\\\"\\n                )\\n                raise ValueError(msg) from e\\n\\n            file_id = uploaded_file.get(\\\"id\\\")\\n            file_url = f\\\"https://drive.google.com/file/d/{file_id}/view\\\"\\n            return Message(text=f\\\"File successfully uploaded to Google Drive: {file_url}\\\")\\n        finally:\\n            # Clean up temp file\\n            if Path(temp_file_path).exists():\\n                Path(temp_file_path).unlink()\\n\\n    async def _save_to_google_apps(self, drive_service, credentials, content: str, app_type: str) -> Message:\\n        \\\"\\\"\\\"Save content to Google Apps (Slides or Docs).\\\"\\\"\\\"\\n        import time\\n\\n        if app_type == \\\"slides\\\":\\n            from googleapiclient.discovery import build\\n\\n            slides_service = build(\\\"slides\\\", \\\"v1\\\", credentials=credentials)\\n\\n            file_metadata = {\\n                \\\"name\\\": self.file_name,\\n                \\\"mimeType\\\": \\\"application/vnd.google-apps.presentation\\\",\\n                \\\"parents\\\": [self.folder_id],\\n            }\\n\\n            created_file = drive_service.files().create(body=file_metadata, fields=\\\"id\\\").execute()\\n            presentation_id = created_file[\\\"id\\\"]\\n\\n            time.sleep(2)  # Wait for file to be available  # noqa: ASYNC251\\n\\n            presentation = slides_service.presentations().get(presentationId=presentation_id).execute()\\n            slide_id = presentation[\\\"slides\\\"][0][\\\"objectId\\\"]\\n\\n            # Add content to slide\\n            requests = [\\n                {\\n                    \\\"createShape\\\": {\\n                        \\\"objectId\\\": \\\"TextBox_01\\\",\\n                        \\\"shapeType\\\": \\\"TEXT_BOX\\\",\\n                        \\\"elementProperties\\\": {\\n                            \\\"pageObjectId\\\": slide_id,\\n                            \\\"size\\\": {\\n                                \\\"height\\\": {\\\"magnitude\\\": 3000000, \\\"unit\\\": \\\"EMU\\\"},\\n                                \\\"width\\\": {\\\"magnitude\\\": 6000000, \\\"unit\\\": \\\"EMU\\\"},\\n                            },\\n                            \\\"transform\\\": {\\n                                \\\"scaleX\\\": 1,\\n                                \\\"scaleY\\\": 1,\\n                                \\\"translateX\\\": 1000000,\\n                                \\\"translateY\\\": 1000000,\\n                                \\\"unit\\\": \\\"EMU\\\",\\n                            },\\n                        },\\n                    }\\n                },\\n                {\\\"insertText\\\": {\\\"objectId\\\": \\\"TextBox_01\\\", \\\"insertionIndex\\\": 0, \\\"text\\\": content}},\\n            ]\\n\\n            slides_service.presentations().batchUpdate(\\n                presentationId=presentation_id, body={\\\"requests\\\": requests}\\n            ).execute()\\n            file_url = f\\\"https://docs.google.com/presentation/d/{presentation_id}/edit\\\"\\n\\n        elif app_type == \\\"docs\\\":\\n            from googleapiclient.discovery import build\\n\\n            docs_service = build(\\\"docs\\\", \\\"v1\\\", credentials=credentials)\\n\\n            file_metadata = {\\n                \\\"name\\\": self.file_name,\\n                \\\"mimeType\\\": \\\"application/vnd.google-apps.document\\\",\\n                \\\"parents\\\": [self.folder_id],\\n            }\\n\\n            created_file = drive_service.files().create(body=file_metadata, fields=\\\"id\\\").execute()\\n            document_id = created_file[\\\"id\\\"]\\n\\n            time.sleep(2)  # Wait for file to be available  # noqa: ASYNC251\\n\\n            # Add content to document\\n            requests = [{\\\"insertText\\\": {\\\"location\\\": {\\\"index\\\": 1}, \\\"text\\\": content}}]\\n            docs_service.documents().batchUpdate(documentId=document_id, body={\\\"requests\\\": requests}).execute()\\n            file_url = f\\\"https://docs.google.com/document/d/{document_id}/edit\\\"\\n\\n        return Message(text=f\\\"File successfully created in Google {app_type.title()}: {file_url}\\\")\\n\\n    def _extract_content_for_upload(self) -> str:\\n        \\\"\\\"\\\"Extract content from input for upload to cloud services.\\\"\\\"\\\"\\n        if self._get_input_type() == \\\"DataFrame\\\":\\n            return self.input.to_csv(index=False)\\n        if self._get_input_type() == \\\"Data\\\":\\n            if hasattr(self.input, \\\"data\\\") and self.input.data:\\n                if isinstance(self.input.data, dict):\\n                    import json\\n\\n                    return json.dumps(self.input.data, indent=2, ensure_ascii=False)\\n                return str(self.input.data)\\n            return str(self.input)\\n        if self._get_input_type() == \\\"Message\\\":\\n            return str(self.input.text) if self.input.text else str(self.input)\\n        return str(self.input)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/files_ingestion/merge_flows.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b54a6b6dcdd8c9c24219661ff816117355380d78b3f5156e40ffb210466358e\",\"content\":\"\\\"\\\"\\\"Component that merges multiple flows into a single trigger point.\\n\\nConnect any number of upstream components to run them all when this component executes.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import HandleInput, Output\\nfrom lfx.schema.message import Message\\n\\n\\nclass MergeFlowsComponent(Component):\\n    display_name = \\\"Merge Flows\\\"\\n    description = \\\"Merges multiple flows into one. Running this triggers all connected upstream flows.\\\"\\n    icon = \\\"git-merge\\\"\\n    name = \\\"MergeFlows\\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\\"inputs\\\",\\n            display_name=\\\"Inputs\\\",\\n            input_types=[\\\"Data\\\", \\\"DataFrame\\\", \\\"Message\\\", \\\"Tool\\\", \\\"JSON\\\", \\\"Table\\\"],\\n            is_list=True,\\n            info=\\\"Connect any upstream component outputs here. All will run when this component executes.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Done\\\",\\n            name=\\\"done\\\",\\n            method=\\\"run\\\",\\n        ),\\n    ]\\n\\n    def run(self) -> Message:\\n        count = len(self.inputs) if self.inputs else 0\\n        return Message(text=f\\\"Merged {count} flows\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b1e5539e6aad4cf59832f5539168796cd77a01dd8043955de406e55c9b2ad04\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from lfx.components.flow_controls.conditional_router import ConditionalRouterComponent\\n    from lfx.components.flow_controls.data_conditional_router import DataConditionalRouterComponent\\n    from lfx.components.flow_controls.flow_tool import FlowToolComponent\\n    from lfx.components.flow_controls.human_input import HumanInput\\n    from lfx.components.flow_controls.listen import ListenComponent\\n    from lfx.components.flow_controls.loop import LoopComponent\\n    from lfx.components.flow_controls.notify import NotifyComponent\\n    from lfx.components.flow_controls.pass_message import PassMessageComponent\\n    from lfx.components.flow_controls.run_flow import RunFlowComponent\\n    from lfx.components.flow_controls.sub_flow import SubFlowComponent\\n\\n_dynamic_imports = {\\n    \\\"ConditionalRouterComponent\\\": \\\"conditional_router\\\",\\n    \\\"DataConditionalRouterComponent\\\": \\\"data_conditional_router\\\",\\n    \\\"FlowToolComponent\\\": \\\"flow_tool\\\",\\n    \\\"HumanInput\\\": \\\"human_input\\\",\\n    \\\"ListenComponent\\\": \\\"listen\\\",\\n    \\\"LoopComponent\\\": \\\"loop\\\",\\n    \\\"NotifyComponent\\\": \\\"notify\\\",\\n    \\\"PassMessageComponent\\\": \\\"pass_message\\\",\\n    \\\"RunFlowComponent\\\": \\\"run_flow\\\",\\n    \\\"SubFlowComponent\\\": \\\"sub_flow\\\",\\n}\\n\\n__all__ = [\\n    \\\"ConditionalRouterComponent\\\",\\n    \\\"DataConditionalRouterComponent\\\",\\n    \\\"FlowToolComponent\\\",\\n    \\\"HumanInput\\\",\\n    \\\"ListenComponent\\\",\\n    \\\"LoopComponent\\\",\\n    \\\"NotifyComponent\\\",\\n    \\\"PassMessageComponent\\\",\\n    \\\"RunFlowComponent\\\",\\n    \\\"SubFlowComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import flow control components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/conditional_router.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1d14fd882a0a4216c9a38b06113affc5daeabd9bb0e4482de5fdf200b292281e\",\"content\":\"import re\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import BoolInput, DropdownInput, IntInput, MessageInput, MessageTextInput, Output\\nfrom lfx.schema.message import Message\\n\\n\\nclass ConditionalRouterComponent(Component):\\n    display_name = \\\"If-Else\\\"\\n    description = \\\"Routes an input message to a corresponding output based on text comparison.\\\"\\n    documentation: str = \\\"https://docs.langflow.org/if-else\\\"\\n    icon = \\\"split\\\"\\n    name = \\\"ConditionalRouter\\\"\\n\\n    def __init__(self, *args, **kwargs):\\n        super().__init__(*args, **kwargs)\\n        self.__iteration_updated = False\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"input_text\\\",\\n            display_name=\\\"Text Input\\\",\\n            info=\\\"The primary text input for the operation.\\\",\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"operator\\\",\\n            display_name=\\\"Operator\\\",\\n            options=[\\n                \\\"equals\\\",\\n                \\\"not equals\\\",\\n                \\\"contains\\\",\\n                \\\"starts with\\\",\\n                \\\"ends with\\\",\\n                \\\"regex\\\",\\n                \\\"less than\\\",\\n                \\\"less than or equal\\\",\\n                \\\"greater than\\\",\\n                \\\"greater than or equal\\\",\\n            ],\\n            info=\\\"The operator to apply for comparing the texts.\\\",\\n            value=\\\"equals\\\",\\n            real_time_refresh=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"match_text\\\",\\n            display_name=\\\"Match Text\\\",\\n            info=\\\"The text input to compare against.\\\",\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\\"case_sensitive\\\",\\n            display_name=\\\"Case Sensitive\\\",\\n            info=\\\"If true, the comparison will be case sensitive.\\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        MessageInput(\\n            name=\\\"true_case_message\\\",\\n            display_name=\\\"Case True\\\",\\n            info=\\\"The message to pass if the condition is True.\\\",\\n            advanced=True,\\n        ),\\n        MessageInput(\\n            name=\\\"false_case_message\\\",\\n            display_name=\\\"Case False\\\",\\n            info=\\\"The message to pass if the condition is False.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_iterations\\\",\\n            display_name=\\\"Max Iterations\\\",\\n            info=\\\"The maximum number of iterations for the conditional router.\\\",\\n            value=10,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"default_route\\\",\\n            display_name=\\\"Default Route\\\",\\n            options=[\\\"true_result\\\", \\\"false_result\\\"],\\n            info=\\\"The default route to take when max iterations are reached.\\\",\\n            value=\\\"false_result\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"True\\\", name=\\\"true_result\\\", method=\\\"true_response\\\", group_outputs=True),\\n        Output(display_name=\\\"False\\\", name=\\\"false_result\\\", method=\\\"false_response\\\", group_outputs=True),\\n    ]\\n\\n    def _pre_run_setup(self):\\n        self.__iteration_updated = False\\n\\n    def evaluate_condition(self, input_text: str, match_text: str, operator: str, *, case_sensitive: bool) -> bool:\\n        if not case_sensitive and operator != \\\"regex\\\":\\n            input_text = input_text.lower()\\n            match_text = match_text.lower()\\n\\n        if operator == \\\"equals\\\":\\n            return input_text == match_text\\n        if operator == \\\"not equals\\\":\\n            return input_text != match_text\\n        if operator == \\\"contains\\\":\\n            return match_text in input_text\\n        if operator == \\\"starts with\\\":\\n            return input_text.startswith(match_text)\\n        if operator == \\\"ends with\\\":\\n            return input_text.endswith(match_text)\\n        if operator == \\\"regex\\\":\\n            try:\\n                return bool(re.match(match_text, input_text))\\n            except re.error:\\n                return False  # Return False if the regex is invalid\\n        if operator in [\\\"less than\\\", \\\"less than or equal\\\", \\\"greater than\\\", \\\"greater than or equal\\\"]:\\n            try:\\n                input_num = float(input_text)\\n                match_num = float(match_text)\\n                if operator == \\\"less than\\\":\\n                    return input_num < match_num\\n                if operator == \\\"less than or equal\\\":\\n                    return input_num <= match_num\\n                if operator == \\\"greater than\\\":\\n                    return input_num > match_num\\n                if operator == \\\"greater than or equal\\\":\\n                    return input_num >= match_num\\n            except ValueError:\\n                return False  # Invalid number format for comparison\\n        return False\\n\\n    def iterate_and_stop_once(self, route_to_stop: str):\\n        \\\"\\\"\\\"Handles cycle iteration counting and branch exclusion.\\n\\n        Uses two complementary mechanisms:\\n        1. stop() - ACTIVE/INACTIVE state for cycle management (gets reset each iteration)\\n        2. exclude_branch_conditionally() - Persistent exclusion for conditional routing\\n\\n        When max_iterations is reached, breaks the cycle by allowing the default_route to execute.\\n        \\\"\\\"\\\"\\n        if not self.__iteration_updated:\\n            self.update_ctx({f\\\"{self._id}_iteration\\\": self.ctx.get(f\\\"{self._id}_iteration\\\", 0) + 1})\\n            self.__iteration_updated = True\\n            current_iteration = self.ctx.get(f\\\"{self._id}_iteration\\\", 0)\\n\\n            # Check if max iterations reached and we're trying to stop the default route\\n            if current_iteration >= self.max_iterations and route_to_stop == self.default_route:\\n                # Clear ALL conditional exclusions to allow default route to execute\\n                if self._id in self.graph.conditional_exclusion_sources:\\n                    previous_exclusions = self.graph.conditional_exclusion_sources[self._id]\\n                    self.graph.conditionally_excluded_vertices -= previous_exclusions\\n                    del self.graph.conditional_exclusion_sources[self._id]\\n\\n                # Switch which route to stop - stop the NON-default route to break the cycle\\n                route_to_stop = \\\"true_result\\\" if route_to_stop == \\\"false_result\\\" else \\\"false_result\\\"\\n\\n                # Call stop to break the cycle\\n                self.stop(route_to_stop)\\n                # Don't apply conditional exclusion when breaking cycle\\n                return\\n\\n            # Normal case: Use BOTH mechanisms\\n            # 1. stop() for cycle management (marks INACTIVE, updates run manager, gets reset)\\n            self.stop(route_to_stop)\\n\\n            # 2. Conditional exclusion for persistent routing (doesn't get reset except by this router)\\n            self.graph.exclude_branch_conditionally(self._id, output_name=route_to_stop)\\n\\n    def _resolve_case_message(self, case_message: Message | str | None) -> Message:\\n        \\\"\\\"\\\"Return the override case message, falling back to the input text when it is blank.\\n\\n        ``Case True`` and ``Case False`` are optional overrides. When left blank the\\n        ``MessageInput`` resolves to an empty ``Message``, so the original ``Text Input``\\n        is routed through instead of an empty message.\\n\\n        A ``Message`` is only treated as blank when it carries no payload at all. An\\n        override with empty text but meaningful content (files or content blocks) is\\n        preserved as-is so that payload is not dropped.\\n\\n        Blankness is judged by payload only (``text``, ``files``, ``content_blocks``).\\n        A ``Message`` carrying just metadata (``sender``, ``properties``, ``error`` ...)\\n        and no payload is intentionally treated as blank: every empty ``Message`` also\\n        defaults ``timestamp`` / ``category`` / ``properties``, so keying on metadata\\n        would defeat the blank-field fallback. With no payload there is nothing to\\n        route, so the ``Text Input`` is used.\\n\\n        ``case_message`` is typed defensively as ``Message | str | None``. ``MessageInput``\\n        wraps user input into a ``Message`` on the validated graph path, but a raw ``str``\\n        can still arrive via direct/programmatic assignment (``.set(...)`` stores the raw\\n        value), so the ``str`` branch is retained rather than dropping such an override.\\n        \\\"\\\"\\\"\\n        if isinstance(case_message, Message):\\n            if case_message.text or case_message.files or case_message.content_blocks:\\n                return case_message\\n            return Message(text=self.input_text)\\n        if isinstance(case_message, str) and case_message:\\n            return Message(text=case_message)\\n        return Message(text=self.input_text)\\n\\n    def true_response(self) -> Message:\\n        result = self.evaluate_condition(\\n            self.input_text, self.match_text, self.operator, case_sensitive=self.case_sensitive\\n        )\\n\\n        # Check if we should force output due to max_iterations on default route\\n        current_iteration = self.ctx.get(f\\\"{self._id}_iteration\\\", 0)\\n        force_output = current_iteration >= self.max_iterations and self.default_route == \\\"true_result\\\"\\n\\n        if result or force_output:\\n            true_message = self._resolve_case_message(self.true_case_message)\\n            self.status = true_message\\n            if not force_output:  # Only stop the other branch if not forcing due to max iterations\\n                self.iterate_and_stop_once(\\\"false_result\\\")\\n            return true_message\\n        self.iterate_and_stop_once(\\\"true_result\\\")\\n        return Message(text=\\\"\\\")\\n\\n    def false_response(self) -> Message:\\n        result = self.evaluate_condition(\\n            self.input_text, self.match_text, self.operator, case_sensitive=self.case_sensitive\\n        )\\n\\n        if not result:\\n            false_message = self._resolve_case_message(self.false_case_message)\\n            self.status = false_message\\n            self.iterate_and_stop_once(\\\"true_result\\\")\\n            return false_message\\n\\n        self.iterate_and_stop_once(\\\"false_result\\\")\\n        return Message(text=\\\"\\\")\\n\\n    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None) -> dict:\\n        if field_name == \\\"operator\\\":\\n            if field_value == \\\"regex\\\":\\n                build_config.pop(\\\"case_sensitive\\\", None)\\n            elif \\\"case_sensitive\\\" not in build_config:\\n                case_sensitive_input = next(\\n                    (input_field for input_field in self.inputs if input_field.name == \\\"case_sensitive\\\"), None\\n                )\\n                if case_sensitive_input:\\n                    build_config[\\\"case_sensitive\\\"] = case_sensitive_input.to_dict()\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/data_conditional_router.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6fa1bf4166a342aa0509033eeb5e106eb3e8536015ce480c1c0e803146726e5d\",\"content\":\"from typing import Any\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DataInput, DropdownInput, MessageTextInput, Output\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\n\\n\\nclass DataConditionalRouterComponent(Component):\\n    display_name = \\\"Condition\\\"\\n    description = \\\"Route Data object(s) based on a condition applied to a specified key, including boolean validation.\\\"\\n    icon = \\\"split\\\"\\n    name = \\\"DataConditionalRouter\\\"\\n    legacy = True\\n    replacement = [\\\"logic.ConditionalRouter\\\"]\\n\\n    inputs = [\\n        DataInput(\\n            name=\\\"data_input\\\",\\n            display_name=\\\"Data Input\\\",\\n            info=\\\"The Data object or list of Data objects to process\\\",\\n            is_list=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"key_name\\\",\\n            display_name=\\\"Key Name\\\",\\n            info=\\\"The name of the key in the Data object(s) to check\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"operator\\\",\\n            display_name=\\\"Operator\\\",\\n            options=[\\\"equals\\\", \\\"not equals\\\", \\\"contains\\\", \\\"starts with\\\", \\\"ends with\\\", \\\"boolean validator\\\"],\\n            info=\\\"The operator to apply for comparing the values. 'boolean validator' treats the value as a boolean.\\\",\\n            value=\\\"equals\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"compare_value\\\",\\n            display_name=\\\"Match Text\\\",\\n            info=\\\"The value to compare against (not used for boolean validator)\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"True Output\\\", name=\\\"true_output\\\", method=\\\"process_data\\\"),\\n        Output(display_name=\\\"False Output\\\", name=\\\"false_output\\\", method=\\\"process_data\\\"),\\n    ]\\n\\n    def compare_values(self, item_value: str, compare_value: str, operator: str) -> bool:\\n        if operator == \\\"equals\\\":\\n            return item_value == compare_value\\n        if operator == \\\"not equals\\\":\\n            return item_value != compare_value\\n        if operator == \\\"contains\\\":\\n            return compare_value in item_value\\n        if operator == \\\"starts with\\\":\\n            return item_value.startswith(compare_value)\\n        if operator == \\\"ends with\\\":\\n            return item_value.endswith(compare_value)\\n        if operator == \\\"boolean validator\\\":\\n            return self.parse_boolean(item_value)\\n        return False\\n\\n    def parse_boolean(self, value):\\n        if isinstance(value, bool):\\n            return value\\n        if isinstance(value, str):\\n            return value.lower() in {\\\"true\\\", \\\"1\\\", \\\"yes\\\", \\\"y\\\", \\\"on\\\"}\\n        return bool(value)\\n\\n    def validate_input(self, data_item: Data) -> bool:\\n        if not isinstance(data_item, Data):\\n            self.status = \\\"Input is not a Data object\\\"\\n            return False\\n        if self.key_name not in data_item.data:\\n            self.status = f\\\"Key '{self.key_name}' not found in Data\\\"\\n            return False\\n        return True\\n\\n    def process_data(self) -> Data | list[Data]:\\n        if isinstance(self.data_input, list):\\n            true_output = []\\n            false_output = []\\n            for item in self.data_input:\\n                if self.validate_input(item):\\n                    result = self.process_single_data(item)\\n                    if result:\\n                        true_output.append(item)\\n                    else:\\n                        false_output.append(item)\\n            self.stop(\\\"false_output\\\" if true_output else \\\"true_output\\\")\\n            return true_output or false_output\\n        if not self.validate_input(self.data_input):\\n            return Data(data={\\\"error\\\": self.status})\\n        result = self.process_single_data(self.data_input)\\n        self.stop(\\\"false_output\\\" if result else \\\"true_output\\\")\\n        return self.data_input\\n\\n    def process_single_data(self, data_item: Data) -> bool:\\n        item_value = data_item.data[self.key_name]\\n        operator = self.operator\\n\\n        if operator == \\\"boolean validator\\\":\\n            condition_met = self.parse_boolean(item_value)\\n            condition_description = f\\\"Boolean validation of '{self.key_name}'\\\"\\n        else:\\n            compare_value = self.compare_value\\n            condition_met = self.compare_values(str(item_value), compare_value, operator)\\n            condition_description = f\\\"{self.key_name} {operator} {compare_value}\\\"\\n\\n        if condition_met:\\n            self.status = f\\\"Condition met: {condition_description}\\\"\\n            return True\\n        self.status = f\\\"Condition not met: {condition_description}\\\"\\n        return False\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None):\\n        if field_name == \\\"operator\\\":\\n            if field_value == \\\"boolean validator\\\":\\n                build_config[\\\"compare_value\\\"][\\\"show\\\"] = False\\n                build_config[\\\"compare_value\\\"][\\\"advanced\\\"] = True\\n                build_config[\\\"compare_value\\\"][\\\"value\\\"] = None\\n            else:\\n                build_config[\\\"compare_value\\\"][\\\"show\\\"] = True\\n                build_config[\\\"compare_value\\\"][\\\"advanced\\\"] = False\\n\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/flow_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e655efd6a4503b34dff743637ae1a94a1e404192e052bda81abd75b942bdbd11\",\"content\":\"from typing import Any\\n\\nfrom typing_extensions import override\\n\\nfrom lfx.base.langchain_utilities.model import LCToolComponent\\nfrom lfx.base.tools.flow_tool import FlowTool\\nfrom lfx.field_typing import Tool\\nfrom lfx.helpers import get_flow_inputs\\nfrom lfx.io import BoolInput, DropdownInput, Output, StrInput\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\n\\n\\nclass FlowToolComponent(LCToolComponent):\\n    display_name = \\\"Flow as Tool\\\"\\n    description = \\\"Construct a Tool from a function that runs the loaded Flow.\\\"\\n    field_order = [\\\"flow_name\\\", \\\"name\\\", \\\"description\\\", \\\"return_direct\\\"]\\n    trace_type = \\\"tool\\\"\\n    name = \\\"FlowTool\\\"\\n    legacy: bool = True\\n    replacement = [\\\"logic.RunFlow\\\"]\\n    icon = \\\"hammer\\\"\\n\\n    async def get_flow_names(self) -> list[str]:\\n        flow_datas = await self.alist_flows()\\n        return [flow_data.data[\\\"name\\\"] for flow_data in flow_datas]\\n\\n    async def get_flow(self, flow_name: str) -> Data | None:\\n        \\\"\\\"\\\"Retrieves a flow by its name.\\n\\n        Args:\\n            flow_name (str): The name of the flow to retrieve.\\n\\n        Returns:\\n            Optional[Text]: The flow record if found, None otherwise.\\n        \\\"\\\"\\\"\\n        flow_datas = await self.alist_flows()\\n        for flow_data in flow_datas:\\n            if flow_data.data[\\\"name\\\"] == flow_name:\\n                return flow_data\\n        return None\\n\\n    @override\\n    async def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None):\\n        if field_name == \\\"flow_name\\\":\\n            build_config[\\\"flow_name\\\"][\\\"options\\\"] = self.get_flow_names()\\n\\n        return build_config\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"flow_name\\\", display_name=\\\"Flow Name\\\", info=\\\"The name of the flow to run.\\\", refresh_button=True\\n        ),\\n        StrInput(\\n            name=\\\"tool_name\\\",\\n            display_name=\\\"Name\\\",\\n            info=\\\"The name of the tool.\\\",\\n        ),\\n        StrInput(\\n            name=\\\"tool_description\\\",\\n            display_name=\\\"Description\\\",\\n            info=\\\"The description of the tool; defaults to the Flow's description.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"return_direct\\\",\\n            display_name=\\\"Return Direct\\\",\\n            info=\\\"Return the result directly from the Tool.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"api_build_tool\\\", display_name=\\\"Tool\\\", method=\\\"build_tool\\\"),\\n    ]\\n\\n    async def build_tool(self) -> Tool:\\n        FlowTool.model_rebuild()\\n        if \\\"flow_name\\\" not in self._attributes or not self._attributes[\\\"flow_name\\\"]:\\n            msg = \\\"Flow name is required\\\"\\n            raise ValueError(msg)\\n        flow_name = self._attributes[\\\"flow_name\\\"]\\n        flow_data = await self.get_flow(flow_name)\\n        if not flow_data:\\n            msg = \\\"Flow not found.\\\"\\n            raise ValueError(msg)\\n        graph = await self.load_flow(str(flow_data.id))\\n        try:\\n            graph.set_run_id(self.graph.run_id)\\n        except Exception:  # noqa: BLE001\\n            logger.warning(\\\"Failed to set run_id\\\", exc_info=True)\\n        inputs = get_flow_inputs(graph)\\n        tool_description = self.tool_description.strip() or flow_data.description\\n        tool = FlowTool(\\n            name=self.tool_name,\\n            description=tool_description,\\n            graph=graph,\\n            return_direct=self.return_direct,\\n            inputs=inputs,\\n            flow_id=str(flow_data.id),\\n            user_id=str(self.user_id),\\n            session_id=self.graph.session_id if hasattr(self, \\\"graph\\\") else None,\\n        )\\n        description_repr = repr(tool.description).strip(\\\"'\\\")\\n        args_str = \\\"\\\\n\\\".join([f\\\"- {arg_name}: {arg_data['description']}\\\" for arg_name, arg_data in tool.args.items()])\\n        self.status = f\\\"{description_repr}\\\\nArguments:\\\\n{args_str}\\\"\\n        return tool\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/human_input.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"63cbbf99823fdb52baf00091e8dd745d8c83dc052680519f3ce816991bf04dee\",\"content\":\"\\\"\\\"\\\"Human Input node: pause a flow for a human decision, then route on the pick (LE-1449).\\n\\nThe User Choices picker chooses which actions the human can take (presets like\\nApprove/Reject/Escalate, or custom); each becomes a branch output. On first execution\\nthe node requests a pause carrying a ``node_input`` request; on resume the injected\\ndecision selects exactly one branch (the others are stopped). With Enable Fallback on,\\na ``fallback`` branch is added for when no user action is answered (e.g. after timeout).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom typing import Any\\n\\nfrom lfx.custom import Component\\nfrom lfx.inputs.inputs import ActionPickerInput, BoolInput, DurationInput\\nfrom lfx.io import MultilineInput, Output\\nfrom lfx.schema.message import Message\\n\\nHUMAN_INPUT_REQUIRED = \\\"human_input_required\\\"\\n_KIND_NODE_INPUT = \\\"node_input\\\"\\n_FALLBACK_ACTION = \\\"fallback\\\"\\n_UNIT_SECONDS = {\\\"Minutes\\\": 60, \\\"Hours\\\": 3600, \\\"Days\\\": 86400}\\n\\n\\ndef _action_id(label: str) -> str:\\n    \\\"\\\"\\\"Stable branch id for a human-facing action label (e.g. 'Request Changes' -> 'request_changes').\\\"\\\"\\\"\\n    return str(label).strip().lower().replace(\\\" \\\", \\\"_\\\")\\n\\n\\nclass HumanInput(Component):\\n    display_name = \\\"Human Input\\\"\\n    description = \\\"Pause the flow for a human-in-the-loop (HITL) decision and route on the chosen action.\\\"\\n    icon = \\\"HumanInput\\\"\\n    name = \\\"HumanInput\\\"\\n    metadata = {\\\"keywords\\\": [\\\"hitl\\\", \\\"human-in-the-loop\\\", \\\"decision\\\"]}\\n\\n    inputs = [\\n        MultilineInput(\\n            name=\\\"prompt\\\",\\n            display_name=\\\"Input\\\",\\n            info=\\\"Content shown to the human for review.\\\",\\n            value=\\\"\\\",\\n        ),\\n        ActionPickerInput(\\n            name=\\\"decisions\\\",\\n            display_name=\\\"User Choices\\\",\\n            info=\\\"Choices the human can pick; each becomes a branch output. Pick from the list or type a custom one.\\\",\\n            value=[\\\"Approve\\\", \\\"Reject\\\"],\\n            real_time_refresh=True,\\n            required=True,\\n        ),\\n        DurationInput(\\n            name=\\\"timeout\\\",\\n            display_name=\\\"Timeout\\\",\\n            info=\\\"A response received after this window is rerouted to the fallback path (when enabled) \\\"\\n            \\\"instead of the chosen action. The run stays paused until a response arrives or the \\\"\\n            \\\"server's suspended-run deadline expires it. Set to 0 to wait indefinitely.\\\",\\n            options=[\\\"Minutes\\\", \\\"Hours\\\", \\\"Days\\\"],\\n            value={\\\"value\\\": 3, \\\"unit\\\": \\\"Days\\\"},\\n            advanced=True,\\n            show=False,\\n        ),\\n        BoolInput(\\n            name=\\\"enable_fallback\\\",\\n            display_name=\\\"Enable Fallback\\\",\\n            info=\\\"Add a 'fallback' output taken when the answer arrives after the timeout window.\\\",\\n            value=False,\\n            advanced=True,\\n            real_time_refresh=True,\\n        ),\\n    ]\\n\\n    # Default branch outputs mirror the default ``decisions`` so a freshly dragged\\n    # node shows handles immediately (update_outputs only fires on a field change).\\n    outputs: list[Output] = [\\n        Output(display_name=\\\"Approve\\\", name=\\\"branch_approve\\\", method=\\\"route_branch\\\", group_outputs=True),\\n        Output(display_name=\\\"Reject\\\", name=\\\"branch_reject\\\", method=\\\"route_branch\\\", group_outputs=True),\\n    ]\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict) -> dict:\\n        \\\"\\\"\\\"Rebuild branch outputs from the saved User Choices so loaded/refreshed flows keep their handles.\\\"\\\"\\\"\\n        new_frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = new_frontend_node.get(\\\"template\\\", {})\\n        decisions = (template.get(\\\"decisions\\\") or {}).get(\\\"value\\\")\\n        self.update_outputs(new_frontend_node, \\\"decisions\\\", decisions if decisions is not None else [])\\n        self._sync_timeout_visibility(template)\\n        return new_frontend_node\\n\\n    @staticmethod\\n    def _sync_timeout_visibility(template: dict) -> None:\\n        \\\"\\\"\\\"Timeout only matters when the fallback branch exists to reroute to.\\\"\\\"\\\"\\n        if \\\"timeout\\\" in template:\\n            template[\\\"timeout\\\"][\\\"show\\\"] = bool((template.get(\\\"enable_fallback\\\") or {}).get(\\\"value\\\"))\\n\\n    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:\\n        if field_name == \\\"enable_fallback\\\" and \\\"timeout\\\" in build_config:\\n            build_config[\\\"timeout\\\"][\\\"show\\\"] = bool(field_value)\\n        return build_config\\n\\n    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:\\n        \\\"\\\"\\\"One branch output per selected action (+ optional fallback) + a stable action output.\\\"\\\"\\\"\\n        if field_name not in (\\\"decisions\\\", \\\"enable_fallback\\\"):\\n            return frontend_node\\n        template = frontend_node.get(\\\"template\\\", {})\\n\\n        def _other(field: str, attr_default):\\n            if field in template:\\n                return (template.get(field) or {}).get(\\\"value\\\")\\n            return getattr(self, attr_default[0], attr_default[1])\\n\\n        actions = field_value if field_name == \\\"decisions\\\" else _other(\\\"decisions\\\", (\\\"decisions\\\", []))\\n        fallback_on = (\\n            field_value if field_name == \\\"enable_fallback\\\" else _other(\\\"enable_fallback\\\", (\\\"enable_fallback\\\", False))\\n        )\\n        outputs: list[Output] = []\\n        seen: set[str] = set()\\n        for label in actions or []:\\n            action_id = _action_id(label)\\n            if not action_id or action_id in seen:\\n                continue\\n            seen.add(action_id)\\n            outputs.append(\\n                Output(\\n                    display_name=str(label).strip(),\\n                    name=f\\\"branch_{action_id}\\\",\\n                    method=\\\"route_branch\\\",\\n                    group_outputs=True,\\n                )\\n            )\\n        if fallback_on:\\n            outputs.append(\\n                Output(\\n                    display_name=\\\"Fallback\\\",\\n                    name=f\\\"branch_{_FALLBACK_ACTION}\\\",\\n                    method=\\\"route_branch\\\",\\n                    group_outputs=True,\\n                )\\n            )\\n        frontend_node[\\\"outputs\\\"] = outputs\\n        return frontend_node\\n\\n    def _actions(self) -> list[tuple[str, str]]:\\n        \\\"\\\"\\\"Selected actions as (action_id, label) pairs, de-duplicated by id.\\\"\\\"\\\"\\n        seen: set[str] = set()\\n        actions: list[tuple[str, str]] = []\\n        for label in getattr(self, \\\"decisions\\\", []) or []:\\n            action_id = _action_id(label)\\n            if not action_id or action_id in seen:\\n                continue\\n            seen.add(action_id)\\n            actions.append((action_id, str(label).strip()))\\n        return actions\\n\\n    def _rendered_prompt(self) -> str:\\n        return str(getattr(self, \\\"prompt\\\", \\\"\\\") or \\\"\\\")\\n\\n    def _timeout_seconds(self) -> int:\\n        timeout = getattr(self, \\\"timeout\\\", None) or {}\\n        if not isinstance(timeout, dict):\\n            return 0\\n        unit = timeout.get(\\\"unit\\\", \\\"Days\\\") or \\\"Days\\\"\\n        return int(timeout.get(\\\"value\\\", 0) or 0) * _UNIT_SECONDS.get(unit, _UNIT_SECONDS[\\\"Days\\\"])\\n\\n    def _request_id(self) -> str:\\n        run_id = str(getattr(self.graph, \\\"run_id\\\", \\\"\\\") or \\\"\\\")\\n        return f\\\"{self._id}:{run_id}\\\"\\n\\n    def _injected_decision(self) -> dict | None:\\n        decisions = getattr(self.graph, \\\"human_input_decisions\\\", None) if self.graph is not None else None\\n        if not isinstance(decisions, dict):\\n            return None\\n        return decisions.get(self._request_id())\\n\\n    def _allowed_decisions(self) -> list[str]:\\n        ids = [action_id for action_id, _ in self._actions()]\\n        if getattr(self, \\\"enable_fallback\\\", False):\\n            ids.append(_FALLBACK_ACTION)\\n        return ids\\n\\n    def _pause_request(self) -> dict[str, Any]:\\n        return {\\n            \\\"request_id\\\": self._request_id(),\\n            \\\"kind\\\": _KIND_NODE_INPUT,\\n            \\\"prompt\\\": self._rendered_prompt(),\\n            \\\"options\\\": [{\\\"action_id\\\": action_id, \\\"label\\\": label} for action_id, label in self._actions()],\\n            \\\"allowed_decisions\\\": self._allowed_decisions(),\\n            \\\"timeout_seconds\\\": self._timeout_seconds(),\\n            \\\"fallback_action\\\": _FALLBACK_ACTION if getattr(self, \\\"enable_fallback\\\", False) else None,\\n            \\\"paused_at\\\": datetime.now(timezone.utc).isoformat(),\\n        }\\n\\n    def _has_downstream_consumer(self) -> bool:\\n        \\\"\\\"\\\"True if any branch output feeds a downstream node.\\n\\n        A node with no outgoing edges runs as an isolated start vertex; pausing it would\\n        suspend the whole run for a decision that routes nowhere (and, alongside an Agent's\\n        own tool-approval pause, leave that pause unresolved on resume). The successor_map is\\n        absent only outside a prepared graph (standalone/tests), where the old behavior holds.\\n        \\\"\\\"\\\"\\n        graph = getattr(self, \\\"graph\\\", None)\\n        successor_map = getattr(graph, \\\"successor_map\\\", None)\\n        if not isinstance(successor_map, dict):\\n            return True\\n        return bool(successor_map.get(self._id))\\n\\n    def _suspend(self) -> None:\\n        self.graph.request_pause(reason=HUMAN_INPUT_REQUIRED, data=self._pause_request())\\n        self.status = \\\"Awaiting human input\\\"\\n\\n    def route_branch(self) -> Message:\\n        decision = self._injected_decision()\\n        if decision is None:\\n            if not self._has_downstream_consumer():\\n                self.status = \\\"Skipped: no connected outputs\\\"\\n                return Message(text=self._rendered_prompt())\\n            self._suspend()\\n            return Message(text=\\\"\\\")\\n        chosen = decision.get(\\\"action_id\\\")\\n        non_chosen = [action_id for action_id in self._allowed_decisions() if action_id != chosen]\\n        for action_id in non_chosen:\\n            self.stop(f\\\"branch_{action_id}\\\")\\n        return Message(text=self._rendered_prompt())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/listen.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7f4e3f36b7e22ab7d3db91a905c68f41bf9d987fb6d8460e0d288bffae0ef94f\",\"content\":\"from lfx.custom import Component\\nfrom lfx.io import Output, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass ListenComponent(Component):\\n    display_name = \\\"Listen\\\"\\n    description = \\\"A component to listen for a notification.\\\"\\n    name = \\\"Listen\\\"\\n    beta: bool = True\\n    icon = \\\"Radio\\\"\\n    inputs = [\\n        StrInput(\\n            name=\\\"context_key\\\",\\n            display_name=\\\"Context Key\\\",\\n            info=\\\"The key of the context to listen for.\\\",\\n            input_types=[\\\"Message\\\"],\\n            required=True,\\n        )\\n    ]\\n\\n    outputs = [Output(name=\\\"data\\\", display_name=\\\"JSON\\\", method=\\\"listen_for_data\\\", cache=False)]\\n\\n    def listen_for_data(self) -> Data:\\n        \\\"\\\"\\\"Retrieves a Data object from the component context using the provided context key.\\n\\n        If the specified context key does not exist in the context, returns an empty Data object.\\n        \\\"\\\"\\\"\\n        return self.ctx.get(self.context_key, Data(text=\\\"\\\"))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/loop.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2712a1de7210b3f15506893853fefc69ae66f7d802fe633869a27b80fe453704\",\"content\":\"from lfx.base.flow_controls.loop_utils import (\\n    execute_loop_body,\\n    extract_loop_output,\\n    get_loop_body_start_edge,\\n    get_loop_body_start_vertex,\\n    get_loop_body_vertices,\\n    validate_data_input,\\n)\\nfrom lfx.components.processing.converter import convert_to_data\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import HandleInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\nfrom lfx.template.field.base import Output\\n\\n\\nclass LoopComponent(Component):\\n    display_name = \\\"Loop\\\"\\n    description = (\\n        \\\"Iterates through Data or Message objects, processing items individually \\\"\\n        \\\"and aggregating results from loop inputs.\\\"\\n    )\\n    documentation: str = \\\"https://docs.langflow.org/loop\\\"\\n    icon = \\\"infinity\\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\\"data\\\",\\n            display_name=\\\"Inputs\\\",\\n            info=\\\"Data to iterate over. Accepts DataFrame, Table, Data, or Message.\\\",\\n            input_types=[\\\"DataFrame\\\", \\\"Table\\\", \\\"Data\\\", \\\"Message\\\"],\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Item\\\",\\n            name=\\\"item\\\",\\n            method=\\\"item_output\\\",\\n            types=[\\\"Data\\\"],\\n            allows_loop=True,\\n            loop_types=[\\\"Message\\\"],\\n            group_outputs=True,\\n        ),\\n        Output(\\n            display_name=\\\"Done\\\",\\n            name=\\\"done\\\",\\n            method=\\\"done_output\\\",\\n            types=[\\\"DataFrame\\\", \\\"Table\\\"],\\n            group_outputs=True,\\n        ),\\n    ]\\n\\n    def initialize_data(self) -> None:\\n        \\\"\\\"\\\"Initialize the data list and context index.\\n\\n        Seeds the input list and index counter in ctx. The aggregated results\\n        are owned by `_iterate`, which writes them once the subgraph finishes.\\n        \\\"\\\"\\\"\\n        if self.ctx.get(f\\\"{self._id}_initialized\\\", False):\\n            return\\n\\n        # Ensure data is a list of Data objects\\n        data_list = self._validate_data(self.data)\\n\\n        # Store the initial data and context variables\\n        self.update_ctx(\\n            {\\n                f\\\"{self._id}_data\\\": data_list,\\n                f\\\"{self._id}_index\\\": 0,\\n                f\\\"{self._id}_initialized\\\": True,\\n            }\\n        )\\n\\n    def _convert_message_to_data(self, message: Message) -> Data:\\n        \\\"\\\"\\\"Convert a Message object to a Data object using Type Convert logic.\\\"\\\"\\\"\\n        return convert_to_data(message, auto_parse=False)\\n\\n    def _validate_data(self, data):\\n        \\\"\\\"\\\"Validate and normalize the input to a flat list of Data objects.\\n\\n        Coerces each accepted input type into Data so `validate_data_input`\\n        always receives a homogeneous payload:\\n        - Message -> a clean Data via `_convert_message_to_data` (just the\\n          message payload, not the full envelope). `Message` subclasses\\n          `Data`, so without this it would slip through as a single Data\\n          carrying all of the message metadata.\\n        - DataFrame/Table -> expanded to its rows.\\n        - Data / list[Data] -> passed through unchanged.\\n\\n        Lists are normalized item-by-item so a mixed `[Message, DataFrame,\\n        Data]` still yields `list[Data]` instead of being rejected as a\\n        mixed-type list (`validate_data_input` requires every list item to be\\n        a Data, and DataFrame is not a Data subclass).\\n        \\\"\\\"\\\"\\n        if isinstance(data, Message):\\n            data = self._convert_message_to_data(data)\\n        elif isinstance(data, list):\\n            normalized: list = []\\n            for item in data:\\n                if isinstance(item, Message):\\n                    normalized.append(self._convert_message_to_data(item))\\n                elif isinstance(item, DataFrame):\\n                    normalized.extend(item.to_data_list())\\n                else:\\n                    normalized.append(item)\\n            data = normalized\\n        return validate_data_input(data)\\n\\n    def get_loop_body_vertices(self) -> set[str]:\\n        \\\"\\\"\\\"Identify vertices in this loop's body via graph traversal.\\n\\n        Traverses from the loop's \\\"item\\\" output to the vertex that feeds back\\n        to the loop's \\\"item\\\" input, collecting all vertices in between.\\n        This naturally handles nested loops by stopping at this loop's feedback edge.\\n\\n        Returns:\\n            Set of vertex IDs that form this loop's body\\n        \\\"\\\"\\\"\\n        # Check if we have a proper graph context\\n        if not hasattr(self, \\\"_vertex\\\") or self._vertex is None:\\n            return set()\\n\\n        return get_loop_body_vertices(\\n            vertex=self._vertex,\\n            graph=self.graph,\\n            get_incoming_edge_by_target_param_fn=self.get_incoming_edge_by_target_param,\\n        )\\n\\n    def _get_loop_body_start_vertex(self) -> str | None:\\n        \\\"\\\"\\\"Get the first vertex in the loop body (connected to loop's item output).\\n\\n        Returns:\\n            The vertex ID of the first vertex in the loop body, or None if not found\\n        \\\"\\\"\\\"\\n        # Check if we have a proper graph context\\n        if not hasattr(self, \\\"_vertex\\\") or self._vertex is None:\\n            return None\\n\\n        return get_loop_body_start_vertex(vertex=self._vertex)\\n\\n    def _extract_loop_output(self, results: list) -> Data:\\n        \\\"\\\"\\\"Extract the output from subgraph execution results.\\n\\n        Args:\\n            results: List of VertexBuildResult objects from subgraph execution\\n\\n        Returns:\\n            Data object containing the loop iteration output\\n        \\\"\\\"\\\"\\n        # Get the vertex ID that feeds back to the item input (end of loop body)\\n        end_vertex_id = self.get_incoming_edge_by_target_param(\\\"item\\\")\\n        return extract_loop_output(results=results, end_vertex_id=end_vertex_id)\\n\\n    async def execute_loop_body(self, data_list: list[Data], event_manager=None) -> list[Data]:\\n        \\\"\\\"\\\"Execute loop body for each data item.\\n\\n        Creates an isolated subgraph for the loop body and executes it\\n        for each item in the data list, collecting results.\\n\\n        Args:\\n            data_list: List of Data objects to iterate over\\n            event_manager: Optional event manager to pass to subgraph execution for UI events\\n\\n        Returns:\\n            List of Data objects containing results from each iteration\\n        \\\"\\\"\\\"\\n        # Get the loop body configuration once\\n        loop_body_vertex_ids = self.get_loop_body_vertices()\\n        start_vertex_id = self._get_loop_body_start_vertex()\\n        start_edge = get_loop_body_start_edge(self._vertex)\\n        end_vertex_id = self.get_incoming_edge_by_target_param(\\\"item\\\")\\n\\n        return await execute_loop_body(\\n            graph=self.graph,\\n            data_list=data_list,\\n            loop_body_vertex_ids=loop_body_vertex_ids,\\n            start_vertex_id=start_vertex_id,\\n            start_edge=start_edge,\\n            end_vertex_id=end_vertex_id,\\n            event_manager=event_manager,\\n        )\\n\\n    async def _iterate(self) -> list[Data]:\\n        \\\"\\\"\\\"Run the loop body subgraph once and cache the aggregated results.\\n\\n        Both `item_output` and `done_output` may be called during the same\\n        vertex build (if both outputs have downstream consumers), so this\\n        helper is idempotent: it caches the aggregated results in ctx under\\n        `{self._id}_aggregated` and guards re-entry with `{self._id}_iterated`.\\n        If a prior call raised, the exception is cached in\\n        `{self._id}_iteration_error` and re-raised on subsequent calls so\\n        repeat invocations surface the same failure instead of silently\\n        returning empty data or re-running the subgraph.\\n\\n        Production constructs a fresh Graph per request (via\\n        `Graph.from_payload`), so `ctx` is effectively per-run and the\\n        cached `_iterated` flag does not leak across executions.\\n        \\\"\\\"\\\"\\n        if self.ctx.get(f\\\"{self._id}_iterated\\\", False):\\n            cached_error = self.ctx.get(f\\\"{self._id}_iteration_error\\\")\\n            if cached_error is not None:\\n                raise cached_error\\n            return self.ctx.get(f\\\"{self._id}_aggregated\\\", [])\\n\\n        import time\\n\\n        started_at = time.perf_counter()\\n        try:\\n            self.initialize_data()\\n            data_list = self.ctx.get(f\\\"{self._id}_data\\\", [])\\n            self.log(f\\\"Starting loop over {len(data_list)} item(s)\\\", name=\\\"Start\\\")\\n\\n            if not data_list:\\n                self.update_ctx({f\\\"{self._id}_aggregated\\\": [], f\\\"{self._id}_iterated\\\": True})\\n                self.log(\\\"No items to iterate, skipping loop body\\\", name=\\\"Skipped\\\")\\n                return []\\n\\n            aggregated_results = await self.execute_loop_body(data_list, event_manager=self._event_manager)\\n        except Exception as exc:\\n            from lfx.log.logger import logger\\n\\n            elapsed = time.perf_counter() - started_at\\n            self.log(f\\\"Loop failed after {elapsed:.3f}s: {exc}\\\", name=\\\"Error\\\")\\n            await logger.aexception(f\\\"Loop {self._id} failed while executing loop body\\\")\\n            self.update_ctx({f\\\"{self._id}_iteration_error\\\": exc, f\\\"{self._id}_iterated\\\": True})\\n            raise\\n\\n        elapsed = time.perf_counter() - started_at\\n        self.log(\\n            f\\\"Completed {len(aggregated_results)} iteration(s) in {elapsed:.3f}s\\\",\\n            name=\\\"Complete\\\",\\n        )\\n        self.update_ctx({f\\\"{self._id}_aggregated\\\": aggregated_results, f\\\"{self._id}_iterated\\\": True})\\n        return aggregated_results\\n\\n    async def item_output(self) -> Data:\\n        \\\"\\\"\\\"Display the inputs dispatched to the loop body.\\n\\n        Also triggers the iteration (idempotent) when `done` has no\\n        downstream consumer, so the loop still runs if only the Item\\n        output is connected. When `done` IS connected we leave iteration\\n        to `done_output`. The `item` branch is stopped in both cases so\\n        downstream vertices aren't executed by the outer graph (the loop\\n        body runs internally via the subgraph in `_iterate`).\\n\\n        Returns a `Data` envelope so the outer item edge remains\\n        compatible with Data-typed consumers in the loop body. The\\n        wrapped payload exposes the iterated rows for inspection.\\n        \\\"\\\"\\\"\\n        self.stop(\\\"item\\\")\\n        if self._vertex is not None and \\\"done\\\" not in self._vertex.edges_source_names:\\n            await self._iterate()\\n        data_list = self.ctx.get(f\\\"{self._id}_data\\\", [])\\n        return Data(data={\\\"count\\\": len(data_list), \\\"items\\\": [d.data for d in data_list]})\\n\\n    async def done_output(self) -> DataFrame:\\n        \\\"\\\"\\\"Return the aggregated results from the loop iteration.\\n\\n        Triggers the iteration if it hasn't run yet (for example when only\\n        `done` is connected and `item_output` never executed). In the common\\n        case where `item` is also connected, `_iterate` has already cached\\n        the aggregated results in ctx and this call is a cheap read, so the\\n        order in which the two outputs are evaluated does not matter.\\n        \\\"\\\"\\\"\\n        aggregated_results = await self._iterate()\\n        return DataFrame(aggregated_results)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/notify.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a22284d4b01e30b75823af753c5eaf90f98d803195045a72f0bd5c56845b1e79\",\"content\":\"from typing import cast\\n\\nfrom lfx.custom import Component\\nfrom lfx.io import BoolInput, HandleInput, Output, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass NotifyComponent(Component):\\n    display_name = \\\"Notify\\\"\\n    description = \\\"A component to generate a notification to Get Notified component.\\\"\\n    icon = \\\"Notify\\\"\\n    name = \\\"Notify\\\"\\n    beta: bool = True\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"context_key\\\",\\n            display_name=\\\"Context Key\\\",\\n            info=\\\"The key of the context to store the notification.\\\",\\n            required=True,\\n        ),\\n        HandleInput(\\n            name=\\\"input_value\\\",\\n            display_name=\\\"Input Data\\\",\\n            info=\\\"The data to store.\\\",\\n            required=False,\\n            input_types=[\\\"Data\\\", \\\"JSON\\\", \\\"Message\\\", \\\"DataFrame\\\", \\\"Table\\\"],\\n        ),\\n        BoolInput(\\n            name=\\\"append\\\",\\n            display_name=\\\"Append\\\",\\n            info=\\\"If True, the record will be appended to the notification.\\\",\\n            value=False,\\n            required=False,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"JSON\\\",\\n            name=\\\"result\\\",\\n            method=\\\"notify_components\\\",\\n            cache=False,\\n        ),\\n    ]\\n\\n    async def notify_components(self) -> Data:\\n        \\\"\\\"\\\"Processes and stores a notification in the component's context.\\n\\n        Normalizes the input value to a `Data` object and stores it under the\\n        specified context key. If `append` is True, adds the value to a list\\n        of notifications; otherwise, replaces the existing value. Updates the\\n        component's status and activates related state vertices in the graph.\\n\\n        Returns:\\n            The processed `Data` object stored in the context.\\n\\n        Raises:\\n            ValueError: If the component is not part of a graph.\\n        \\\"\\\"\\\"\\n        if not self._vertex:\\n            msg = \\\"Notify component must be used in a graph.\\\"\\n            raise ValueError(msg)\\n        input_value: Data | str | dict | None = self.input_value\\n        if input_value is None:\\n            input_value = Data(text=\\\"\\\")\\n        elif not isinstance(input_value, Data):\\n            if isinstance(input_value, str):\\n                input_value = Data(text=input_value)\\n            elif isinstance(input_value, dict):\\n                input_value = Data(data=input_value)\\n            else:\\n                input_value = Data(text=str(input_value))\\n        if input_value:\\n            if self.append:\\n                current_data = self.ctx.get(self.context_key, [])\\n                if not isinstance(current_data, list):\\n                    current_data = [current_data]\\n                current_data.append(input_value)\\n                self.update_ctx({self.context_key: current_data})\\n            else:\\n                self.update_ctx({self.context_key: input_value})\\n            self.status = input_value\\n        else:\\n            self.status = \\\"No record provided.\\\"\\n        self._vertex.is_state = True\\n        self.graph.activate_state_vertices(name=self.context_key, caller=self._id)\\n        return cast(\\\"Data\\\", input_value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/pass_message.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"04d3e1ed3390facbeb851dbeb8c40c313d0b056d2c4ffcf32296ee59e1043c36\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageInput\\nfrom lfx.schema.message import Message\\nfrom lfx.template.field.base import Output\\n\\n\\nclass PassMessageComponent(Component):\\n    display_name = \\\"Pass\\\"\\n    description = \\\"Forwards the input message, unchanged.\\\"\\n    name = \\\"Pass\\\"\\n    icon = \\\"arrow-right\\\"\\n    legacy: bool = True\\n    replacement = [\\\"logic.ConditionalRouter\\\"]\\n\\n    inputs = [\\n        MessageInput(\\n            name=\\\"input_message\\\",\\n            display_name=\\\"Input Message\\\",\\n            info=\\\"The message to be passed forward.\\\",\\n            required=True,\\n        ),\\n        MessageInput(\\n            name=\\\"ignored_message\\\",\\n            display_name=\\\"Ignored Message\\\",\\n            info=\\\"A second message to be ignored. Used as a workaround for continuity.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Output Message\\\", name=\\\"output_message\\\", method=\\\"pass_message\\\"),\\n    ]\\n\\n    def pass_message(self) -> Message:\\n        self.status = self.input_message\\n        return self.input_message\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/run_flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ea901208037dfb27d712e359a1cb4b83f7ffee67fa52c56c2a64f22bbe0673ba\",\"content\":\"from copy import deepcopy\\nfrom datetime import datetime\\nfrom typing import Any\\n\\nfrom lfx.base.tools.run_flow import RunFlowBaseComponent\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\n\\n\\nclass RunFlowComponent(RunFlowBaseComponent):\\n    display_name = \\\"Run Flow\\\"\\n    description = (\\n        \\\"Executes another flow from within the same project. Can also be used as a tool for agents.\\\"\\n        \\\" \\\\n **Select a Flow to use the tool mode**\\\"\\n    )\\n    documentation: str = \\\"https://docs.langflow.org/run-flow\\\"\\n    beta = True\\n    name = \\\"RunFlow\\\"\\n    icon = \\\"Workflow\\\"\\n\\n    # Keep the concrete class templates detached from the base-class templates;\\n    # Component.__init__ still makes the per-instance copies used at runtime.\\n    inputs = deepcopy(RunFlowBaseComponent.get_base_inputs())\\n    outputs = deepcopy(RunFlowBaseComponent.get_base_outputs())\\n\\n    async def update_build_config(\\n        self,\\n        build_config: dotdict,\\n        field_value: Any,\\n        field_name: str | None = None,\\n    ):\\n        missing_keys = [key for key in self.default_keys if key not in build_config]\\n        for key in missing_keys:  # TODO: create a defaults dict to avoid hardcoding the defaults here\\n            if key == \\\"flow_name_selected\\\":\\n                build_config[key] = {\\\"options\\\": [], \\\"options_metadata\\\": [], \\\"value\\\": None}\\n            elif key == \\\"flow_id_selected\\\":\\n                build_config[key] = {\\\"value\\\": None}\\n            elif key == \\\"cache_flow\\\":\\n                build_config[key] = {\\\"value\\\": False}\\n            else:\\n                build_config[key] = {}\\n        if field_name == \\\"flow_name_selected\\\" and (build_config.get(\\\"is_refresh\\\", False) or field_value is None):\\n            # refresh button was clicked or componented was initialized, so list the flows\\n            options: list[str] = await self.alist_flows_by_flow_folder()\\n            build_config[\\\"flow_name_selected\\\"][\\\"options\\\"] = [flow.data[\\\"name\\\"] for flow in options]\\n            build_config[\\\"flow_name_selected\\\"][\\\"options_metadata\\\"] = []\\n            for flow in options:\\n                # populate options_metadata\\n                build_config[\\\"flow_name_selected\\\"][\\\"options_metadata\\\"].append(\\n                    {\\\"id\\\": flow.data[\\\"id\\\"], \\\"updated_at\\\": flow.data[\\\"updated_at\\\"]}\\n                )\\n                # update selected flow if it is stale\\n                if str(flow.data[\\\"id\\\"]) == self.flow_id_selected:\\n                    await self.check_and_update_stale_flow(flow, build_config)\\n        elif field_name in {\\\"flow_name_selected\\\", \\\"flow_id_selected\\\"} and field_value is not None:\\n            # flow was selected by name or id, so get the flow and update the bcfg\\n            try:\\n                # derive flow id if the field_name is flow_name_selected\\n                build_config[\\\"flow_id_selected\\\"][\\\"value\\\"] = (\\n                    self.get_selected_flow_meta(build_config, \\\"id\\\") or build_config[\\\"flow_id_selected\\\"][\\\"value\\\"]\\n                )\\n                updated_at = self.get_selected_flow_meta(build_config, \\\"updated_at\\\")\\n                await self.load_graph_and_update_cfg(\\n                    build_config, build_config[\\\"flow_id_selected\\\"][\\\"value\\\"], updated_at\\n                )\\n            except Exception as e:\\n                msg = f\\\"Error building graph for flow {field_value}\\\"\\n                await logger.aexception(msg)\\n                raise RuntimeError(msg) from e\\n\\n        return build_config\\n\\n    def get_selected_flow_meta(self, build_config: dotdict, field: str) -> dict:\\n        \\\"\\\"\\\"Get the selected flow's metadata from the build config.\\\"\\\"\\\"\\n        return build_config.get(\\\"flow_name_selected\\\", {}).get(\\\"selected_metadata\\\", {}).get(field)\\n\\n    async def load_graph_and_update_cfg(\\n        self,\\n        build_config: dotdict,\\n        flow_id: str,\\n        updated_at: str | datetime,\\n    ) -> None:\\n        \\\"\\\"\\\"Load a flow's graph and update the build config.\\\"\\\"\\\"\\n        graph = await self.get_graph(\\n            flow_id_selected=flow_id,\\n            updated_at=self.get_str_isots(updated_at),\\n        )\\n        self.update_build_config_from_graph(build_config, graph)\\n\\n    def should_update_stale_flow(self, flow: Data, build_config: dotdict) -> bool:\\n        \\\"\\\"\\\"Check if the flow should be updated.\\\"\\\"\\\"\\n        return (\\n            (updated_at := self.get_str_isots(flow.data[\\\"updated_at\\\"]))  # true updated_at date just fetched from db\\n            and (stale_at := self.get_selected_flow_meta(build_config, \\\"updated_at\\\"))  # outdated date in bcfg\\n            and self._parse_timestamp(updated_at) > self._parse_timestamp(stale_at)  # stale flow condition\\n        )\\n\\n    async def check_and_update_stale_flow(self, flow: Data, build_config: dotdict) -> None:\\n        \\\"\\\"\\\"Check if the flow should be updated and update it if necessary.\\\"\\\"\\\"\\n        # TODO: improve contract/return value\\n        if self.should_update_stale_flow(flow, build_config):\\n            await self.load_graph_and_update_cfg(\\n                build_config,\\n                flow.data[\\\"id\\\"],\\n                flow.data[\\\"updated_at\\\"],\\n            )\\n\\n    def get_str_isots(self, date: datetime | str) -> str:\\n        \\\"\\\"\\\"Get a string timestamp from a datetime or string.\\\"\\\"\\\"\\n        return date.isoformat() if hasattr(date, \\\"isoformat\\\") else date\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/flow_controls/sub_flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"70db23b079a9a32e7d938151c0db4042d9ce35f3271e852caf2d7d86e70dec78\",\"content\":\"from typing import Any\\n\\nfrom lfx.base.flow_processing.utils import build_data_from_result_data\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.graph.vertex.base import Vertex\\nfrom lfx.helpers import get_flow_inputs\\nfrom lfx.io import DropdownInput, Output\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\n\\n\\nclass SubFlowComponent(Component):\\n    display_name = \\\"Sub Flow\\\"\\n    description = \\\"Generates a Component from a Flow, with all of its inputs, and \\\"\\n    name = \\\"SubFlow\\\"\\n    legacy: bool = True\\n    replacement = [\\\"logic.RunFlow\\\"]\\n    icon = \\\"Workflow\\\"\\n\\n    async def get_flow_names(self) -> list[str]:\\n        flow_data = await self.alist_flows()\\n        return [flow_data.data[\\\"name\\\"] for flow_data in flow_data]\\n\\n    async def get_flow(self, flow_name: str) -> Data | None:\\n        flow_datas = await self.alist_flows()\\n        for flow_data in flow_datas:\\n            if flow_data.data[\\\"name\\\"] == flow_name:\\n                return flow_data\\n        return None\\n\\n    async def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None):\\n        if field_name == \\\"flow_name\\\":\\n            build_config[\\\"flow_name\\\"][\\\"options\\\"] = await self.get_flow_names()\\n\\n        for key in list(build_config.keys()):\\n            if key not in [x.name for x in self.inputs] + [\\\"code\\\", \\\"_type\\\", \\\"get_final_results_only\\\"]:\\n                del build_config[key]\\n        if field_value is not None and field_name == \\\"flow_name\\\":\\n            try:\\n                flow_data = await self.get_flow(field_value)\\n            except Exception:  # noqa: BLE001\\n                await logger.aexception(f\\\"Error getting flow {field_value}\\\")\\n            else:\\n                if not flow_data:\\n                    msg = f\\\"Flow {field_value} not found.\\\"\\n                    await logger.aerror(msg)\\n                else:\\n                    try:\\n                        graph = await self.load_flow(str(flow_data.id))\\n                        # Get all inputs from the graph\\n                        inputs = get_flow_inputs(graph)\\n                        # Add inputs to the build config\\n                        build_config = self.add_inputs_to_build_config(inputs, build_config)\\n                    except Exception:  # noqa: BLE001\\n                        await logger.aexception(f\\\"Error building graph for flow {field_value}\\\")\\n\\n        return build_config\\n\\n    def add_inputs_to_build_config(self, inputs_vertex: list[Vertex], build_config: dotdict):\\n        new_fields: list[dotdict] = []\\n\\n        for vertex in inputs_vertex:\\n            new_vertex_inputs = []\\n            field_template = vertex.data[\\\"node\\\"][\\\"template\\\"]\\n            for inp in field_template:\\n                if inp not in {\\\"code\\\", \\\"_type\\\"}:\\n                    field_template[inp][\\\"display_name\\\"] = (\\n                        vertex.display_name + \\\" - \\\" + field_template[inp][\\\"display_name\\\"]\\n                    )\\n                    field_template[inp][\\\"name\\\"] = vertex.id + \\\"|\\\" + inp\\n                    new_vertex_inputs.append(field_template[inp])\\n            new_fields += new_vertex_inputs\\n        for field in new_fields:\\n            build_config[field[\\\"name\\\"]] = field\\n        return build_config\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"flow_name\\\",\\n            display_name=\\\"Flow Name\\\",\\n            info=\\\"The name of the flow to run.\\\",\\n            options=[],\\n            refresh_button=True,\\n            real_time_refresh=True,\\n        ),\\n    ]\\n\\n    outputs = [Output(name=\\\"flow_outputs\\\", display_name=\\\"Flow Outputs\\\", method=\\\"generate_results\\\")]\\n\\n    async def generate_results(self) -> list[Data]:\\n        tweaks: dict = {}\\n        for field in self._attributes:\\n            if field != \\\"flow_name\\\" and \\\"|\\\" in field:\\n                [node, name] = field.split(\\\"|\\\")\\n                if node not in tweaks:\\n                    tweaks[node] = {}\\n                tweaks[node][name] = self._attributes[field]\\n        flow_name = self._attributes.get(\\\"flow_name\\\")\\n        run_outputs = await self.run_flow(\\n            tweaks=tweaks,\\n            flow_name=flow_name,\\n            output_type=\\\"all\\\",\\n        )\\n        data: list[Data] = []\\n        if not run_outputs:\\n            return data\\n        run_output = run_outputs[0]\\n\\n        if run_output is not None:\\n            for output in run_output.outputs:\\n                if output:\\n                    data.extend(build_data_from_result_data(output))\\n        return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/knowledge_bases/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e126a7e3c08413d57fe74070266f2991ccfb0b47207b5d56b04520ab23644ba1\",\"content\":\"# lfx-compat-shim\\n\\\"\\\"\\\"Knowledge bases module - backwards compatibility alias for files_and_knowledge.\\n\\nThis module provides backwards compatibility by forwarding all imports\\nto files_and_knowledge where the actual knowledge base components are located.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport sys\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from lfx.components.files_and_knowledge.retrieval import KnowledgeBaseComponent\\n\\n_dynamic_imports = {\\n    \\\"KnowledgeBaseComponent\\\": \\\"retrieval\\\",\\n}\\n\\n__all__ = [\\\"KnowledgeBaseComponent\\\"]\\n\\n# Register redirected submodules in sys.modules for direct importlib.import_module() calls\\n# This allows imports like: import lfx.components.knowledge_bases.retrieval\\n_redirected_submodules = {\\n    \\\"lfx.components.knowledge_bases.retrieval\\\": \\\"lfx.components.files_and_knowledge.retrieval\\\",\\n}\\n\\nfor old_path, new_path in _redirected_submodules.items():\\n    if old_path not in sys.modules:\\n        # Use a lazy loader that imports the actual module when accessed\\n        class _RedirectedModule:\\n            def __init__(self, target_path: str, original_path: str):\\n                self._target_path = target_path\\n                self._original_path = original_path\\n                self._module = None\\n\\n            def __getattr__(self, name: str) -> Any:\\n                if self._module is None:\\n                    from importlib import import_module\\n\\n                    self._module = import_module(self._target_path)\\n                    # Also register under the original path for future imports\\n                    sys.modules[self._original_path] = self._module\\n                return getattr(self._module, name)\\n\\n            def __repr__(self) -> str:\\n                return f\\\"<redirected module '{self._original_path}' -> '{self._target_path}'>\\\"\\n\\n        sys.modules[old_path] = _RedirectedModule(new_path, old_path)\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Forward attribute access to files_and_knowledge components.\\\"\\\"\\\"\\n    # Handle submodule access for backwards compatibility\\n    if attr_name == \\\"retrieval\\\":\\n        from importlib import import_module\\n\\n        result = import_module(\\\"lfx.components.files_and_knowledge.retrieval\\\")\\n        globals()[attr_name] = result\\n        return result\\n\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n\\n    # Import from files_and_knowledge using the correct package path\\n    package = \\\"lfx.components.files_and_knowledge\\\"\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], package)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    \\\"\\\"\\\"Return directory of available components.\\\"\\\"\\\"\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/models_and_agents/agent_helpers/graph_event_adapter.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9665a37dace0c194136e1796502165154a2d1de78ac38f9ac44245c67673d1e7\",\"content\":\"\\\"\\\"\\\"Adapt LangGraph events to the AgentExecutor event shape.\\n\\n`langchain.agents.create_agent` returns a `CompiledStateGraph` whose `astream_events(v2)`\\nemits the outermost `on_chain_start` with `data.input = {\\\"messages\\\": [...]}` and the\\noutermost `on_chain_end` with `data.output = {\\\"messages\\\": [..., AIMessage]}`. The legacy\\n`process_agent_events` in `lfx.base.agents.events` was written for the AgentExecutor\\nshape \u2014 `{\\\"input\\\": str, \\\"chat_history\\\": [...]}` and `AgentFinish` respectively.\\n\\nThis adapter wraps the graph's event stream and re-shapes ONLY the outermost graph\\nevents into the executor shape, so `process_agent_events` works unchanged. Inner\\nevents (graph nodes, retrievers), tool events, and chat-model-stream events pass\\nthrough untouched.\\n\\nOutermost-event detection: the run_id of the FIRST `on_chain_start` is captured;\\nevents with that run_id are the outermost graph's events. Inner nested events have\\ndifferent run_ids and are passed through verbatim.\\n\\\"\\\"\\\"\\n\\nfrom collections.abc import AsyncIterator\\nfrom typing import Any\\n\\nfrom langchain_core.agents import AgentFinish\\nfrom langchain_core.messages import AIMessage, HumanMessage\\n\\n\\nasync def adapt_graph_events_to_executor_shape(\\n    stream: AsyncIterator[dict[str, Any]],\\n) -> AsyncIterator[dict[str, Any]]:\\n    \\\"\\\"\\\"Re-shape outermost graph events; pass everything else through unchanged.\\\"\\\"\\\"\\n    outer_run_id: str | None = None\\n    async for event in stream:\\n        if outer_run_id is None and event.get(\\\"event\\\") == \\\"on_chain_start\\\":\\n            outer_run_id = event.get(\\\"run_id\\\")\\n        if event.get(\\\"run_id\\\") == outer_run_id:\\n            if event.get(\\\"event\\\") == \\\"on_chain_start\\\":\\n                yield _reshape_chain_start(event)\\n                continue\\n            if event.get(\\\"event\\\") == \\\"on_chain_end\\\":\\n                yield _reshape_chain_end(event)\\n                continue\\n        yield event\\n\\n\\ndef _reshape_chain_start(event: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Translate `{\\\"messages\\\": [...]}` \u2192 `{\\\"input\\\": str, \\\"chat_history\\\": [...]}`.\\n\\n    The user's fresh turn is the LAST HumanMessage. Everything before it is history.\\n    If the last message is not a HumanMessage (rare \u2014 defensive), keep an empty input.\\n    \\\"\\\"\\\"\\n    data = event.get(\\\"data\\\") or {}\\n    graph_input = data.get(\\\"input\\\")\\n    if not isinstance(graph_input, dict) or \\\"messages\\\" not in graph_input:\\n        return event\\n\\n    messages = list(graph_input[\\\"messages\\\"])\\n    if messages and isinstance(messages[-1], HumanMessage):\\n        last = messages[-1]\\n        text = last.content if isinstance(last.content, str) else _extract_text(last.content)\\n        executor_input = {\\\"input\\\": text, \\\"chat_history\\\": messages[:-1]}\\n    else:\\n        executor_input = {\\\"input\\\": \\\"\\\", \\\"chat_history\\\": messages}\\n\\n    return {**event, \\\"data\\\": {**data, \\\"input\\\": executor_input}}\\n\\n\\ndef _reshape_chain_end(event: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Translate final state `{\\\"messages\\\": [..., AIMessage]}` \u2192 `AgentFinish`.\\n\\n    The final answer is the LAST AIMessage in the state's messages list. If the state\\n    doesn't contain that shape (rare \u2014 defensive), pass the event through unchanged.\\n    \\\"\\\"\\\"\\n    data = event.get(\\\"data\\\") or {}\\n    output = data.get(\\\"output\\\")\\n    if not isinstance(output, dict) or \\\"messages\\\" not in output:\\n        return event\\n\\n    messages = output[\\\"messages\\\"]\\n    final_text = \\\"\\\"\\n    for msg in reversed(messages):\\n        if isinstance(msg, AIMessage):\\n            final_text = msg.content if isinstance(msg.content, str) else _extract_text(msg.content)\\n            break\\n\\n    return {**event, \\\"data\\\": {**data, \\\"output\\\": AgentFinish(return_values={\\\"output\\\": final_text}, log=\\\"\\\")}}\\n\\n\\ndef _extract_text(content: object) -> str:\\n    if isinstance(content, list):\\n        parts: list[str] = []\\n        for part in content:\\n            if isinstance(part, str):\\n                parts.append(part)\\n            elif isinstance(part, dict) and part.get(\\\"type\\\") == \\\"text\\\":\\n                parts.append(part.get(\\\"text\\\", \\\"\\\"))\\n        return \\\"\\\".join(parts)\\n    return str(content)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/components/scrapegraph/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"99e4815b48e036e92f1a8d68256ced12efb631a253e61e96e7b3a3dd7ffe7322\",\"content\":\"# lfx-bundles-shim\\n\\\"\\\"\\\"Compatibility shim: lfx.components.scrapegraph moved to lfx-bundles.\\n\\nThis module re-points to the installed bundle distribution. It contains\\nno component implementations and no third-party dependencies, and is\\nremoved once the deprecation window closes (M4).\\n\\\"\\\"\\\"\\n\\nimport importlib\\nimport sys\\n\\ntry:\\n    sys.modules[__name__] = importlib.import_module(\\\"lfx_bundles.scrapegraph\\\")\\nexcept ModuleNotFoundError as exc:\\n    if exc.name is not None and (exc.name == \\\"lfx_bundles\\\" or exc.name.startswith(\\\"lfx_bundles.\\\")):\\n        msg = (\\n            \\\"The 'scrapegraph' components moved to the 'lfx-bundles' distribution. \\\"\\n            \\\"Install it with: pip install lfx-bundles.\\\"\\n        )\\n        raise ModuleNotFoundError(msg, name=\\\"lfx_bundles\\\") from exc\\n    raise\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b878c5d905ba8bcf3fab7baca6e3e7ba54f2100fd0355e9eca0383f146601b8d\",\"content\":\"from lfx.graph.edge.base import Edge\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.graph.vertex.base import Vertex\\nfrom lfx.graph.vertex.vertex_types import CustomComponentVertex, InterfaceVertex, StateVertex\\n\\n__all__ = [\\\"CustomComponentVertex\\\", \\\"Edge\\\", \\\"Graph\\\", \\\"InterfaceVertex\\\", \\\"StateVertex\\\", \\\"Vertex\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/checkpoint/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"65dfee9f2f79d04d54d970ecf8e3dff11b794405b302b921ac693deef9f78004\",\"content\":\"from lfx.graph.checkpoint.schema import (\\n    GraphCheckpoint,\\n    VertexCheckpointData,\\n    deserialize_value,\\n    serialize_value,\\n)\\nfrom lfx.graph.checkpoint.store import CheckpointStore, InMemoryCheckpointStore\\n\\n__all__ = [\\n    \\\"CheckpointStore\\\",\\n    \\\"GraphCheckpoint\\\",\\n    \\\"InMemoryCheckpointStore\\\",\\n    \\\"VertexCheckpointData\\\",\\n    \\\"deserialize_value\\\",\\n    \\\"serialize_value\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/checkpoint/builder.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30809361c4985f4e45b07dd77be440ddd78992f7b7daa643652ea7c805651b00\",\"content\":\"\\\"\\\"\\\"Builds a GraphCheckpoint from a live Graph instance (LE-1440).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.graph.checkpoint.schema import (\\n    GraphCheckpoint,\\n    VertexCheckpointData,\\n    serialize_value,\\n    wire_has_opaque_drop,\\n)\\nfrom lfx.graph.utils import UnbuiltObject, UnbuiltResult\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n    from lfx.graph.vertex.base import Vertex\\n\\n_EMPTY_GRAPH_DATA = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n\\n\\ndef _vertex_data(vertex: Vertex) -> VertexCheckpointData:\\n    built_object_wire: dict[str, Any] | None = None\\n    raw = vertex.built_object\\n    if vertex.built and raw is not None and not isinstance(raw, (UnbuiltObject, UnbuiltResult)):\\n        candidate = serialize_value(raw)\\n        # Why: an opaque member of a dict built_object degrades to a bare None inside the envelope;\\n        # store the whole built_object as None (downstream re-derives it) instead of corrupting it to\\n        # {'x': None} or hard-raising (which would bypass the pause path and finalize the run FAILED).\\n        built_object_wire = None if wire_has_opaque_drop(candidate) else candidate\\n    built_result_wire = None\\n    if vertex.built and vertex.built_result is not None and not isinstance(vertex.built_result, UnbuiltResult):\\n        built_result_wire = serialize_value(vertex.built_result)\\n    return VertexCheckpointData(\\n        vertex_id=vertex.id,\\n        built=vertex.built,\\n        state=getattr(vertex.state, \\\"name\\\", \\\"ACTIVE\\\"),\\n        results={k: serialize_value(v) for k, v in vertex.results.items()},\\n        artifacts={k: serialize_value(v) for k, v in vertex.artifacts.items()},\\n        built_object=built_object_wire,\\n        built_result=built_result_wire,\\n    )\\n\\n\\ndef build_checkpoint(graph: Graph) -> GraphCheckpoint:\\n    run_state = graph.run_manager.to_dict()\\n    flow_payload: dict[str, Any] = dict(graph.raw_graph_data)\\n    if flow_payload == _EMPTY_GRAPH_DATA:\\n        flow_payload = {\\\"nodes\\\": list(graph._vertices), \\\"edges\\\": list(graph._edges)}  # noqa: SLF001\\n    return GraphCheckpoint(\\n        run_id=str(graph.run_id),\\n        flow_id=str(graph.flow_id) if graph.flow_id else None,\\n        source_flow_id=graph.source_flow_id,\\n        session_id=graph.session_id or None,\\n        user_id=str(graph.user_id) if graph.user_id else None,\\n        job_id=graph.job_id,\\n        flow_payload=flow_payload,\\n        run_map={k: list(v) for k, v in run_state[\\\"run_map\\\"].items()},\\n        run_predecessors={k: list(v) for k, v in run_state[\\\"run_predecessors\\\"].items()},\\n        vertices_to_run=set(run_state[\\\"vertices_to_run\\\"]),\\n        vertices_being_run=set(run_state[\\\"vertices_being_run\\\"]),\\n        ran_at_least_once=set(run_state[\\\"ran_at_least_once\\\"]),\\n        run_queue=list(graph._run_queue),  # noqa: SLF001\\n        call_order=list(graph._call_order),  # noqa: SLF001\\n        vertices_layers=[list(layer) for layer in graph.vertices_layers],\\n        first_layer=list(graph._first_layer),  # noqa: SLF001\\n        inactivated_vertices={str(v) for v in graph.inactivated_vertices},\\n        branch_inactivation_sources={\\n            str(source): {str(vertex) for vertex in vertices}\\n            for source, vertices in graph.branch_inactivation_sources.items()\\n        },\\n        conditionally_excluded_vertices={str(v) for v in graph.conditionally_excluded_vertices},\\n        activated_vertices=list(graph.activated_vertices),\\n        vertex_results={vertex.id: _vertex_data(vertex) for vertex in graph.vertices},\\n        pause_context=graph.pause_info,\\n        human_input_decisions=dict(getattr(graph, \\\"human_input_decisions\\\", {}) or {}),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/checkpoint/probe.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5ff5362e2029d4f4b0394955333c3e900b8740931dc591d3f97b21cae42b12e0\",\"content\":\"\\\"\\\"\\\"Injected pause-probe seam (LE-1440).\\n\\nThe graph never imports langflow: the runtime (LE-1442) injects a probe that\\nconsults the job's durable signals and answers with a control decision. The\\ndefault no-op keeps standalone lfx running without ever pausing.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections.abc import Awaitable, Callable\\nfrom typing import Literal\\n\\nPauseDecision = Literal[\\\"run\\\", \\\"pause\\\", \\\"cancel\\\"]\\nPauseProbe = Callable[[str], Awaitable[str]]\\n\\nRUN: PauseDecision = \\\"run\\\"\\nPAUSE: PauseDecision = \\\"pause\\\"\\nCANCEL: PauseDecision = \\\"cancel\\\"\\n\\n\\nasync def noop_pause_probe(_job_id: str) -> str:\\n    return RUN\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/checkpoint/resume.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e7473116e73d04dad6af2336335c673016afd5be78492954189e392a6bf9e53d\",\"content\":\"\\\"\\\"\\\"Restores a Graph from a GraphCheckpoint and recomputes the resume layer (LE-1440).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections import defaultdict\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.graph.checkpoint.schema import deserialize_value\\nfrom lfx.graph.graph.runnable_vertices_manager import RunnableVerticesManager\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.checkpoint.schema import GraphCheckpoint\\n    from lfx.graph.checkpoint.store import CheckpointStore\\n    from lfx.graph.graph.base import Graph\\n\\n\\ndef compute_resume_layer(graph: Graph) -> list[str]:\\n    \\\"\\\"\\\"Next runnable vertex ids: unbuilt, non-inactivated vertices whose predecessors are all built.\\n\\n    Recomputed from restored per-vertex state instead of a full re-sort, so already-built vertices\\n    are never queued (and never re-executed) on resume. Inactivated vertices (a branch a\\n    ConditionalRouter stopped before the pause) are excluded so resume doesn't revive a dead branch.\\n    \\\"\\\"\\\"\\n    inactivated = graph.inactivated_vertices | graph.conditionally_excluded_vertices | graph._orphaned_tool_vertex_ids()  # noqa: SLF001\\n    built_ids = {vertex.id for vertex in graph.vertices if vertex.built}\\n    layer = [\\n        vertex.id\\n        for vertex in graph.vertices\\n        if not vertex.built\\n        and vertex.id not in inactivated\\n        and all(pred in built_ids for pred in graph.predecessor_map.get(vertex.id, []))\\n    ]\\n    return sorted(layer)\\n\\n\\ndef _restore_run_manager(graph: Graph, checkpoint: GraphCheckpoint) -> None:\\n    run_predecessors: defaultdict[str, list[str]] = defaultdict(list)\\n    run_predecessors.update({k: list(v) for k, v in checkpoint.run_predecessors.items()})\\n    run_map: defaultdict[str, list[str]] = defaultdict(list)\\n    run_map.update({k: list(v) for k, v in checkpoint.run_map.items()})\\n    manager = RunnableVerticesManager.from_dict(\\n        {\\n            \\\"run_map\\\": run_map,\\n            \\\"run_predecessors\\\": run_predecessors,\\n            \\\"vertices_to_run\\\": set(checkpoint.vertices_to_run),\\n            # Vertices interrupted mid-build re-run on resume: back to the runnable pool, not in-flight.\\n            \\\"vertices_being_run\\\": set(),\\n            \\\"ran_at_least_once\\\": set(checkpoint.ran_at_least_once),\\n        }\\n    )\\n    manager.vertices_to_run.update(checkpoint.vertices_being_run)\\n    # from_dict omits cycle_vertices; without this a resumed Loop flow never schedules its loop vertex and hangs.\\n    manager.cycle_vertices = set(graph.cycle_vertices)\\n    graph.run_manager = manager\\n\\n\\ndef _restore_vertices(graph: Graph, checkpoint: GraphCheckpoint) -> None:\\n    from lfx.graph.vertex.base import VertexStates\\n\\n    for vertex_id, vertex_data in checkpoint.vertex_results.items():\\n        try:\\n            vertex = graph.get_vertex(vertex_id)\\n        except ValueError:\\n            continue\\n        vertex.built = vertex_data.built\\n        # Restore ACTIVE/INACTIVE so a branch a ConditionalRouter stopped stays stopped on resume.\\n        if vertex_data.state in VertexStates.__members__:\\n            vertex.state = VertexStates[vertex_data.state]\\n        vertex.results = {k: deserialize_value(v) for k, v in vertex_data.results.items()}\\n        vertex.artifacts = {k: deserialize_value(v) for k, v in vertex_data.artifacts.items()}\\n        if vertex_data.built_object is not None:\\n            vertex.built_object = deserialize_value(vertex_data.built_object)\\n        if vertex_data.built_result is not None:\\n            vertex.built_result = deserialize_value(vertex_data.built_result)\\n\\n\\ndef _unbuild_needed_dropped_producers(graph: Graph) -> None:\\n    \\\"\\\"\\\"Un-build only the opaque-dropped producers an unbuilt consumer will actually read.\\n\\n    A vertex whose live output was dropped to None (Tool/model client) must re-run on resume so a\\n    consumer that re-runs gets a valid input. But re-running one whose consumers are all still built\\n    is wasted work \u2014 and for a producer with side effects (an Agent re-bills its LLM and re-emits its\\n    message), that surfaces as duplicate outputs on every later resume. So drop only those reachable\\n    by an unbuilt successor, iterating to a fixpoint so a dropped producer behind another dropped one\\n    (e.g. a tool feeding an agent) is freed once the agent itself is freed.\\n    \\\"\\\"\\\"\\n    dropped = [\\n        vertex for vertex in graph.vertices if vertex.id in graph.checkpoint_opaque_dropped_ids and not vertex.is_input\\n    ]\\n    changed = True\\n    while changed:\\n        changed = False\\n        built_ids = {vertex.id for vertex in graph.vertices if vertex.built}\\n        for vertex in dropped:\\n            if vertex.built and any(s not in built_ids for s in graph.successor_map.get(vertex.id, [])):\\n                vertex.built = False\\n                changed = True\\n\\n\\ndef resume_graph_with_decision(\\n    checkpoint: GraphCheckpoint, store: CheckpointStore, request_id: str | None, decision: dict\\n) -> Graph:\\n    \\\"\\\"\\\"Restore a paused graph and inject a HITL decision for ``request_id``.\\n\\n    The shared \\\"restore + inject + un-build\\\" seam for HITL resume: rebuild the graph from the\\n    checkpoint, re-attach the store, record the decision (merged with any checkpoint-restored ones),\\n    and un-build the paused vertex so it re-runs and reads the decision. Used by the lfx CLI resume\\n    loop (``lfx.run.hitl``) and the A2A resume path. ``build.py``'s background resume keeps its own\\n    variant (it adds tracing + predecessor re-run on top).\\n    \\\"\\\"\\\"\\n    from lfx.graph.graph.base import Graph\\n\\n    if not request_id:\\n        # No request_id means the decision can't be routed to a paused vertex: it would silently\\n        # vanish (no vertex matches) or crash on the startswith below. Fail loud instead.\\n        msg = \\\"Cannot resume: pause request is missing request_id\\\"\\n        raise RuntimeError(msg)\\n\\n    graph = Graph.resume_from_checkpoint(checkpoint, checkpoint_store=store)\\n    graph.checkpointing_enabled = True\\n    graph.checkpoint_store = store\\n    graph.human_input_decisions = {\\n        **(getattr(graph, \\\"human_input_decisions\\\", {}) or {}),\\n        request_id: decision,\\n    }\\n    for vertex in graph.vertices:\\n        vertex_request_id = f\\\"{vertex.id}:{graph.run_id}\\\"\\n        if request_id == vertex_request_id or request_id.startswith(vertex_request_id + \\\":\\\"):\\n            vertex.built = False\\n    # Re-run the fixpoint after un-building the paused vertex so any opaque-dropped\\n    # producer it consumes is rebuilt instead of restoring a None value.\\n    _unbuild_needed_dropped_producers(graph)\\n    return graph\\n\\n\\ndef restore_graph_from_checkpoint(checkpoint: GraphCheckpoint, *, store: CheckpointStore | None = None) -> Graph:\\n    from lfx.graph.graph.base import Graph\\n\\n    graph = Graph.from_payload(\\n        checkpoint.flow_payload,\\n        flow_id=checkpoint.flow_id,\\n        user_id=checkpoint.user_id,\\n    )\\n    graph.source_flow_id = checkpoint.source_flow_id\\n    if not graph._prepared:  # noqa: SLF001\\n        graph.prepare()\\n    graph.set_run_id(checkpoint.run_id)\\n    if checkpoint.session_id:\\n        graph.session_id = checkpoint.session_id\\n    # Continue under the starting identity; else self.user_id (via graph.user_id) is None\\n    # and str(None) fails UUID parsing for A2A/flow tools (\\\"badly formed hexadecimal UUID string\\\").\\n    if checkpoint.user_id:\\n        graph.user_id = checkpoint.user_id\\n    graph.job_id = checkpoint.job_id\\n    graph.checkpointing_enabled = True\\n    graph.checkpoint_store = store\\n    graph.resumed_from_checkpoint = True\\n    graph.vertices_layers = [list(layer) for layer in checkpoint.vertices_layers]\\n    graph._first_layer = list(checkpoint.first_layer)  # noqa: SLF001\\n    graph._call_order = list(checkpoint.call_order)  # noqa: SLF001\\n    # Without these, every vertex resumes ACTIVE and compute_resume_layer revives a ConditionalRouter-stopped branch.\\n    graph.inactivated_vertices = {str(v) for v in checkpoint.inactivated_vertices}\\n    graph.branch_inactivation_sources = {\\n        str(source): {str(vertex) for vertex in vertices}\\n        for source, vertices in checkpoint.branch_inactivation_sources.items()\\n    }\\n    graph.conditionally_excluded_vertices = {str(v) for v in checkpoint.conditionally_excluded_vertices}\\n    graph.human_input_decisions = dict(checkpoint.human_input_decisions)\\n    graph.activated_vertices = list(checkpoint.activated_vertices)\\n    # Built-at-checkpoint vertices must not have their async generators re-consumed; the output loop skips this set.\\n    graph.checkpoint_restored_built_ids = {vid for vid, vd in checkpoint.vertex_results.items() if vd.built}\\n    # Opaque output (Tool/client) dropped to None re-runs anywhere; the restored None would crash a consumer.\\n    graph.checkpoint_opaque_dropped_ids = {\\n        vid for vid, vd in checkpoint.vertex_results.items() if vd.built and vd.built_object is None\\n    }\\n    _restore_run_manager(graph, checkpoint)\\n    _restore_vertices(graph, checkpoint)\\n    _unbuild_needed_dropped_producers(graph)\\n    graph._run_queue.clear()  # noqa: SLF001\\n    graph._run_queue.extend(compute_resume_layer(graph))  # noqa: SLF001\\n    return graph\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/checkpoint/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ee8674416e89a520b089d01df3c6eab5072c4f2f33527f906a65887d271aa44b\",\"content\":\"\\\"\\\"\\\"Durable checkpoint data model for HITL graph suspend/resume (LE-1440).\\n\\nEvery field must survive a JSON round-trip (the durable store persists\\ncheckpoints as JSON), including the set-typed execution-state fields.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom importlib import import_module\\nfrom typing import Any\\nfrom uuid import uuid4\\n\\nfrom pydantic import BaseModel, Field\\n\\nfrom lfx.log.logger import logger\\n\\n_WIRE_KIND = \\\"__lfx_ser__\\\"\\n\\n\\nclass VertexCheckpointData(BaseModel):\\n    vertex_id: str\\n    built: bool = False\\n    state: str = \\\"ACTIVE\\\"\\n    results: dict[str, Any] = Field(default_factory=dict)\\n    artifacts: dict[str, Any] = Field(default_factory=dict)\\n    built_object: Any = None\\n    built_result: Any = None\\n\\n\\nclass GraphCheckpoint(BaseModel):\\n    checkpoint_id: str = Field(default_factory=lambda: uuid4().hex)\\n    run_id: str\\n    flow_id: str | None = None\\n    # Server-set storage provenance for public flows whose execution uses a virtual flow_id.\\n    source_flow_id: str | None = None\\n    session_id: str | None = None\\n    # The identity the run started under; restored so a resumed run continues as the same\\n    # user (e.g. self.user_id-reading components keep working after a HITL pause).\\n    user_id: str | None = None\\n    job_id: str | None = None\\n    flow_payload: dict[str, Any] = Field(default_factory=dict)\\n    run_map: dict[str, list[str]] = Field(default_factory=dict)\\n    run_predecessors: dict[str, list[str]] = Field(default_factory=dict)\\n    vertices_to_run: set[str] = Field(default_factory=set)\\n    vertices_being_run: set[str] = Field(default_factory=set)\\n    ran_at_least_once: set[str] = Field(default_factory=set)\\n    run_queue: list[str] = Field(default_factory=list)\\n    call_order: list[str] = Field(default_factory=list)\\n    vertices_layers: list[list[str]] = Field(default_factory=list)\\n    first_layer: list[str] = Field(default_factory=list)\\n    inactivated_vertices: set[str] = Field(default_factory=set)\\n    branch_inactivation_sources: dict[str, set[str]] = Field(default_factory=dict)\\n    conditionally_excluded_vertices: set[str] = Field(default_factory=set)\\n    activated_vertices: list[str] = Field(default_factory=list)\\n    vertex_results: dict[str, VertexCheckpointData] = Field(default_factory=dict)\\n    pause_context: dict[str, Any] | None = None\\n    human_input_decisions: dict[str, Any] = Field(default_factory=dict)\\n    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    expires_at: datetime | None = None\\n\\n\\ndef serialize_value(value: Any) -> dict[str, Any] | None:\\n    \\\"\\\"\\\"Encode a built value into a JSON-safe tagged envelope.\\n\\n    Opaque objects (no faithful JSON form) degrade to None rather than raising:\\n    a checkpoint must still be writable when one vertex holds e.g. a client\\n    handle, and resume re-derives such objects from the rebuilt component.\\n\\n    Limitation: paused vertex state that is not JSON-serializable is NOT restored\\n    on resume (it returns as None). A flow that depends on such state downstream of\\n    the pause must re-derive it from the rebuilt node, not from the checkpoint.\\n    \\\"\\\"\\\"\\n    if value is None or isinstance(value, (str, int, float, bool)):\\n        return {_WIRE_KIND: \\\"raw\\\", \\\"value\\\": value}\\n    if isinstance(value, BaseModel):\\n        module = type(value).__module__\\n        # Why: _restore_model only imports lfx.* modules (importing arbitrary modules from stored\\n        # data is injection). A non-lfx model would checkpoint fine but raise TypeError on every\\n        # resume \u2014 leaving the run permanently stuck \u2014 so degrade it to None here for symmetry.\\n        if not module.startswith(\\\"lfx.\\\"):\\n            logger.debug(\\\"checkpoint: dropping non-lfx model %s\\\", type(value).__qualname__)\\n            return None\\n        try:\\n            dumped = value.model_dump(mode=\\\"json\\\")\\n        except Exception:  # noqa: BLE001\\n            # Opaque field (LLM client / model class) can't round-trip; degrade to None.\\n            logger.debug(\\\"checkpoint: dropping non-serializable model %s\\\", type(value).__qualname__)\\n            return None\\n        return {\\n            _WIRE_KIND: \\\"model\\\",\\n            \\\"module\\\": module,\\n            \\\"name\\\": type(value).__qualname__,\\n            \\\"value\\\": dumped,\\n        }\\n    if isinstance(value, dict):\\n        if not all(isinstance(k, str) for k in value):\\n            return None\\n        return {_WIRE_KIND: \\\"dict\\\", \\\"value\\\": {k: serialize_value(v) for k, v in value.items()}}\\n    if isinstance(value, (list, tuple)):\\n        return {_WIRE_KIND: \\\"list\\\", \\\"value\\\": [serialize_value(v) for v in value]}\\n    return None\\n\\n\\ndef wire_has_opaque_drop(wire: Any) -> bool:\\n    \\\"\\\"\\\"True if serialization dropped an opaque member somewhere in the envelope tree.\\n\\n    serialize_value encodes a genuine None as a \\\"raw\\\" envelope but returns a bare None when it\\n    drops an opaque value (e.g. a DataFrame member of a dict). A bare None anywhere therefore means\\n    the value could not be checkpointed faithfully \u2014 the caller must not persist it as built state.\\n    \\\"\\\"\\\"\\n    if wire is None:\\n        return True\\n    if not isinstance(wire, dict):\\n        return False\\n    kind = wire.get(_WIRE_KIND)\\n    payload = wire.get(\\\"value\\\")\\n    if kind == \\\"dict\\\":\\n        return any(wire_has_opaque_drop(v) for v in (payload or {}).values())\\n    if kind == \\\"list\\\":\\n        return any(wire_has_opaque_drop(v) for v in (payload or []))\\n    return False\\n\\n\\ndef deserialize_value(wire: dict[str, Any] | None) -> Any:\\n    if wire is None:\\n        return None\\n    kind = wire.get(_WIRE_KIND)\\n    payload = wire.get(\\\"value\\\")\\n    if kind == \\\"raw\\\":\\n        return payload\\n    if kind == \\\"dict\\\":\\n        return {k: deserialize_value(v) for k, v in (payload or {}).items()}\\n    if kind == \\\"list\\\":\\n        return [deserialize_value(v) for v in (payload or [])]\\n    if kind == \\\"model\\\":\\n        return _restore_model(wire[\\\"module\\\"], wire[\\\"name\\\"], payload)\\n    msg = f\\\"Unknown checkpoint wire kind: {kind!r}\\\"\\n    raise TypeError(msg)\\n\\n\\ndef _restore_model(module_name: str, class_name: str, payload: Any) -> Any:\\n    # Why: the module path is data read back from storage \u2014 importing arbitrary modules from it would be injection.\\n    if not module_name.startswith(\\\"lfx.\\\"):\\n        msg = f\\\"Refusing to restore checkpoint model from non-lfx module {module_name!r}\\\"\\n        raise TypeError(msg)\\n    obj: Any = import_module(module_name)\\n    for part in class_name.split(\\\".\\\"):\\n        obj = getattr(obj, part)\\n    if not (isinstance(obj, type) and issubclass(obj, BaseModel)):\\n        msg = f\\\"{module_name}.{class_name} is not a pydantic model\\\"\\n        raise TypeError(msg)\\n    return obj.model_validate(payload)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/checkpoint/store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"67c8c9f334d7404053e278cd1155f1a3d680b9cdafefc9896c07197643a718a1\",\"content\":\"\\\"\\\"\\\"CheckpointStore contract + in-memory reference implementation (LE-1440).\\n\\nThe in-memory store is the standalone/test default; the durable DB-backed\\nstore lands in LE-1441 behind this same interface.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom abc import ABC, abstractmethod\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.checkpoint.schema import GraphCheckpoint\\n\\n\\nclass CheckpointStore(ABC):\\n    @abstractmethod\\n    async def save(self, checkpoint: GraphCheckpoint) -> None: ...\\n\\n    @abstractmethod\\n    async def load(self, checkpoint_id: str) -> GraphCheckpoint | None: ...\\n\\n    @abstractmethod\\n    async def delete(self, checkpoint_id: str) -> None: ...\\n\\n    @abstractmethod\\n    async def load_by_run_id(self, run_id: str) -> GraphCheckpoint | None: ...\\n\\n    @abstractmethod\\n    async def list_by_session(self, session_id: str) -> list[GraphCheckpoint]: ...\\n\\n    async def save_blob(self, job_id: str, kind: str, blob: str) -> None:\\n        \\\"\\\"\\\"Persist an opaque per-run blob keyed by ``(job_id, kind)``.\\n\\n        Used by the agent tool-approval saver (LE-1447, kind='agent'), separate from\\n        the graph checkpoint. The default is in-memory (standalone/CLI); the durable\\n        store overrides it to write the job-scoped table.\\n        \\\"\\\"\\\"\\n        if not hasattr(self, \\\"_blobs\\\"):\\n            self._blobs: dict[tuple[str, str], str] = {}\\n        self._blobs[(job_id, kind)] = blob\\n\\n    async def load_blob(self, job_id: str, kind: str) -> str | None:\\n        \\\"\\\"\\\"Return the blob stored for ``(job_id, kind)``, or None.\\\"\\\"\\\"\\n        return getattr(self, \\\"_blobs\\\", {}).get((job_id, kind))\\n\\n\\ndef _expired(checkpoint: GraphCheckpoint) -> bool:\\n    return checkpoint.expires_at is not None and checkpoint.expires_at <= datetime.now(timezone.utc)\\n\\n\\nclass InMemoryCheckpointStore(CheckpointStore):\\n    def __init__(self) -> None:\\n        self._checkpoints: dict[str, GraphCheckpoint] = {}\\n\\n    async def save(self, checkpoint: GraphCheckpoint) -> None:\\n        self._checkpoints[checkpoint.checkpoint_id] = checkpoint\\n\\n    async def load(self, checkpoint_id: str) -> GraphCheckpoint | None:\\n        checkpoint = self._checkpoints.get(checkpoint_id)\\n        if checkpoint is None or _expired(checkpoint):\\n            return None\\n        return checkpoint\\n\\n    async def delete";
